// Status badge — color via tone prop
function Badge({
  tone = "neutral",
  children,
  dot = false,
  soft = true,
  style,
}) {
  const tones = {
    neutral: ["#EEF2F7", "#475569", "#94A3B8"],
    blue: ["#EEF3FF", "#1842A6", "#3B6BE6"],
    green: ["#E6F6EE", "#0E8A4D", "#22B86C"],
    amber: ["#FFF3DC", "#A86A00", "#E5A33A"],
    red: ["#FDECEC", "#C0303A", "#E66670"],
    violet: ["#EFEBFF", "#5B4BD1", "#8C7DEB"],
    teal: ["#DEF3F0", "#0E7C77", "#3CB1AB"],
    ink: ["#E2E8F0", "#1E2A47", "#475569"],
  };
  const [bg, fg, dotC] = tones[tone] || tones.neutral;
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        padding: "2px 8px",
        borderRadius: 999,
        background: soft ? bg : "transparent",
        color: fg,
        fontSize: 12,
        lineHeight: "18px",
        fontWeight: 500,
        whiteSpace: "nowrap",
        border: soft ? "none" : `1px solid ${dotC}`,
        ...style,
      }}
    >
      {dot && (
        <span
          style={{ width: 6, height: 6, borderRadius: 999, background: dotC }}
        />
      )}
      {children}
    </span>
  );
}

// Solid Status pill with vertical line accent — for table status columns
function StatusPill({ tone = "neutral", children }) {
  const tones = {
    neutral: ["#64748B"],
    blue: ["#1E50C8"],
    green: ["#0E8A4D"],
    amber: ["#C58A1A"],
    red: ["#C0303A"],
    violet: ["#5B4BD1"],
    teal: ["#0E7C77"],
  };
  const [c] = tones[tone] || tones.neutral;
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 8,
        fontSize: 13,
        color: "var(--ink-700)",
      }}
    >
      <span
        style={{
          width: 6,
          height: 6,
          borderRadius: 999,
          background: c,
          boxShadow: `0 0 0 3px ${c}22`,
        }}
      />
      {children}
    </span>
  );
}

function Button({
  kind = "default",
  size = "md",
  children,
  icon,
  onClick,
  disabled,
  style,
  type = "button",
}) {
  const sizes = {
    sm: { h: 26, px: 10, fs: 12, gap: 4 },
    md: { h: 32, px: 12, fs: 13, gap: 6 },
    lg: { h: 38, px: 16, fs: 14, gap: 8 },
  };
  const s = sizes[size];
  const kinds = {
    primary: {
      bg: "var(--blue-600)",
      color: "#fff",
      border: "1px solid var(--blue-600)",
      hover: "var(--blue-700)",
    },
    default: {
      bg: "#fff",
      color: "var(--ink-700)",
      border: "1px solid var(--line-strong)",
      hover: "#F4F6FB",
    },
    ghost: {
      bg: "transparent",
      color: "var(--ink-500)",
      border: "1px solid transparent",
      hover: "#EEF2F7",
    },
    danger: {
      bg: "#fff",
      color: "var(--danger-600)",
      border: "1px solid #F3C4C9",
      hover: "#FDECEC",
    },
    link: {
      bg: "transparent",
      color: "var(--blue-600)",
      border: "none",
      hover: "transparent",
    },
  };
  const k = kinds[kind];
  const [hover, setHover] = React.useState(false);
  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        height: s.h,
        padding: `0 ${s.px}px`,
        fontSize: s.fs,
        background: hover && !disabled ? k.hover : k.bg,
        color: k.color,
        border: k.border,
        borderRadius: 6,
        cursor: disabled ? "not-allowed" : "pointer",
        display: "inline-flex",
        alignItems: "center",
        gap: s.gap,
        fontWeight: 500,
        opacity: disabled ? 0.55 : 1,
        transition: "background 100ms ease",
        whiteSpace: "nowrap",
        ...style,
      }}
    >
      {icon}
      {children}
    </button>
  );
}

