// Avatar — 头像图片优先；无图时回退到自定义字标（支持 emoji），再回退姓名首字
function Avatar({ name, text, imageUrl, size = 28, tone }) {
  const palette = [
    "#1E50C8",
    "#5B4BD1",
    "#0E7C77",
    "#A86A00",
    "#C0303A",
    "#0E8A4D",
  ];
  const image = typeof imageUrl === "string" ? imageUrl.trim() : "";
  if (image) {
    return (
      <img
        src={image}
        alt={name ? `${name} 的头像` : "头像"}
        style={{
          width: size,
          height: size,
          borderRadius: 999,
          objectFit: "cover",
          flexShrink: 0,
          display: "inline-block",
        }}
      />
    );
  }
  const code = (name || "?").split("").reduce((a, c) => a + c.charCodeAt(0), 0);
  const bg = tone || palette[code % palette.length];
  const custom = typeof text === "string" ? text.trim() : "";
  const display = custom || Array.from(name || "?")[0] || "?";
  const displayLength = Array.from(display).length;
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        width: size,
        height: size,
        borderRadius: 999,
        background: `${bg}18`,
        color: bg,
        fontSize: displayLength > 1 ? size * 0.34 : size * 0.42,
        fontWeight: 600,
        flexShrink: 0,
      }}
    >
      {display}
    </span>
  );
}

// 客户端把用户选的图片压到 256px 见方的 JPEG data URL，控制体积（一般 10-30KB）。
// 居中裁剪成正方形，避免头像被拉伸。
const AVATAR_IMAGE_MAX_SIZE = 256;
function compressAvatarImage(file) {
  return new Promise((resolve, reject) => {
    if (!file || !/^image\/(png|jpeg)$/.test(file.type)) {
      reject(new Error("仅支持 PNG 或 JPG 图片。"));
      return;
    }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("图片读取失败，请重试。"));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("图片解码失败，请换一张。"));
      img.onload = () => {
        const side = Math.min(img.naturalWidth, img.naturalHeight) || 1;
        const sx = (img.naturalWidth - side) / 2;
        const sy = (img.naturalHeight - side) / 2;
        const target = Math.min(AVATAR_IMAGE_MAX_SIZE, side);
        const canvas = document.createElement("canvas");
        canvas.width = target;
        canvas.height = target;
        const ctx = canvas.getContext("2d");
        if (!ctx) {
          reject(new Error("当前浏览器不支持图片压缩。"));
          return;
        }
        ctx.drawImage(img, sx, sy, side, side, 0, 0, target, target);
        resolve(canvas.toDataURL("image/jpeg", 0.82));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

// Tabular: header + body. Pass columns + rows as React-friendly arrays.
function DataTable({
  columns,
  rows,
  dense = false,
  onRowClick,
  activeRowId,
  emptyText = "暂无数据",
  // 行内抽屉：expandedRowId 命中的行会在其正下方渲染 renderExpanded(row)，
  // 让明细跟随所点的行展开，而不是跳到页面其他位置。
  renderExpanded,
  expandedRowId,
  // 行 id 默认取 row.id；行 id 藏在嵌套字段（如 board.project.id）时传入访问器。
  rowId,
}) {
  return (
    <div
      className="ops-data-table-scroll"
      style={{ width: "100%", overflow: "auto" }}
    >
      <table
        style={{
          width: "100%",
          borderCollapse: "separate",
          borderSpacing: 0,
          fontSize: 13,
          color: "var(--ink-700)",
        }}
      >
        <thead>
          <tr>
            {columns.map((c, i) => (
              <th
                key={i}
                style={{
                  position: "sticky",
                  top: 0,
                  zIndex: 1,
                  background: "var(--bg-soft)",
                  textAlign: c.align || "left",
                  fontWeight: 500,
                  fontSize: 12,
                  color: "var(--ink-400)",
                  padding: dense ? "8px 12px" : "10px 14px",
                  borderBottom: "1px solid var(--line)",
                  width: c.width,
                  whiteSpace: "nowrap",
                }}
              >
                {c.title}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 && (
            <tr>
              <td
                colSpan={columns.length}
                style={{
                  padding: 48,
                  textAlign: "center",
                  color: "var(--ink-400)",
                }}
              >
                {emptyText}
              </td>
            </tr>
          )}
          {rows.map((r, i) => {
            const rid = rowId ? rowId(r) : r.id;
            const expanded =
              Boolean(renderExpanded) && rid != null && expandedRowId === rid;
            const highlighted =
              (rid != null && activeRowId === rid) || expanded;
            return (
              <React.Fragment key={rid ?? i}>
                <tr
                  onClick={onRowClick ? () => onRowClick(r) : undefined}
                  style={{
                    background: highlighted ? "var(--blue-50)" : "transparent",
                    cursor: onRowClick ? "pointer" : "default",
                  }}
                  onMouseEnter={(e) => {
                    if (onRowClick && !highlighted)
                      e.currentTarget.style.background = "#F7F9FD";
                  }}
                  onMouseLeave={(e) => {
                    if (onRowClick && !highlighted)
                      e.currentTarget.style.background = "transparent";
                  }}
                >
                  {columns.map((c, j) => (
                    <td
                      key={j}
                      style={{
                        padding: dense ? "8px 12px" : "12px 14px",
                        textAlign: c.align || "left",
                        borderBottom: expanded
                          ? "none"
                          : "1px solid var(--line)",
                        verticalAlign: c.valign || "middle",
                        whiteSpace: c.wrap ? "normal" : "nowrap",
                        color: c.muted ? "var(--ink-400)" : "var(--ink-700)",
                      }}
                    >
                      {c.render ? c.render(r, i) : r[c.key]}
                    </td>
                  ))}
                </tr>
                {expanded ? (
                  <tr>
                    <td
                      colSpan={columns.length}
                      style={{
                        padding: 0,
                        background: "var(--bg-soft)",
                        borderBottom: "1px solid var(--line)",
                      }}
                    >
                      {renderExpanded(r)}
                    </td>
                  </tr>
                ) : null}
              </React.Fragment>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// Metric block — large number with label + delta
function Metric({
  label,
  value,
  unit,
  delta,
  deltaTone = "green",
  hint,
  accent,
}) {
  return (
    <div
      style={{ display: "flex", flexDirection: "column", gap: 6, minWidth: 0 }}
    >
      <div
        style={{
          fontSize: 12,
          color: "var(--ink-400)",
          display: "flex",
          alignItems: "center",
          gap: 6,
        }}
      >
        {accent}
        {label}
      </div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
        <span
          className="num"
          style={{
            fontSize: 24,
            fontWeight: 600,
            color: "var(--ink-900)",
            letterSpacing: "-0.02em",
            whiteSpace: "nowrap",
          }}
        >
          {value}
        </span>
        {unit && (
          <span
            style={{
              fontSize: 12,
              color: "var(--ink-400)",
              whiteSpace: "nowrap",
            }}
          >
            {unit}
          </span>
        )}
      </div>
      {(delta || hint) && (
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            flexWrap: "wrap",
            rowGap: 2,
          }}
        >
          {delta && (
            <span
              className="num"
              style={{
                fontSize: 12,
                fontWeight: 500,
                whiteSpace: "nowrap",
                color:
                  deltaTone === "green"
                    ? "var(--ok-600)"
                    : deltaTone === "red"
                      ? "var(--danger-600)"
                      : "var(--ink-400)",
              }}
            >
              {delta}
            </span>
          )}
          {hint && (
            <span
              style={{
                fontSize: 12,
                color: "var(--ink-400)",
                whiteSpace: "nowrap",
              }}
            >
              {hint}
            </span>
          )}
        </div>
      )}
    </div>
  );
}

