const OPS_FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  "summary",
  '[tabindex]:not([tabindex="-1"])',
].join(", ");

function isVisiblyTabbableWithin(element, boundary) {
  if (!element || element.tabIndex < 0) return false;

  for (
    let current = element;
    current && boundary?.contains(current);
    current = current.parentElement
  ) {
    if (
      current.hidden ||
      current.getAttribute?.("aria-hidden") === "true" ||
      current.hasAttribute?.("inert")
    ) {
      return false;
    }

    if (current.tagName === "DETAILS" && !current.open) {
      const summary = Array.from(current.children).find(
        (child) => child.tagName === "SUMMARY",
      );
      if (!summary?.contains(element)) return false;
    }

    const style = globalThis.getComputedStyle?.(current);
    const isOpenDrawerCloseButton =
      current === element &&
      element.classList?.contains("ops-sidebar-close") &&
      boundary?.dataset.open === "true";
    if (
      !isOpenDrawerCloseButton &&
      (style?.display === "none" ||
        style?.visibility === "hidden" ||
        style?.visibility === "collapse")
    ) {
      return false;
    }

    if (current === boundary) break;
  }

  return true;
}

function isRestorableFocusTarget(element) {
  const body = globalThis.document?.body;
  const isMobile = Boolean(
    globalThis.matchMedia?.(OPS_MOBILE_NAVIGATION_QUERY).matches,
  );
  if (element?.classList?.contains("ops-mobile-nav-trigger")) {
    return Boolean(element.isConnected && isMobile);
  }
  const sidebar = element?.closest?.(".ops-reference-sidebar");
  if (sidebar && isMobile && sidebar.dataset.open !== "true") return false;

  return Boolean(
    element?.isConnected &&
      body?.contains(element) &&
      isVisiblyTabbableWithin(element, body),
  );
}

const bodySiblingIsolationRegistry = new WeakMap();

function acquireBodySiblingIsolation(element) {
  const existingState = bodySiblingIsolationRegistry.get(element);
  if (existingState) {
    existingState.ownerCount += 1;
    return;
  }

  bodySiblingIsolationRegistry.set(element, {
    ownerCount: 1,
    inert: element.getAttribute("inert"),
    ariaHidden: element.getAttribute("aria-hidden"),
  });
  element.setAttribute("inert", "");
  element.setAttribute("aria-hidden", "true");
}

function releaseBodySiblingIsolation(element) {
  const state = bodySiblingIsolationRegistry.get(element);
  if (!state) return;

  state.ownerCount -= 1;
  if (state.ownerCount > 0) return;

  bodySiblingIsolationRegistry.delete(element);
  if (state.inert == null) element.removeAttribute("inert");
  else element.setAttribute("inert", state.inert);
  if (state.ariaHidden == null) element.removeAttribute("aria-hidden");
  else element.setAttribute("aria-hidden", state.ariaHidden);
}

function useModalLayerIsolation(layerRef, onActivate, onRestore) {
  React.useLayoutEffect(() => {
    const body = globalThis.document?.body;
    const layer = layerRef.current;
    if (!body || !layer) return undefined;

    const siblings = Array.from(body.children).filter(
      (element) => element !== layer,
    );

    siblings.forEach(acquireBodySiblingIsolation);
    onActivate?.();

    return () => {
      siblings.forEach(releaseBodySiblingIsolation);
      onRestore?.();
    };
  }, [layerRef, onActivate, onRestore]);
}

export function Sidebar({
  route,
  onNav,
  navCounts = {},
  currentUser,
  organizationSettings,
  organizationMembers,
  onOpenOrganizationSettings,
  onUpdateAvatar,
  mobileNavigationOpen = false,
  onCloseMobileNavigation,
  onPrepareOverlay,
  mobileCloseButtonRef,
  mobileDrawerRef,
  mobileNavigationTriggerRef,
}) {
  const displayUser = normalizeCurrentUser(currentUser);
  const orgSettings = normalizeOrganizationSettings(organizationSettings);
  const enabledFeatureCount = countEnabledOrganizationFeatures(orgSettings);
  const memberCount = Array.isArray(organizationMembers)
    ? organizationMembers.length
    : null;
  const [accountPanel, setAccountPanel] = React.useState(null);
  const accountSummaryRef = React.useRef(null);
  const accountPanelWasOpenRef = React.useRef(false);
  const switcherMemberText =
    memberCount != null
      ? `当前组织 · ${memberCount} 名成员`
      : orgSettings.memberLimit != null
        ? `当前组织 · 配额 ${orgSettings.memberLimit}`
        : "当前组织 · 设置与权限";

  React.useLayoutEffect(() => {
    if (accountPanel) {
      accountPanelWasOpenRef.current = true;
      return;
    }
    if (!accountPanelWasOpenRef.current) return;

    accountPanelWasOpenRef.current = false;
    const isMobile = Boolean(
      globalThis.matchMedia?.(OPS_MOBILE_NAVIGATION_QUERY).matches,
    );
    const focusTarget = isMobile
      ? mobileNavigationTriggerRef?.current
      : accountSummaryRef.current;
    focusTarget?.focus();
  }, [accountPanel, mobileNavigationTriggerRef]);

  const openAccountPanel = (mode) => {
    onPrepareOverlay?.();
    setAccountPanel(mode);
  };

  return (
    <aside
      ref={mobileDrawerRef}
      id="ops-sidebar-drawer"
      className="ops-reference-sidebar"
      aria-label="主导航"
      data-open={mobileNavigationOpen ? "true" : "false"}
      style={{
        width: 232,
        flexShrink: 0,
        background: "#fff",
        borderRight: "1px solid var(--line)",
        display: "flex",
        flexDirection: "column",
        height: "100vh",
        position: "sticky",
        top: 0,
      }}
    >
      {/* Logo */}
      <div
        style={{
          height: 56,
          display: "flex",
          alignItems: "center",
          gap: 10,
          padding: "0 18px",
          borderBottom: "1px solid var(--line)",
        }}
      >
        <div
          aria-label="组织 LOGO"
          style={{
            width: 32,
            height: 32,
            borderRadius: 7,
            background: "linear-gradient(135deg, #1E50C8 0%, #3B6BE6 100%)",
            color: "#fff",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontWeight: 700,
            fontSize: 13,
            letterSpacing: "-0.04em",
            boxShadow: "0 2px 6px rgba(30,80,200,0.35)",
            overflow: "hidden",
          }}
        >
          {orgSettings.logoImage &&
          orgSettings.logoText === DEFAULT_ORGANIZATION_SETTINGS.logoText ? (
            <img
              src={orgSettings.logoImage}
              alt="经营舱品牌标识"
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                display: "block",
              }}
            />
          ) : (
            orgSettings.logoText
          )}
        </div>
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            minWidth: 0,
            lineHeight: 1.15,
          }}
        >
          <span
            style={{
              fontWeight: 700,
              fontSize: 14,
              color: "var(--ink-900)",
              letterSpacing: "-0.005em",
            }}
          >
            {orgSettings.brandName}
          </span>
          <span
            style={{
              fontSize: 10.5,
              color: "var(--ink-400)",
              letterSpacing: "0.04em",
            }}
          >
            {orgSettings.brandTagline}
          </span>
        </div>
        <button
          ref={mobileCloseButtonRef}
          type="button"
          className="ops-sidebar-close"
          aria-label="关闭主导航"
          title="关闭主导航"
          onClick={onCloseMobileNavigation}
          style={{
            display: "none",
            width: 44,
            height: 44,
            flex: "0 0 44px",
            marginLeft: "auto",
            alignItems: "center",
            justifyContent: "center",
            border: "none",
            borderRadius: 8,
            background: "transparent",
            color: "var(--ink-500)",
            cursor: "pointer",
          }}
        >
          <XIcon size={20} aria-hidden="true" />
        </button>
      </div>

      {/* Org switcher */}
      <button
        type="button"
        onClick={onOpenOrganizationSettings}
        style={{
          margin: "12px 12px 8px",
          padding: "10px 12px",
          minWidth: 0,
          background: "var(--bg-soft)",
          border: "1px solid var(--line)",
          borderRadius: 8,
          display: "flex",
          alignItems: "center",
          gap: 10,
          cursor: "pointer",
        }}
      >
        <span
          data-org-switcher-mark="true"
          style={{
            width: 28,
            height: 28,
            flexShrink: 0,
            borderRadius: 7,
            background: "var(--blue-50)",
            color: "var(--blue-700)",
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            fontWeight: 700,
            fontSize: 12,
          }}
        >
          星
        </span>
        <div
          data-org-switcher-content="true"
          style={{
            flex: "1 1 auto",
            minWidth: 0,
            display: "flex",
            flexDirection: "column",
            rowGap: 2,
            textAlign: "left",
          }}
        >
          <div
            style={{
              fontSize: 13,
              fontWeight: 600,
              color: "var(--ink-900)",
              lineHeight: 1.2,
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
            }}
          >
            {orgSettings.name}
          </div>
          <div
            style={{
              fontSize: 10.5,
              color: "var(--ink-400)",
              lineHeight: 1.25,
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
            }}
          >
            {switcherMemberText}
          </div>
          <div
            style={{
              fontSize: 10.5,
              color: "var(--blue-600)",
              lineHeight: 1.25,
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
            }}
          >
            已启用 {enabledFeatureCount} 项功能
          </div>
        </div>
        <span
          data-org-switcher-chevron="true"
          style={{
            width: 18,
            height: 18,
            flexShrink: 0,
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <Icon.ChevDown size={14} stroke="var(--ink-400)" />
        </span>
      </button>

      {/* Nav */}
      <nav style={{ padding: "4px 8px", flex: 1, overflowY: "auto" }}>
        {NAV.map((it, i) => {
          if (it.divider) {
            return (
              <div
                key={"d" + i}
                style={{
                  height: 1,
                  margin: "10px 12px",
                  background: "var(--line)",
                }}
              />
            );
          }
          const active = it.key === route;
          const IconComp = Icon[it.icon];
          const count = navCounts[it.key] ?? 0;
          // 徽标数是全组织口径（非当前项目），在可访问名/悬浮提示里点明。
          const badgeLabel =
            count > 0
              ? `${it.label}，全组织待办 ${formatBadgeCount(count)} 项`
              : undefined;
          return (
            <button
              key={it.key}
              title={badgeLabel}
              aria-label={badgeLabel}
              onClick={() =>
                it.href ? window.location.assign(it.href) : onNav(it.key)
              }
              style={{
                width: "100%",
                padding: "0 10px",
                height: 34,
                display: "flex",
                alignItems: "center",
                gap: 10,
                background: active ? "var(--blue-50)" : "transparent",
                border: "none",
                borderRadius: 6,
                cursor: "pointer",
                color: active ? "var(--blue-700)" : "var(--ink-500)",
                fontWeight: active ? 600 : 500,
                fontSize: 13,
                position: "relative",
                marginBottom: 2,
              }}
              onMouseEnter={(e) => {
                if (!active) e.currentTarget.style.background = "var(--ink-50)";
              }}
              onMouseLeave={(e) => {
                if (!active) e.currentTarget.style.background = "transparent";
              }}
            >
              {active && (
                <span
                  style={{
                    position: "absolute",
                    left: -8,
                    top: 8,
                    bottom: 8,
                    width: 3,
                    borderRadius: 999,
                    background: "var(--blue-600)",
                  }}
                />
              )}
              <IconComp
                size={16}
                stroke={active ? "var(--blue-700)" : "var(--ink-400)"}
              />
              <span style={{ flex: 1, textAlign: "left" }}>{it.label}</span>
              {count > 0 && (
                <span
                  style={{
                    fontSize: 11,
                    fontWeight: 600,
                    padding: "0 6px",
                    height: 16,
                    background: active ? "var(--blue-600)" : "#E1E7F0",
                    color: active ? "#fff" : "var(--ink-500)",
                    borderRadius: 999,
                    display: "inline-flex",
                    alignItems: "center",
                    minWidth: 16,
                  }}
                >
                  {formatBadgeCount(count)}
                </span>
              )}
              {it.accent && !active && (
                <span
                  style={{
                    fontSize: 10,
                    padding: "0 5px",
                    height: 16,
                    lineHeight: "16px",
                    background: "linear-gradient(135deg, #EFEBFF, #DCE6FF)",
                    color: "var(--violet-600)",
                    borderRadius: 4,
                    fontWeight: 600,
                  }}
                >
                  AI
                </span>
              )}
            </button>
          );
        })}
      </nav>

      {/* User */}
      <div
        style={{
          position: "relative",
          padding: "10px 12px",
          borderTop: "1px solid var(--line)",
        }}
      >
        <details
          style={{ position: "relative" }}
          onClick={(event) => {
            if (event.target?.closest?.("[data-account-menu-close]")) {
              event.currentTarget.removeAttribute("open");
            }
          }}
        >
          <summary
            ref={accountSummaryRef}
            role="button"
            aria-haspopup="menu"
            aria-label={`${displayUser.name} ${formatCurrentUserMeta(displayUser)} 账号菜单`}
            style={{
              listStyle: "none",
              width: "100%",
              border: "1px solid transparent",
              background: "transparent",
              borderRadius: 8,
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: 10,
              padding: "8px 6px",
              textAlign: "left",
            }}
          >
            <Avatar
              name={displayUser.name}
              text={displayUser.avatarText}
              imageUrl={displayUser.avatarUrl}
              size={32}
            />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 600,
                  color: "var(--ink-900)",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                }}
              >
                {displayUser.name}
              </div>
              <div
                style={{
                  fontSize: 11,
                  color: "var(--ink-400)",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                }}
              >
                {formatCurrentUserMeta(displayUser)}
              </div>
            </div>
            <Icon.ChevDown
              size={14}
              stroke="var(--ink-400)"
              style={{
                transition: "transform 120ms ease",
              }}
            />
          </summary>

          <div
            role="menu"
            aria-label="账号菜单"
            style={{
              position: "absolute",
              left: 12,
              right: 12,
              bottom: 66,
              zIndex: 30,
              padding: 6,
              borderRadius: 8,
              border: "1px solid var(--line)",
              background: "#fff",
              boxShadow: "0 16px 40px rgba(15,23,42,0.14)",
            }}
          >
            <AccountMenuItem
              icon={<Icon.Streamer size={14} />}
              label="个人资料"
              closeMenu
              onClick={() => {
                openAccountPanel("profile");
              }}
            />
            <AccountMenuItem
              icon={<Icon.Lock size={14} />}
              label="账号安全"
              closeMenu
              onClick={() => {
                openAccountPanel("security");
              }}
            />
            <AccountMenuItem
              icon={<Icon.Settings size={14} />}
              label="组织设置"
              closeMenu
              onClick={() => {
                onOpenOrganizationSettings?.(accountSummaryRef.current);
              }}
            />
            <div
              style={{
                height: 1,
                background: "var(--line)",
                margin: "6px 4px",
              }}
            />
            <form action="/api/auth/signout" method="post">
              <AccountMenuItem
                icon={<Icon.Logout size={14} stroke="var(--danger-600)" />}
                label="退出登录"
                danger
                submit
              />
            </form>
          </div>
        </details>
      </div>

      {accountPanel ? (
        <AccountPanelDialog
          mode={accountPanel}
          currentUser={displayUser}
          onClose={() => setAccountPanel(null)}
          onUpdateAvatar={onUpdateAvatar}
        />
      ) : null}
    </aside>
  );
}

function AccountMenuItem({
  icon,
  label,
  onClick,
  danger = false,
  submit = false,
  closeMenu = false,
}) {
  return (
    <button
      type={submit ? "submit" : "button"}
      role="menuitem"
      data-account-menu-close={closeMenu ? "true" : undefined}
      onClick={onClick}
      style={{
        width: "100%",
        minHeight: 34,
        border: "none",
        borderRadius: 6,
        background: "transparent",
        color: danger ? "var(--danger-600)" : "var(--ink-700)",
        cursor: "pointer",
        display: "flex",
        alignItems: "center",
        gap: 9,
        padding: "0 9px",
        fontSize: 13,
        fontWeight: 500,
        textAlign: "left",
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.background = danger ? "#FDECEC" : "var(--ink-50)";
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.background = "transparent";
      }}
    >
      <span
        style={{
          width: 16,
          height: 16,
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          color: danger ? "var(--danger-600)" : "var(--ink-400)",
        }}
      >
        {icon}
      </span>
      <span>{label}</span>
    </button>
  );
}

function AccountPanelDialog({ mode, currentUser, onClose, onUpdateAvatar }) {
  const title = mode === "security" ? "账号安全" : "个人资料";
  const [avatarDraft, setAvatarDraft] = React.useState(
    currentUser.avatarText || "",
  );
  const [avatarUrlDraft, setAvatarUrlDraft] = React.useState(
    currentUser.avatarUrl || "",
  );
  const [avatarBusy, setAvatarBusy] = React.useState(false);
  const [avatarMessage, setAvatarMessage] = React.useState("");
  const fileInputRef = React.useRef(null);
  const closeButtonRef = React.useRef(null);
  const dialogRef = React.useRef(null);

  React.useLayoutEffect(() => {
    closeButtonRef.current?.focus();
  }, []);

  const handleDialogKeyDown = (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      onClose?.();
      return;
    }
    if (event.key !== "Tab") return;

    const dialogElement = dialogRef.current;
    if (!dialogElement) return;
    const focusable = Array.from(
      dialogElement.querySelectorAll(OPS_FOCUSABLE_SELECTOR),
    ).filter((element) => isVisiblyTabbableWithin(element, dialogElement));
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (!first || !last) {
      event.preventDefault();
      return;
    }

    const activeElement = globalThis.document?.activeElement;
    if (event.shiftKey && activeElement === first) {
      event.preventDefault();
      event.stopPropagation();
      last.focus();
      return;
    }
    if (!event.shiftKey && activeElement === last) {
      event.preventDefault();
      event.stopPropagation();
      first.focus();
    }
  };

  const pickImage = async (event) => {
    const file = event.target.files?.[0];
    // 清空 value，让用户再次选同一张图也能触发 change。
    event.target.value = "";
    if (!file) return;
    setAvatarBusy(true);
    setAvatarMessage("");
    try {
      const dataUrl = await compressAvatarImage(file);
      setAvatarUrlDraft(dataUrl);
    } catch (error) {
      setAvatarMessage(error?.message || "图片处理失败，请换一张。");
    } finally {
      setAvatarBusy(false);
    }
  };

  const saveAvatar = async () => {
    setAvatarBusy(true);
    setAvatarMessage("");
    try {
      await onUpdateAvatar?.({
        avatarText: sliceByCodePoints(avatarDraft.trim(), 4),
        avatarUrl: avatarUrlDraft,
      });
      setAvatarMessage("头像已更新。");
    } catch (error) {
      setAvatarMessage(error?.message || "保存头像失败，请稍后重试。");
    } finally {
      setAvatarBusy(false);
    }
  };

  const dialog = (
    <div
      ref={dialogRef}
      role="dialog"
      aria-modal="true"
      aria-label={title}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 120,
        background: "rgba(15,23,42,0.24)",
        display: "grid",
        placeItems: "center",
        padding: 20,
      }}
      onClick={onClose}
      onKeyDown={handleDialogKeyDown}
    >
      <div
        style={{
          width: 420,
          maxWidth: "100%",
          borderRadius: 8,
          background: "#fff",
          boxShadow: "0 24px 60px rgba(15,23,42,0.22)",
          border: "1px solid var(--line)",
          overflow: "hidden",
        }}
        onClick={(e) => e.stopPropagation()}
      >
        <div
          style={{
            padding: "16px 18px",
            borderBottom: "1px solid var(--line)",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 12,
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <Avatar
              name={currentUser.name}
              text={mode === "profile" ? avatarDraft.trim() : currentUser.avatarText}
              imageUrl={
                mode === "profile" ? avatarUrlDraft : currentUser.avatarUrl
              }
              size={34}
            />
            <div>
              <div
                style={{
                  fontSize: 15,
                  fontWeight: 700,
                  color: "var(--ink-900)",
                }}
              >
                {title}
              </div>
              <div style={{ fontSize: 12, color: "var(--ink-400)" }}>
                {currentUser.name}
              </div>
            </div>
          </div>
          <button
            ref={closeButtonRef}
            type="button"
            aria-label="关闭"
            onClick={onClose}
            style={{
              width: 30,
              height: 30,
              border: "1px solid var(--line)",
              borderRadius: 6,
              background: "#fff",
              cursor: "pointer",
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Icon.X size={14} />
          </button>
        </div>
        <div style={{ padding: 18, display: "grid", gap: 12 }}>
          {mode === "security" ? (
            <>
              <KV label="登录密码">已启用</KV>
              <KV label="双因素认证">待接入账号系统</KV>
              <KV label="登录设备">当前浏览器会话</KV>
            </>
          ) : (
            <>
              <KV label="姓名">{currentUser.name}</KV>
              <KV label="角色">
                {ROLES[currentUser.role] ?? ROLES[DEFAULT_CURRENT_USER.role]}
              </KV>
              <KV label="组织">{currentUser.dept || "未配置组织"}</KV>
              <KV label="头像图片">
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: 6,
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 10,
                      flexWrap: "wrap",
                    }}
                  >
                    <Avatar
                      name={currentUser.name}
                      text={avatarDraft.trim()}
                      imageUrl={avatarUrlDraft}
                      size={44}
                    />
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept="image/png,image/jpeg"
                      aria-label="上传头像图片"
                      onChange={pickImage}
                      style={{ display: "none" }}
                    />
                    <Button
                      kind="default"
                      size="sm"
                      disabled={avatarBusy}
                      onClick={() => fileInputRef.current?.click()}
                    >
                      上传图片
                    </Button>
                    {avatarUrlDraft ? (
                      <Button
                        kind="ghost"
                        size="sm"
                        disabled={avatarBusy}
                        onClick={() => setAvatarUrlDraft("")}
                      >
                        移除图片
                      </Button>
                    ) : null}
                  </div>
                  <span style={{ fontSize: 11.5, color: "var(--ink-400)" }}>
                    支持 PNG / JPG，自动压缩到 256px 见方。
                  </span>
                </div>
              </KV>
              <KV label="头像字标">
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: 6,
                  }}
                >
                  <input
                    aria-label="头像字标"
                    value={avatarDraft}
                    maxLength={8}
                    disabled={!!avatarUrlDraft}
                    onChange={(event) => setAvatarDraft(event.target.value)}
                    placeholder={Array.from(currentUser.name || "?")[0] || "?"}
                    style={{
                      width: 120,
                      height: 30,
                      padding: "0 10px",
                      border: "1px solid var(--line-strong)",
                      borderRadius: 6,
                      fontSize: 13,
                      background: avatarUrlDraft ? "var(--bg-soft)" : "#fff",
                      color: avatarUrlDraft ? "var(--ink-300)" : "var(--ink-900)",
                    }}
                  />
                  <span style={{ fontSize: 11.5, color: "var(--ink-400)" }}>
                    {avatarUrlDraft
                      ? "已设置头像图片，字标暂不生效；移除图片后可用。"
                      : "最多 4 个字符，支持 emoji；留空则显示姓名首字。"}
                  </span>
                </div>
              </KV>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "flex-end",
                  gap: 10,
                }}
              >
                {avatarMessage ? (
                  <span
                    aria-live="polite"
                    style={{
                      fontSize: 11.5,
                      color:
                        avatarMessage === "头像已更新。"
                          ? "var(--green-600, #0E8A4D)"
                          : "var(--danger-600)",
                    }}
                  >
                    {avatarMessage}
                  </span>
                ) : null}
                <Button
                  kind="primary"
                  size="sm"
                  disabled={avatarBusy}
                  onClick={saveAvatar}
                >
                  {avatarBusy ? "保存中…" : "保存头像"}
                </Button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );

  if (typeof document === "undefined") {
    return dialog;
  }
  // 传送到 body：侧边栏 aside 用 position:sticky 会形成独立层叠上下文，
  // 弹窗若留在其中会被根级 position:fixed 的 AI 助手面板盖住。
  return createPortal(dialog, document.body);
}

