function projectStatusOptionsForTransition(fromStatus, currentValue) {
  const baseStatus = PROJECT_STATUS[fromStatus] ? fromStatus : currentValue;
  const nextStatuses = PROJECT_STATUS[baseStatus]
    ? getAllowedProjectStatusTransitions(baseStatus)
    : [];
  const visibleValues = new Set([baseStatus, currentValue, ...nextStatuses]);
  return PROJECT_STATUS_OPTIONS.filter((option) =>
    visibleValues.has(option.value),
  );
}

function projectStatusNextLabels(fromStatus) {
  if (!PROJECT_STATUS[fromStatus]) return "暂无可流转状态";
  const nextOptions = getAllowedProjectStatusTransitions(fromStatus)
    .map((status) => PROJECT_STATUS[status]?.label)
    .filter(Boolean);
  return nextOptions.length > 0 ? nextOptions.join("、") : "暂无可流转状态";
}

function isProjectPublishFromSettings(fromStatus, nextStatus) {
  return fromStatus === "draft" && nextStatus === "recruiting";
}

function ProjectSettingsStatusPicker({ value, fromStatus, onChange }) {
  const [open, setOpen] = React.useState(false);
  const statusOptions = projectStatusOptionsForTransition(fromStatus, value);
  const current =
    statusOptions.find((option) => option.value === value) ||
    PROJECT_STATUS_OPTIONS.find((option) => option.value === value) ||
    statusOptions[0] ||
    PROJECT_STATUS_OPTIONS[0];
  const listboxId = "project-settings-status-options";

  const selectOption = (option) => {
    onChange(option.value);
    setOpen(false);
  };

  return (
    <div
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setOpen(false);
        }
      }}
      style={{ position: "relative" }}
    >
      <button
        type="button"
        role="combobox"
        aria-label="项目状态"
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-controls={listboxId}
        onClick={() => setOpen((next) => !next)}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            setOpen(false);
          }
          if (event.key === "ArrowDown" || event.key === "Enter") {
            event.preventDefault();
            setOpen(true);
          }
        }}
        style={{
          width: "100%",
          height: 40,
          border: `1px solid ${open ? "#b9c9ea" : "#dfe5ee"}`,
          borderRadius: 10,
          background: "#fff",
          display: "flex",
          alignItems: "center",
          gap: 8,
          padding: "0 12px",
          boxShadow: open ? "0 0 0 3px rgba(47, 111, 237, 0.12)" : "none",
          cursor: "pointer",
          fontFamily: "inherit",
          textAlign: "left",
          outline: "none",
          transition: "border-color 120ms ease, box-shadow 120ms ease",
        }}
      >
        <span
          aria-hidden="true"
          style={{
            width: 7,
            height: 7,
            borderRadius: 999,
            background: projectSettingsStatusDot(current.value),
            flex: "none",
          }}
        />
        <span
          style={{
            flex: 1,
            minWidth: 0,
            fontSize: 13.5,
            fontWeight: 500,
            color: "#17233d",
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap",
          }}
        >
          {current.label}
        </span>
        <Icon.ChevDown aria-hidden="true" size={15} sw={2} stroke="#8a97ad" />
      </button>
      {open && (
        <div
          id={listboxId}
          role="listbox"
          aria-label="项目状态选项"
          style={{
            position: "absolute",
            zIndex: 30,
            top: 44,
            left: 0,
            right: 0,
            background: "#fff",
            border: "1px solid #e4e9f1",
            borderRadius: 12,
            boxShadow: "0 12px 32px -12px rgba(23,35,61,.28)",
            padding: 5,
          }}
        >
          {statusOptions.map((option) => {
            const selected = option.value === current.value;
            return (
              <button
                key={option.value}
                type="button"
                role="option"
                aria-selected={selected}
                className="ps-option"
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => selectOption(option)}
                style={{
                  width: "100%",
                  border: "none",
                  background: "transparent",
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  padding: "8px 10px",
                  borderRadius: 8,
                  cursor: "pointer",
                  fontSize: 13,
                  color: "#17233d",
                  fontFamily: "inherit",
                  textAlign: "left",
                }}
              >
                <span style={{ flex: 1, minWidth: 0 }}>{option.label}</span>
                {selected && (
                  <Icon.Check
                    aria-hidden="true"
                    size={14}
                    sw={2}
                    stroke="#2f6fed"
                  />
                )}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ProjectSettingsDateField({ label, value, onChange }) {
  const inputRef = React.useRef(null);
  const [focused, setFocused] = React.useState(false);
  const openPicker = () => {
    const input = inputRef.current;
    if (!input) return;
    if (typeof input.showPicker === "function") {
      input.showPicker();
      return;
    }
    input.focus();
  };

  return (
    <ProjectSettingsField label={label}>
      <div
        onClick={openPicker}
        style={{
          position: "relative",
          height: 38,
          border: `1px solid ${focused ? "#2f6fed" : "#e4e9f1"}`,
          borderRadius: 10,
          background: "#fff",
          display: "flex",
          alignItems: "center",
          cursor: "pointer",
          boxShadow: focused ? "0 0 0 3px rgba(47, 111, 237, 0.12)" : "none",
          transition: "border-color 120ms ease, box-shadow 120ms ease",
        }}
      >
        <input
          className="ps-date-input"
          ref={inputRef}
          type="date"
          value={value}
          onClick={(event) => {
            event.stopPropagation();
            openPicker();
          }}
          onChange={(event) => onChange(event.target.value)}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          style={{
            width: "100%",
            height: "100%",
            border: "none",
            background: "transparent",
            outline: "none",
            color: "#17233d",
            fontSize: 13,
            padding: "0 34px 0 12px",
            cursor: "pointer",
            fontFamily: "inherit",
          }}
        />
        <span
          aria-hidden="true"
          style={{
            position: "absolute",
            right: 12,
            top: "50%",
            transform: "translateY(-50%)",
            display: "inline-flex",
            color: "#8a97ad",
            pointerEvents: "none",
          }}
        >
          <Icon.Calendar size={14} sw={2} stroke="#8a97ad" />
        </span>
      </div>
    </ProjectSettingsField>
  );
}

function projectCollaborationApplicationStatusLabel(status) {
  const labels = {
    submitted: "待审核",
    owner_countered: "待对方确认",
    approved: "已通过",
    rejected: "已拒绝",
    active: "已生效",
  };
  return labels[status] || status || "未知";
}

function projectCollaborationShareLabel(value) {
  const bps = Number(value);
  if (!Number.isFinite(bps) || bps <= 0) return "未填写";
  return `${(bps / 100).toFixed(2)}%`;
}

function projectCollaborationPercentToBps(value) {
  const percent = Number.parseFloat(String(value ?? "").trim());
  if (!Number.isFinite(percent)) return null;
  const bps = Math.round(percent * 100);
  if (bps < 0 || bps > 10000) return null;
  return bps;
}

function projectCollaborationApplicantLabel(application) {
  return (
    application?.applicantOrganizationName ||
    application?.organizationName ||
    application?.applicantOrganizationId ||
    "外部 MCN"
  );
}

function ProjectCollaborationPanel({
  project,
  draft,
  message,
  error,
  submitting,
  shareUrl,
  applications = [],
  onChange,
  onSave,
  onCreateShare,
  onRefreshApplications,
  onReviewApplication,
}) {
  const isBusy = Boolean(submitting);
  const enabled = Boolean(draft.enabled);
  const persisted = Boolean(project?.isOpenToMcnCollaboration);
  const [copyState, setCopyState] = React.useState("");
  const [applicationDrafts, setApplicationDrafts] = React.useState({});

  const updateApplicationDraft = (applicationId, patch) => {
    setApplicationDrafts((current) => ({
      ...current,
      [applicationId]: {
        counterSharePercent: "",
        rejectionReason: "",
        ...(current[applicationId] || {}),
        ...patch,
      },
    }));
  };

  const copyShareUrl = async () => {
    if (!shareUrl) return;
    try {
      if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(shareUrl);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = shareUrl;
        textarea.setAttribute("readonly", "");
        textarea.style.position = "fixed";
        textarea.style.left = "-9999px";
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand("copy");
        document.body.removeChild(textarea);
      }
      setCopyState("已复制");
    } catch {
      setCopyState("复制失败，请手动复制");
    }
  };

  return (
    <div
      style={{
        ...projectSettingsCardStyle,
        display: "flex",
        flexDirection: "column",
        minWidth: 0,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 10,
          padding: "15px 20px",
          borderBottom: "1px solid #edf0f6",
        }}
      >
        <div
          style={{ flex: 1, fontSize: 15, fontWeight: 700, color: "#17233d" }}
        >
          外部 MCN 协作
        </div>
        <ProjectSettingsPill
          tone={persisted ? "green" : enabled ? "blue" : "neutral"}
        >
          {persisted ? "已开启" : enabled ? "待保存" : "未开启"}
        </ProjectSettingsPill>
      </div>
      <div
        style={{
          padding: "18px 20px",
          display: "flex",
          flexDirection: "column",
          gap: 14,
        }}
      >
        <form
          onSubmit={onSave}
          style={{ display: "flex", flexDirection: "column", gap: 14 }}
        >
          <p
            style={{
              margin: 0,
              fontSize: 12.5,
              color: "#5b6b84",
              lineHeight: 1.7,
            }}
          >
            开启后，其他 MCN
            可通过邀请链接加入本项目；项目方保留项目设置与审核权限。
          </p>
          <ProjectSettingsToggleCard
            highlight
            title="开放外部 MCN 协作"
            desc="开启并保存后，外部 MCN 可通过协作链接提交申请"
            checked={enabled}
            onChange={(checked) => onChange("enabled", checked)}
          />
          {enabled ? (
            <>
              <ProjectSettingsField label="协作摘要">
                <textarea
                  className="ps-control"
                  value={draft.summary}
                  onChange={(event) => onChange("summary", event.target.value)}
                  rows={3}
                  placeholder="给外部 MCN 看的项目亮点、主播要求和交付口径"
                  style={{ minHeight: 64 }}
                />
              </ProjectSettingsField>
              <ProjectSettingsField label="分成建议">
                <input
                  className="ps-control"
                  value={draft.revenueShareHint}
                  onChange={(event) =>
                    onChange("revenueShareHint", event.target.value)
                  }
                  placeholder="例如 8-12%"
                />
              </ProjectSettingsField>
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: 10,
                }}
              >
                <button
                  type="button"
                  className="ps-btn ps-btn-secondary"
                  style={{ fontSize: 12.5, gap: 6, padding: 0 }}
                  onClick={onCreateShare}
                  disabled={isBusy}
                >
                  <Icon.Link2 aria-hidden="true" size={14} stroke="#5b6b84" />
                  {submitting === "share" ? "生成中" : "生成协作链接"}
                </button>
                <button
                  type="button"
                  className="ps-btn ps-btn-secondary"
                  style={{ fontSize: 12.5, gap: 6, padding: 0 }}
                  onClick={onRefreshApplications}
                  disabled={isBusy}
                >
                  <Icon.RefreshCw
                    aria-hidden="true"
                    size={14}
                    stroke="#5b6b84"
                  />
                  {submitting === "applications" ? "刷新中" : "刷新申请"}
                </button>
              </div>
            </>
          ) : null}
          <button
            type="submit"
            className="ps-btn ps-btn-primary"
            style={{ height: 38, width: "100%" }}
            disabled={isBusy}
          >
            {submitting === "settings" ? "保存中" : "保存协作设置"}
          </button>
          {error || message ? (
            <div
              aria-live="polite"
              style={{
                fontSize: 12,
                lineHeight: 1.6,
                color: error ? "#d64545" : "#5b6b84",
              }}
            >
              {error || message}
            </div>
          ) : null}
        </form>

        {shareUrl ? (
          <div
            style={{
              border: "1px solid #e4e9f1",
              borderRadius: 12,
              background: "#f6f8fb",
              padding: "12px 14px",
              display: "flex",
              flexDirection: "column",
              gap: 8,
            }}
          >
            <label
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 6,
                minWidth: 0,
                fontSize: 12,
                color: "#6b7686",
              }}
            >
              协作链接
              <input
                readOnly
                className="ps-control"
                value={shareUrl}
                style={{
                  color: "#1e4fd6",
                  fontSize: 12,
                  fontFamily:
                    "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                }}
              />
            </label>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-end",
                gap: 8,
              }}
            >
              {copyState ? (
                <span
                  aria-live="polite"
                  style={{
                    marginRight: "auto",
                    fontSize: 12,
                    color: copyState === "已复制" ? "#0e8c6c" : "#d64545",
                    whiteSpace: "nowrap",
                  }}
                >
                  {copyState}
                </span>
              ) : null}
              <button
                type="button"
                className="ps-btn ps-btn-secondary ps-btn-sm"
                onClick={copyShareUrl}
              >
                <Icon.Copy
                  aria-hidden="true"
                  size={13}
                  sw={2}
                  stroke="#5b6b84"
                />
                复制链接
              </button>
            </div>
          </div>
        ) : null}

        <ProjectSettingsDivider />

        {applications.length ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {applications.map((application) => {
              const canReview = application.status === "submitted";
              const applicationDraft = applicationDrafts[application.id] || {
                counterSharePercent: "",
                rejectionReason: "",
              };
              const counterShareBps = projectCollaborationPercentToBps(
                applicationDraft.counterSharePercent,
              );
              const canSubmitCounter = canReview && counterShareBps !== null;
              const canReject =
                canReview &&
                applicationDraft.rejectionReason.trim().length > 0;
              const isReviewing = submitting === `review:${application.id}`;
              return (
                <div
                  key={application.id}
                  style={{
                    border: "1px solid #e4e9f1",
                    borderRadius: 12,
                    padding: "13px 14px",
                    display: "flex",
                    flexDirection: "column",
                    gap: 10,
                    background: "#fff",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                      flexWrap: "wrap",
                    }}
                  >
                    <strong
                      style={{
                        fontSize: 13,
                        fontWeight: 600,
                        color: "#17233d",
                      }}
                    >
                      {projectCollaborationApplicantLabel(application)}
                    </strong>
                    <ProjectSettingsPill
                      tone={
                        canReview
                          ? "blue"
                          : application.status === "approved" ||
                              application.status === "active"
                            ? "green"
                            : "neutral"
                      }
                    >
                      {projectCollaborationApplicationStatusLabel(
                        application.status,
                      )}
                    </ProjectSettingsPill>
                    <span style={{ fontSize: 12, color: "#5b6b84" }}>
                      分成{" "}
                      {projectCollaborationShareLabel(
                        application.requestedRevenueShareBps,
                      )}
                    </span>
                    {application.ownerCounterRevenueShareBps ? (
                      <span style={{ fontSize: 12, color: "#5b6b84" }}>
                        反报价{" "}
                        {projectCollaborationShareLabel(
                          application.ownerCounterRevenueShareBps,
                        )}
                      </span>
                    ) : null}
                  </div>
                  {application.applicantNote ? (
                    <div
                      style={{
                        fontSize: 12,
                        color: "#8a97ad",
                        lineHeight: 1.6,
                      }}
                    >
                      {application.applicantNote}
                    </div>
                  ) : null}
                  {application.rejectionReason ? (
                    <div
                      style={{
                        fontSize: 12,
                        color: "#d64545",
                        lineHeight: 1.6,
                      }}
                    >
                      {application.rejectionReason}
                    </div>
                  ) : null}
                  {canReview ? (
                    <div
                      style={{
                        display: "flex",
                        flexDirection: "column",
                        gap: 10,
                      }}
                    >
                      <button
                        type="button"
                        className="ps-btn ps-btn-primary ps-btn-sm"
                        style={{ alignSelf: "flex-start" }}
                        disabled={isReviewing}
                        onClick={() =>
                          onReviewApplication(application, {
                            action: "accept",
                            ownerReviewNote: "",
                          })
                        }
                      >
                        通过申请
                      </button>
                      <div
                        style={{
                          display: "flex",
                          gap: 8,
                          flexWrap: "wrap",
                          alignItems: "end",
                        }}
                      >
                        <ProjectSettingsField label="反报价比例">
                          <input
                            type="number"
                            min="0"
                            max="100"
                            step="0.01"
                            value={applicationDraft.counterSharePercent}
                            onChange={(event) =>
                              updateApplicationDraft(application.id, {
                                counterSharePercent: event.target.value,
                              })
                            }
                            placeholder="8"
                            className="ps-control"
                            style={{ width: 110, height: 30 }}
                          />
                        </ProjectSettingsField>
                        <button
                          type="button"
                          className="ps-btn ps-btn-secondary ps-btn-sm"
                          disabled={isReviewing || !canSubmitCounter}
                          onClick={() =>
                            onReviewApplication(application, {
                              action: "counter",
                              ownerCounterRevenueShareBps: counterShareBps,
                              ownerReviewNote: "",
                            })
                          }
                        >
                          提交反报价
                        </button>
                      </div>
                      <div
                        style={{
                          display: "flex",
                          gap: 8,
                          flexWrap: "wrap",
                          alignItems: "end",
                        }}
                      >
                        <ProjectSettingsField label="拒绝原因">
                          <input
                            value={applicationDraft.rejectionReason}
                            onChange={(event) =>
                              updateApplicationDraft(application.id, {
                                rejectionReason: event.target.value,
                              })
                            }
                            placeholder="例如 档期不匹配"
                            className="ps-control"
                            style={{ width: 170, height: 30 }}
                          />
                        </ProjectSettingsField>
                        <button
                          type="button"
                          className="ps-btn ps-btn-danger ps-btn-sm"
                          disabled={isReviewing || !canReject}
                          onClick={() =>
                            onReviewApplication(application, {
                              action: "reject",
                              ownerReviewNote: "",
                              rejectionReason:
                                applicationDraft.rejectionReason.trim(),
                            })
                          }
                        >
                          确认拒绝
                        </button>
                      </div>
                    </div>
                  ) : null}
                </div>
              );
            })}
          </div>
        ) : (
          <div
            style={{
              border: "1px dashed #d5dce8",
              borderRadius: 12,
              padding: 20,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 8,
              textAlign: "center",
            }}
          >
            <span
              aria-hidden="true"
              style={{
                width: 38,
                height: 38,
                borderRadius: 999,
                background: "#f3f6fb",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <Icon.Inbox size={18} stroke="#a4afc2" />
            </span>
            <div style={{ fontSize: 13, fontWeight: 600, color: "#17233d" }}>
              暂无外部 MCN 申请
            </div>
            <div
              style={{
                fontSize: 12,
                color: "#8a97ad",
                lineHeight: 1.6,
                maxWidth: 240,
              }}
            >
              生成协作链接并分享后，外部 MCN 的申请会展示在这里。
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function PartnerCollaborationApplicationPanel({
  project,
  message,
  error,
  submitting,
  onConfirmCounter,
}) {
  const isCountered =
    project.collaborationApplicationStatus === "owner_countered";
  const isBusy = submitting === `confirm:${project.collaborationApplicationId}`;

  return (
    <Card
      title={isCountered ? "协作反报价待确认" : "协作申请待审核"}
      extra={
        <Badge tone={isCountered ? "amber" : "blue"} dot>
          {isCountered ? "待确认" : "待项目方审核"}
        </Badge>
      }
      padded={true}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 12,
        }}
      >
        <div
          style={{
            display: "flex",
            gap: 12,
            flexWrap: "wrap",
            alignItems: "center",
          }}
        >
          <span style={{ fontSize: 12, color: "var(--ink-500)" }}>
            申请分成{" "}
            {projectCollaborationShareLabel(project.requestedRevenueShareBps)}
          </span>
          {project.ownerCounterRevenueShareBps ? (
            <span style={{ fontSize: 13, color: "var(--ink-900)" }}>
              项目方反报价{" "}
              {projectCollaborationShareLabel(
                project.ownerCounterRevenueShareBps,
              )}
            </span>
          ) : null}
          {project.ownerOrganizationName ? (
            <span style={{ fontSize: 12, color: "var(--ink-500)" }}>
              项目方 {project.ownerOrganizationName}
            </span>
          ) : null}
        </div>
        {project.collaborationSummary ? (
          <div
            style={{
              fontSize: 12,
              color: "var(--ink-500)",
              lineHeight: 1.5,
            }}
          >
            {project.collaborationSummary}
          </div>
        ) : null}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 10,
            flexWrap: "wrap",
          }}
        >
          <div
            aria-live="polite"
            style={{
              minHeight: 18,
              fontSize: 12,
              color: error ? "var(--danger-600)" : "var(--ink-500)",
            }}
          >
            {error || message}
          </div>
          {isCountered ? (
            <Button
              kind="primary"
              icon={<Icon.Check size={14} stroke="#fff" />}
              disabled={isBusy}
              onClick={onConfirmCounter}
            >
              {isBusy ? "确认中" : "确认反报价"}
            </Button>
          ) : null}
        </div>
      </div>
    </Card>
  );
}

