// L3 复核优先级标签：lane 来自确定性规则 rankReportQueue。title 显示理由（含权重）。
const REVIEW_LANE_META = {
  review: { tone: "red", label: "复核优先" },
  normal: { tone: "neutral", label: "常规" },
  fast: { tone: "green", label: "绿快车道" },
};

function ReviewLaneTag({ row }) {
  const lane = row?._lane;
  if (!lane) return <span style={{ color: "var(--ink-400)" }}>—</span>;
  const meta = REVIEW_LANE_META[lane] || REVIEW_LANE_META.normal;
  return (
    <span
      style={{ display: "inline-flex", alignItems: "center", gap: 6 }}
      title={row?._reason || ""}
    >
      <span
        className="num"
        style={{
          fontSize: 11,
          color: "var(--ink-400)",
          minWidth: 18,
          textAlign: "right",
        }}
      >
        #{row?._priority ?? "—"}
      </span>
      <Badge tone={meta.tone} dot>
        {meta.label}
      </Badge>
    </span>
  );
}

function ScreenReports({ go }) {
  const reports = useOpsReports();
  const actions = useOpsLiveActions();
  const [filter, setFilter] = React.useState("pending_review");
  // 队列级筛选：项目 / 日期 / 关键字。状态 Tab 的计数基于筛选后的集合。
  const [projectFilter, setProjectFilter] = React.useState("all");
  const [dateRange, setDateRange] = React.useState("all");
  const [searchQuery, setSearchQuery] = React.useState("");
  const [activeId, setActiveId] = React.useState(reports[0]?.id ?? null);
  const [exportMessage, setExportMessage] = React.useState("");
  const [exportSubmitting, setExportSubmitting] = React.useState(false);
  const [batchSubmitting, setBatchSubmitting] = React.useState(false);
  const [autoReviewSubmitting, setAutoReviewSubmitting] = React.useState("");
  // L3 智能排序：可疑置顶 / 绿灯快速通道。默认开启（确定性规则，非 AI 改状态）。
  const [aiSort, setAiSort] = React.useState(true);

  // 报数明细导出需要项目（产品/小时单价）与任务（直播时间）；公会列取当前组织名。
  const projects = useOpsProjects();
  const tasks = useOpsTasks();
  const currentUser = useOpsCurrentUser();
  const { projects: projectData, tasks: taskData } =
    React.useContext(OpsLiveDataContext);

  const [exportPanelOpen, setExportPanelOpen] = React.useState(false);
  const [exportProjectSel, setExportProjectSel] = React.useState(
    () => new Set(),
  );
  const [exportStreamerSel, setExportStreamerSel] = React.useState(
    () => new Set(),
  );
  const [exportFrom, setExportFrom] = React.useState("");
  const [exportTo, setExportTo] = React.useState("");
  const reportProjectOptions = React.useMemo(
    () => Array.from(new Set(reports.map((r) => r.project).filter(Boolean))),
    [reports],
  );
  const reportStreamerOptions = React.useMemo(() => {
    const map = new Map();
    reports.forEach((r) => {
      if (r.streamerId && !map.has(r.streamerId)) {
        map.set(r.streamerId, r.streamer);
      }
    });
    return Array.from(map, ([id, name]) => ({ value: id, label: name }));
  }, [reports]);

  const scopedReports = React.useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    const minDate =
      dateRange === "all"
        ? ""
        : new Date(Date.now() - Number(dateRange) * 24 * 60 * 60 * 1000)
            .toISOString()
            .slice(0, 10);
    return reports.filter((r) => {
      if (projectFilter !== "all" && r.project !== projectFilter) return false;
      if (minDate && String(r.date || "") < minDate) return false;
      if (query) {
        const haystack = [r.id, r.taskId, r.streamer, r.project]
          .filter(Boolean)
          .join(" ")
          .toLowerCase();
        if (!haystack.includes(query)) return false;
      }
      return true;
    });
  }, [reports, projectFilter, dateRange, searchQuery]);

  const counts = {
    all: scopedReports.length,
    pending_review: scopedReports.filter((r) => r.status === "pending_review")
      .length,
    need_supply: scopedReports.filter((r) => r.status === "need_supply").length,
    approved: scopedReports.filter((r) => r.status === "approved").length,
    rejected: scopedReports.filter((r) => r.status === "rejected").length,
  };
  const filtered = React.useMemo(
    () =>
      filter === "all"
        ? scopedReports
        : scopedReports.filter((r) => r.status === filter),
    [filter, scopedReports],
  );

  // 智能排序：把列表喂给确定性规则引擎 rankReportQueue（可疑置顶/绿快车道），
  // 再按返回顺序重排，并把 lane / 优先级 / 理由挂回行对象供「复核优先级」列展示。
  const displayRows = React.useMemo(() => {
    if (!aiSort) return filtered;
    const ranked = rankReportQueue(
      filtered.map((r) => ({
        id: r.id,
        streamerName: r.streamer,
        projectName: r.project,
        evidenceLevel: r.evidenceLevel ?? null,
        deviationPct: r.deviationPct ?? null,
        submittedAt: r.submittedAt ?? r.date ?? null,
      })),
    );
    const byId = new Map(filtered.map((r) => [r.id, r]));
    return ranked
      .map((rk) => {
        const row = byId.get(rk.id);
        if (!row) return null;
        return { ...row, _lane: rk.lane, _priority: rk.priority, _reason: rk.reason };
      })
      .filter(Boolean);
  }, [aiSort, filtered]);

  React.useEffect(() => {
    if (filtered.length === 0) {
      if (activeId !== null) {
        setActiveId(null);
      }
      return;
    }

    if (!filtered.some((report) => report.id === activeId)) {
      setActiveId(filtered[0].id);
    }
  }, [activeId, filtered]);

  const activeReport =
    filtered.find((report) => report.id === activeId) || filtered[0] || null;
  const openExportPanel = () => {
    // 仅在打开导出面板时按需补齐项目/主播/任务数据（供导出列拼装），
    // 避免在报数审核页常驻拉取。
    if (projectData == null) actions.refreshProjects?.().catch(() => {});
    if (taskData == null) actions.refreshOpsTasks?.().catch(() => {});
    setExportProjectSel(new Set(reportProjectOptions));
    setExportStreamerSel(new Set(reportStreamerOptions.map((s) => s.value)));
    setExportFrom("");
    setExportTo("");
    setExportMessage("");
    setExportPanelOpen(true);
  };
  const toggleExportValue = (setter, value) =>
    setter((prev) => {
      const next = new Set(prev);
      if (next.has(value)) {
        next.delete(value);
      } else {
        next.add(value);
      }
      return next;
    });
  const toggleExportAll = (setter, options, allSelected) =>
    setter(allSelected ? new Set() : new Set(options.map((o) => o.value)));
  const runReportExport = async () => {
    setExportSubmitting(true);
    setExportMessage("");
    try {
      const projectByName = new Map(projects.map((p) => [p.name, p]));
      const projectById = new Map(projects.map((p) => [p.id, p]));
      const taskById = new Map(tasks.map((t) => [t.id, t]));
      // 公会列默认取当前组织名（工会 = 组织）。
      const guildName = (currentUser?.org || "").trim();
      const selected = reports.filter((r) => {
        const inProject = exportProjectSel.has(r.project);
        const inStreamer = exportStreamerSel.has(r.streamerId);
        const date = r.date || "";
        const inPeriod =
          (!exportFrom || date >= exportFrom) &&
          (!exportTo || date <= exportTo);
        return inProject && inStreamer && inPeriod;
      });
      if (selected.length === 0) {
        setExportMessage("当前筛选下没有可导出的报数。");
        setExportSubmitting(false);
        return;
      }
      const rows = selected.map((r) => {
        const proj =
          (r.projectId && projectById.get(r.projectId)) ||
          projectByName.get(r.project);
        const task = taskById.get(r.taskId);
        const hours = Number(r.systemDurationHours ?? r.duration ?? 0);
        // 小时单价取项目默认小时单价（即厂家给的单价）；达人费用 = 厂家单价 × 时长。
        const rate = Number(proj?.defaultHourlyRate ?? 0);
        return {
          reportId: r.id,
          guildOrIndividual: guildName || "—",
          gameProduct: proj?.product || r.project || "—",
          streamerName: r.streamer,
          liveDate: r.date || "—",
          liveTime:
            task &&
            Number.isFinite(task.startHour) &&
            Number.isFinite(task.endHour)
              ? `${task.startHour}:00-${task.endHour}:00`
              : "—",
          duration: `${hours} 小时`,
          hourlyRate: rate ? `¥${rate}` : "—",
          talentFee: rate ? `¥${(hours * rate).toFixed(2)}` : "—",
          // 截图列由服务端真实嵌入图片；此处仅作无图回退文案。
          screenshot: `${r.screens ?? 0} 张`,
        };
      });
      const result = await actions.exportReportSettlementXlsx?.({ rows });
      if (result) {
        downloadBase64Xlsx(result);
      }
      setExportPanelOpen(false);
      setExportMessage(`已导出 ${rows.length} 条报数明细`);
    } catch (error) {
      setExportMessage(error?.message || "报数明细导出失败，请稍后重试");
    } finally {
      setExportSubmitting(false);
    }
  };
  const batchApproveReports = async () => {
    if (batchSubmitting) return;
    const targetReports = filtered.filter(
      (report) => report.status === "pending_review",
    );
    if (targetReports.length === 0) {
      setExportMessage("当前筛选下没有可批量通过的待审核报数。");
      return;
    }

    setBatchSubmitting(true);
    setExportMessage("");
    try {
      for (const report of targetReports) {
        await actions.reviewReport?.(report.id, "approve");
      }
      setExportMessage(`批量审核已通过 ${targetReports.length} 条`);
    } catch (error) {
      setExportMessage(error?.message || "批量审核失败，请稍后重试");
    } finally {
      setBatchSubmitting(false);
    }
  };
  const evaluateAutoReview = async () => {
    if (!activeReport || autoReviewSubmitting) return;
    setAutoReviewSubmitting("evaluate");
    setExportMessage("");
    try {
      const body = await postWarRoomJson(
        "/api/auto-review/evaluate",
        {
          report: buildAutoReviewReportSnapshot(activeReport),
          rule: buildAutoReviewRuleSnapshot(),
        },
        "auto review evaluation failed",
      );
      const result = body.result ?? {};
      setExportMessage(
        `自动审核评估完成：${result.decision || "已返回结果"} · ${result.mode || "shadow"}`,
      );
    } catch (error) {
      setExportMessage(error?.message || "自动审核评估失败，请稍后重试");
    } finally {
      setAutoReviewSubmitting("");
    }
  };
  const readAutoReviewGate = async () => {
    if (autoReviewSubmitting) return;
    setAutoReviewSubmitting("gate");
    setExportMessage("");
    try {
      const body = await getOpsJson(
        "/api/auto-review/rollout-metrics?targetMode=active&explicitActiveRequest=false",
        "auto review rollout metrics failed",
      );
      const gate = body.result?.gate ?? {};
      const summary = body.result?.metrics?.summary ?? {};
      setExportMessage(
        `审核门槛：${gate.effectiveMode || gate.targetMode || "shadow"} · shadow ${summary.shadowSampleCount ?? 0} · audit ${summary.auditSampleCount ?? 0}`,
      );
    } catch (error) {
      setExportMessage(error?.message || "审核门槛读取失败，请稍后重试");
    } finally {
      setAutoReviewSubmitting("");
    }
  };

  const allProjectsSelected =
    reportProjectOptions.length > 0 &&
    exportProjectSel.size === reportProjectOptions.length;
  const allStreamersSelected =
    reportStreamerOptions.length > 0 &&
    exportStreamerSel.size === reportStreamerOptions.length;

  return (
    <>
      {exportPanelOpen ? (
        <ExportSettingsModal
          title="导出报数明细"
          submitting={exportSubmitting}
          onCancel={() => setExportPanelOpen(false)}
          onConfirm={runReportExport}
        >
          <ExportFilterSection title="周期">
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <input
                type="date"
                aria-label="开始日期"
                value={exportFrom}
                onChange={(e) => setExportFrom(e.target.value)}
                style={exportDateInputStyle}
              />
              <span style={{ color: "var(--ink-400)" }}>至</span>
              <input
                type="date"
                aria-label="结束日期"
                value={exportTo}
                onChange={(e) => setExportTo(e.target.value)}
                style={exportDateInputStyle}
              />
            </div>
          </ExportFilterSection>
          <ExportChecklist
            title="项目"
            options={reportProjectOptions.map((name) => ({
              value: name,
              label: name,
            }))}
            selected={exportProjectSel}
            allSelected={allProjectsSelected}
            onToggle={(v) => toggleExportValue(setExportProjectSel, v)}
            onToggleAll={() =>
              toggleExportAll(
                setExportProjectSel,
                reportProjectOptions.map((name) => ({ value: name })),
                allProjectsSelected,
              )
            }
          />
          <ExportChecklist
            title="主播"
            options={reportStreamerOptions}
            selected={exportStreamerSel}
            allSelected={allStreamersSelected}
            onToggle={(v) => toggleExportValue(setExportStreamerSel, v)}
            onToggleAll={() =>
              toggleExportAll(
                setExportStreamerSel,
                reportStreamerOptions,
                allStreamersSelected,
              )
            }
          />
        </ExportSettingsModal>
      ) : null}
      <PageHeader
        title="下播截图报数 · 审核"
        actions={
          <>
            <Button
              kind="default"
              icon={<Icon.Export size={14} />}
              onClick={openExportPanel}
              disabled={exportSubmitting}
            >
              {exportSubmitting ? "导出中" : "导出报数明细"}
            </Button>
            <Button
              kind="default"
              icon={<Icon.Sparkles size={14} />}
              onClick={evaluateAutoReview}
              disabled={!activeReport || Boolean(autoReviewSubmitting)}
            >
              {autoReviewSubmitting === "evaluate" ? "评估中" : "自动审核评估"}
            </Button>
            <Button
              kind="default"
              icon={<Icon.Audit size={14} />}
              onClick={readAutoReviewGate}
              disabled={Boolean(autoReviewSubmitting)}
            >
              {autoReviewSubmitting === "gate" ? "读取中" : "审核门槛"}
            </Button>
            <Button
              kind="primary"
              icon={<Icon.Check size={14} stroke="#fff" />}
              onClick={batchApproveReports}
              disabled={batchSubmitting}
            >
              {batchSubmitting ? "批量审核中" : "批量审核通过"}
            </Button>
          </>
        }
      />

      <div
        style={{
          padding: 20,
          display: "grid",
          gridTemplateColumns: "1.35fr 1fr",
          gap: 20,
          alignItems: "flex-start",
        }}
      >
        {exportMessage ? (
          <div
            aria-live="polite"
            style={{
              gridColumn: "1 / -1",
              padding: "10px 12px",
              border: "1px solid var(--line)",
              borderRadius: 8,
              background: "var(--bg-soft)",
              color: exportMessage.includes("失败")
                ? "var(--danger-600)"
                : "var(--ink-700)",
              fontSize: 12,
            }}
          >
            {exportMessage}
          </div>
        ) : null}
        <Card padded={false}>
          <div
            style={{ padding: "0 12px", borderBottom: "1px solid var(--line)" }}
          >
            <Tabs
              value={filter}
              onChange={setFilter}
              items={[
                {
                  key: "pending_review",
                  label: "待审核",
                  count: counts.pending_review,
                },
                {
                  key: "need_supply",
                  label: "需补充",
                  count: counts.need_supply,
                },
                { key: "approved", label: "已通过", count: counts.approved },
                { key: "rejected", label: "已驳回", count: counts.rejected },
                { key: "all", label: "全部", count: counts.all },
              ]}
            />
          </div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              padding: "12px 16px",
              borderBottom: "1px solid var(--line)",
            }}
          >
            <SearchInput
              placeholder="任务号 / 主播 / 项目"
              width={220}
              value={searchQuery}
              onChange={setSearchQuery}
            />
            <select
              aria-label="按日期筛选"
              value={dateRange}
              onChange={(event) => setDateRange(event.target.value)}
              style={{ ...taskInputStyle, width: 120 }}
            >
              <option value="all">全部日期</option>
              <option value="7">近 7 天</option>
              <option value="30">近 30 天</option>
              <option value="90">近 90 天</option>
            </select>
            <select
              aria-label="按项目筛选"
              value={projectFilter}
              onChange={(event) => setProjectFilter(event.target.value)}
              style={{ ...taskInputStyle, width: 180 }}
            >
              <option value="all">全部项目</option>
              {reportProjectOptions.map((name) => (
                <option key={name} value={name}>
                  {name}
                </option>
              ))}
            </select>
            <Button
              kind={aiSort ? "primary" : "default"}
              icon={<Icon.Sparkles size={14} stroke={aiSort ? "#fff" : undefined} />}
              onClick={() => setAiSort((v) => !v)}
            >
              {aiSort ? "AI 智能排序：开" : "AI 智能排序：关"}
            </Button>
            <div style={{ flex: 1 }} />
            <span style={{ fontSize: 12, color: "var(--ink-400)" }}>
              {aiSort ? "可疑置顶 · 绿灯快速通道" : "OCR 与手动偏差自动标红"}
            </span>
          </div>

          <DataTable
            activeRowId={activeId}
            onRowClick={(r) => setActiveId(r.id)}
            emptyText="当前筛选下暂无报数"
            columns={[
              ...(aiSort
                ? [
                    {
                      title: "复核优先级",
                      render: (r) => <ReviewLaneTag row={r} />,
                    },
                  ]
                : []),
              {
                title: "报数 / 任务",
                render: (r) => (
                  <div>
                    <div
                      className="mono"
                      style={{
                        fontWeight: 600,
                        color: "var(--ink-900)",
                        fontSize: 12.5,
                      }}
                    >
                      {displayRecordId(r.id, "报数记录")}
                    </div>
                    <div
                      className="mono"
                      style={{ fontSize: 11, color: "var(--ink-400)" }}
                    >
                      {displayRecordId(r.taskId, "任务")}
                    </div>
                  </div>
                ),
              },
              {
                title: "主播 · 项目",
                render: (r) => (
                  <div>
                    <div style={{ color: "var(--ink-900)", fontWeight: 500 }}>
                      {r.streamer}
                    </div>
                    <div
                      className="mono"
                      style={{ fontSize: 11, color: "var(--ink-400)" }}
                    >
                      {r.project}
                    </div>
                  </div>
                ),
              },
              {
                title: "日期",
                render: (r) => (
                  <span className="num" style={{ fontSize: 12 }}>
                    {r.date}
                  </span>
                ),
              },
              {
                title: "时长",
                align: "right",
                render: (r) => (
                  <span className="num" style={{ fontWeight: 600 }}>
                    {r.duration.toFixed(1)} h
                  </span>
                ),
              },
              {
                title: "场观",
                align: "right",
                render: (r) => (
                  <span className="num">{r.audience.toLocaleString()}</span>
                ),
              },
              {
                title: "截图",
                align: "center",
                render: (r) => (
                  <span
                    style={{
                      display: "inline-flex",
                      alignItems: "center",
                      gap: 4,
                      fontSize: 11,
                      color: "var(--ink-500)",
                    }}
                  >
                    <Icon.Reports size={12} stroke="var(--ink-400)" />
                    {r.screens}
                  </span>
                ),
              },
              {
                title: "来源",
                render: (r) => (
                  <Badge tone={r.source === "OCR" ? "violet" : "neutral"}>
                    {r.source === "OCR" ? "OCR 识别" : "手动"}
                  </Badge>
                ),
              },
              {
                title: "状态",
                render: (r) => {
                  const status = reportStatusMeta(r.status);
                  return (
                    <Badge tone={status.tone} dot>
                      {status.label}
                    </Badge>
                  );
                },
              },
            ]}
            rows={displayRows}
          />
        </Card>

        {/* Detail */}
        <ReportDetail id={activeId} reports={displayRows} />
      </div>
    </>
  );
}

function ReportScreenshot({ reportId, streamer, fallback }) {
  const [failed, setFailed] = React.useState(false);
  if (failed) {
    return fallback;
  }
  const src = `/api/live-reports/${reportId}/screenshot`;
  return (
    <a
      href={src}
      target="_blank"
      rel="noopener noreferrer"
      style={{ display: "block" }}
    >
      <img
        src={src}
        alt={`${streamer} 下播截图`}
        onError={() => setFailed(true)}
        style={{
          width: "100%",
          borderRadius: 10,
          border: "1px solid var(--line)",
          display: "block",
        }}
      />
    </a>
  );
}

function ReportDetail({ id, reports }) {
  const actions = useOpsLiveActions();
  const [busyDecision, setBusyDecision] = React.useState(null);
  const r = reports.find((x) => x.id === id) || reports[0] || null;
  if (!r) {
    return (
      <div
        style={{
          position: "sticky",
          top: 76,
          display: "flex",
          flexDirection: "column",
          gap: 16,
        }}
      >
        <Card>
          <EmptyHint
            title="暂无报数数据"
            hint="报数审核记录会在后端返回后展示。"
          />
        </Card>
      </div>
    );
  }

  const s = STREAMERS.find((s) => s.alias === r.streamer);
  const p = PROJECTS.find((p) => p.id === r.project);
  const projectName = p?.name || r.project;
  const isReviewable = r.status === "pending_review";

  const review = async (decision) => {
    if (!actions.reviewReport || !isReviewable) return;
    setBusyDecision(decision);
    try {
      await actions.reviewReport(r.id, decision);
    } finally {
      setBusyDecision(null);
    }
  };

  // OCR (screenshot) vs system/platform, built from real report data.
  const systemHours = (r.systemDurationHours ?? r.duration ?? 0).toFixed(1);
  const ocrHours =
    r.ocrDurationHours != null
      ? r.ocrDurationHours.toFixed(1) + " h"
      : "未识别";
  const durationDiff =
    r.ocrDurationHours != null &&
    Math.abs(r.ocrDurationHours - (r.systemDurationHours ?? r.duration ?? 0)) >=
      0.05;
  const ocrFields = [
    { label: "直播日期", ocr: r.date, manual: r.date, diff: false },
    {
      label: "直播时长",
      ocr: ocrHours,
      manual: systemHours + " h",
      diff: durationDiff,
    },
    {
      label: "场观",
      ocr: (r.audience ?? 0).toLocaleString(),
      manual: <span style={{ color: "var(--ink-300)" }}>—</span>,
      diff: false,
    },
  ];
  const diffCount = ocrFields.filter((f) => f.diff).length;
  const riskFlags = Array.isArray(r.riskFlags) ? r.riskFlags : [];
  const divergencePct =
    typeof r.divergencePct === "number" ? r.divergencePct : null;

  return (
    // 面板钉在视口内（不随左列表滚动）：自身高度=视口高，播放窗弹性伸缩，
    // AI 识别/预审与操作条常驻底部。
    <div
      style={{
        position: "sticky",
        top: 76,
        height: "calc(100vh - 100px)",
        minHeight: 520,
        display: "flex",
        flexDirection: "column",
        gap: 16,
      }}
    >
      <Card
        padded={false}
        style={{ flex: 1, minHeight: 0 }}
        bodyStyle={{ minHeight: 0, display: "flex", flexDirection: "column" }}
      >
        <div
          style={{
            padding: "14px 16px",
            borderBottom: "1px solid var(--line)",
            display: "flex",
            alignItems: "center",
            gap: 12,
          }}
        >
          <div style={{ flex: 1, minWidth: 0 }}>
            <div
              className="mono"
              style={{ fontSize: 11, color: "var(--ink-400)" }}
            >
              {displayRecordId(r.id, "报数记录")} · 任务{" "}
              {displayRecordId(r.taskId, "任务")}
            </div>
            <div
              style={{
                fontSize: 15,
                fontWeight: 600,
                color: "var(--ink-900)",
                marginTop: 2,
              }}
            >
              {r.streamer} · {projectName}
            </div>
          </div>
          {(() => {
            const status = reportStatusMeta(r.status);
            return (
              <Badge tone={status.tone} dot>
                {status.label}
              </Badge>
            );
          })()}
        </div>

        {/* Screenshot preview */}
        <div style={{ padding: 16 }}>
          <ReportScreenshot
            key={r.id}
            reportId={r.id}
            streamer={r.streamer}
            fallback={
              <ScreenshotPreview
                platform={s?.platforms?.[0] || "抖音"}
                streamer={r.streamer}
                date={r.date}
                duration={r.duration}
                audience={r.audience}
              />
            }
          />
        </div>

        {/* OCR vs Manual */}
        <div style={{ padding: "0 16px 16px" }}>
          <div
            style={{
              fontSize: 12,
              fontWeight: 600,
              color: "var(--ink-700)",
              margin: "0 0 8px",
              display: "flex",
              alignItems: "center",
              gap: 8,
            }}
          >
            OCR 识别 vs 系统/平台
            {diffCount > 0 ? (
              <Badge tone="violet" dot>
                差异 {diffCount} 项
              </Badge>
            ) : (
              <Badge tone="green" dot>
                一致
              </Badge>
            )}
          </div>
          <table
            style={{
              width: "100%",
              borderCollapse: "separate",
              borderSpacing: 0,
              border: "1px solid var(--line)",
              borderRadius: 8,
              overflow: "hidden",
            }}
          >
            <thead>
              <tr style={{ background: "var(--bg-soft)" }}>
                <th
                  style={{
                    padding: "8px 12px",
                    textAlign: "left",
                    fontSize: 11,
                    fontWeight: 500,
                    color: "var(--ink-400)",
                  }}
                >
                  字段
                </th>
                <th
                  style={{
                    padding: "8px 12px",
                    textAlign: "left",
                    fontSize: 11,
                    fontWeight: 500,
                    color: "var(--ink-400)",
                  }}
                >
                  OCR 原始
                </th>
                <th
                  style={{
                    padding: "8px 12px",
                    textAlign: "left",
                    fontSize: 11,
                    fontWeight: 500,
                    color: "var(--ink-400)",
                  }}
                >
                  系统/平台
                </th>
              </tr>
            </thead>
            <tbody>
              {ocrFields.map((f, i) => (
                <tr
                  key={f.label}
                  style={{ background: f.diff ? "#FEF7E6" : "#fff" }}
                >
                  <td
                    style={{
                      padding: "9px 12px",
                      fontSize: 12,
                      color: "var(--ink-500)",
                      borderTop: i ? "1px solid var(--line)" : "none",
                    }}
                  >
                    {f.label}
                  </td>
                  <td
                    className="num"
                    style={{
                      padding: "9px 12px",
                      fontSize: 12.5,
                      color: f.diff ? "var(--warn-600)" : "var(--ink-700)",
                      borderTop: i ? "1px solid var(--line)" : "none",
                      textDecoration: f.diff ? "line-through" : "none",
                    }}
                  >
                    {f.ocr}
                  </td>
                  <td
                    className="num"
                    style={{
                      padding: "9px 12px",
                      fontSize: 12.5,
                      fontWeight: f.diff ? 600 : 500,
                      color: "var(--ink-900)",
                      borderTop: i ? "1px solid var(--line)" : "none",
                    }}
                  >
                    {f.manual}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div style={{ padding: "0 16px 16px" }}>
          <KV label="主播备注">
            {r.note || <span style={{ color: "var(--ink-300)" }}>—</span>}
          </KV>
          <KV label="风控提示">
            <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
              {divergencePct != null && divergencePct > 0 ? (
                <span
                  style={{
                    fontSize: 12,
                    color: "var(--warn-600)",
                    display: "inline-flex",
                    alignItems: "center",
                    gap: 6,
                  }}
                >
                  <Icon.Warn size={12} stroke="var(--warn-600)" />
                  时长偏差 {(divergencePct * 100).toFixed(1)}%
                </span>
              ) : null}
              {riskFlags.map((flag) => (
                <span
                  key={flag}
                  style={{
                    fontSize: 12,
                    color: "var(--warn-600)",
                    display: "inline-flex",
                    alignItems: "center",
                    gap: 6,
                  }}
                >
                  <Icon.Warn size={12} stroke="var(--warn-600)" />
                  {riskFlagLabel(flag)}
                </span>
              ))}
              {divergencePct == null && riskFlags.length === 0 ? (
                <span
                  style={{
                    fontSize: 12,
                    color: "var(--ok-600)",
                    display: "inline-flex",
                    alignItems: "center",
                    gap: 6,
                  }}
                >
                  <Icon.Check size={12} stroke="var(--ok-600)" />
                  无风险提示
                </span>
              ) : null}
            </div>
          </KV>
        </div>

        {isReviewable ? (
          <div
            style={{
              padding: 12,
              borderTop: "1px solid var(--line)",
              background: "var(--bg-soft)",
              display: "flex",
              gap: 8,
            }}
          >
            <Button
              kind="danger"
              icon={<Icon.X size={14} />}
              disabled={Boolean(busyDecision)}
              onClick={() => review("reject")}
            >
              {busyDecision === "reject" ? "处理中…" : "驳回"}
            </Button>
            <Button
              kind="default"
              disabled={Boolean(busyDecision)}
              onClick={() => review("need_more")}
            >
              {busyDecision === "need_more" ? "处理中…" : "需补充截图"}
            </Button>
            <div style={{ flex: 1 }} />
            <label
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 6,
                fontSize: 12,
                color: "var(--ink-500)",
              }}
            >
              <input
                type="checkbox"
                defaultChecked
                style={{ accentColor: "var(--blue-600)" }}
              />{" "}
              计入任务结果
            </label>
            <Button
              kind="primary"
              icon={<Icon.Check size={14} stroke="#fff" />}
              disabled={Boolean(busyDecision)}
              onClick={() => review("approve")}
            >
              {busyDecision === "approve" ? "处理中…" : "审核通过"}
            </Button>
          </div>
        ) : (
          <div
            style={{
              padding: 12,
              borderTop: "1px solid var(--line)",
              background: "var(--bg-soft)",
              display: "flex",
              alignItems: "center",
              gap: 8,
              color: "var(--ink-500)",
              fontSize: 12,
            }}
          >
            {(() => {
              const status = reportStatusMeta(r.status);
              return <Badge tone={status.tone}>{status.label}</Badge>;
            })()}
            该报数已完成当前审核流转。
          </div>
        )}
      </Card>
    </div>
  );
}

