function settlementEvidenceTone(value) {
  if (String(value).startsWith("green")) return "green";
  if (String(value).startsWith("yellow")) return "amber";
  if (String(value).startsWith("red")) return "red";
  return "neutral";
}

function BatchDetail({
  id,
  batches = BATCHES,
  batchDetails = {},
  onAddManualItem,
  onLockBatch,
  onReopenBatch,
  onConfirmBatch,
  onNotifyStreamers,
  lockGate = { evaluated: false, hasBlocking: false },
  lockBlockMessage = "",
  busyAction,
}) {
  const [detailMessage, setDetailMessage] = React.useState("");
  const [auditBusy, setAuditBusy] = React.useState(false);
  const auditEntries = useOpsAuditEntries();
  const currentUser = useOpsCurrentUser();
  const actions = useOpsLiveActions();
  const b = batches.find((x) => x.id === id) || batches[0] || BATCHES[1];
  if (!b) {
    return (
      <div
        className="ops-settlement-batch-detail"
        style={{
          position: "sticky",
          top: 76,
          display: "flex",
          flexDirection: "column",
          gap: 16,
        }}
      >
        <Card>
          <EmptyHint title="暂无结算批次" hint="结算批次会在后端返回后展示。" />
        </Card>
      </div>
    );
  }

  const isPayable = b.type === "streamer_payable";
  const isLocked = b.status === "locked";
  const batchStatus = BATCH_STATUS[b.status] || BATCH_STATUS.pending_confirm;
  const isReferenceBatch = BATCHES.some((x) => x.id === b.id);
  const apiDetailRows = Array.isArray(batchDetails[b.id])
    ? batchDetails[b.id]
    : null;
  const detailRows = apiDetailRows?.length
    ? apiDetailRows
    : isReferenceBatch
      ? BATCH_DETAIL_ITEMS
      : [
          {
            streamer: "批次汇总",
            id: String(b.id).slice(0, 8),
            rule: isPayable ? "主播应付汇总" : "厂家应收汇总",
            hours: 0,
            qty: "API 批次",
            base: 0,
            variable: b.amount,
            adjust: 0,
            total: b.amount,
          },
        ];

  const total = detailRows.reduce((s, x) => s + x.total, 0);
  const baseSum = detailRows.reduce((s, x) => s + x.base, 0);
  const varSum = detailRows.reduce((s, x) => s + x.variable, 0);
  const adjSum = detailRows.reduce((s, x) => s + x.adjust, 0);
  const ruleBreakdownRows = detailRows.filter((row) => row.ruleBreakdown);
  const openRuleExceptions = detailRows.flatMap((row) =>
    Array.isArray(row.openExceptions)
      ? row.openExceptions.map((exception) => ({
          ...exception,
          itemId: row.id,
          streamer: row.streamer,
        }))
      : [],
  );
  const showPendingDetail = (message) => {
    setDetailMessage(message);
  };
  const batchAudit = auditEntries.filter(
    (entry) =>
      entry.objectId === b.id ||
      (entry.module === "settlement" && entry.objectName === b.name),
  );
  const loadBatchAudit = async () => {
    if (auditBusy) return;
    setDetailMessage("");
    if (!actions.refreshAuditEntries) {
      setDetailMessage("审计明细需要登录后台后查看。");
      return;
    }
    setAuditBusy(true);
    try {
      await actions.refreshAuditEntries();
      setDetailMessage("批次审计明细已刷新，见下方审计轨迹。");
    } catch (error) {
      setDetailMessage(error?.message || "审计明细刷新失败，请稍后重试。");
    } finally {
      setAuditBusy(false);
    }
  };

  return (
    <div
      className="ops-settlement-batch-detail"
      style={{
        position: "sticky",
        top: 76,
        display: "flex",
        flexDirection: "column",
        gap: 16,
      }}
    >
      <Card padded={false}>
        {/* Header */}
        <div
          style={{
            padding: "14px 16px",
            borderBottom: "1px solid var(--line)",
          }}
        >
          <div
            className="ops-settlement-batch-header"
            style={{ display: "flex", alignItems: "flex-start", gap: 12 }}
          >
            <div style={{ flex: 1, minWidth: 0 }}>
              <div
                className="mono"
                style={{ fontSize: 11, color: "var(--ink-400)" }}
              >
                {displayRecordId(b.id, "结算批次")}
              </div>
              <div
                style={{
                  fontSize: 16,
                  fontWeight: 600,
                  color: "var(--ink-900)",
                  marginTop: 2,
                }}
              >
                {b.name}
              </div>
              <div
                style={{
                  marginTop: 8,
                  display: "flex",
                  gap: 6,
                  flexWrap: "wrap",
                }}
              >
                <Badge tone={isPayable ? "teal" : "blue"}>
                  {isPayable ? "主播应付" : "厂家应收"}
                </Badge>
                <Badge tone={batchStatus.tone} dot>
                  {batchStatus.label}
                </Badge>
                {isLocked && (
                  <Badge tone="ink" soft={true}>
                    <Icon.Lock size={11} /> 已锁定
                  </Badge>
                )}
              </div>
            </div>
            <div
              className="ops-settlement-batch-total"
              style={{ textAlign: "right" }}
            >
              <div style={{ fontSize: 11, color: "var(--ink-400)" }}>
                合计金额
              </div>
              <div
                className="num"
                style={{
                  fontSize: 22,
                  fontWeight: 700,
                  color: "var(--ink-900)",
                  letterSpacing: "-0.02em",
                }}
              >
                ¥{total.toLocaleString()}
              </div>
            </div>
          </div>

          <div
            className="ops-settlement-batch-meta"
            style={{
              marginTop: 12,
              display: "grid",
              // minmax(0,…) + break-all：创建人是 36 位 UUID 这类不可断词的
              // 长串，1fr 的 min-content 会把批次详情卡撑出容器右缘。
              gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
              gap: 12,
              paddingTop: 12,
              borderTop: "1px dashed var(--line)",
            }}
          >
            <KV label="结算周期" w={60}>
              <span className="num">{b.period}</span>
            </KV>
            <KV label="项目" w={36}>
              <span className="mono">{b.project}</span>
            </KV>
            <KV label="创建人" w={50}>
              <span style={{ wordBreak: "break-all" }}>{b.creator}</span>
            </KV>
            <KV label="更新" w={36}>
              <span className="num" style={{ fontSize: 11.5 }}>
                {b.updated}
              </span>
            </KV>
          </div>
        </div>

        {/* Items */}
        <div
          className="ops-settlement-batch-items-header"
          style={{
            padding: "12px 16px 0",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <div
            style={{ fontSize: 13, fontWeight: 600, color: "var(--ink-700)" }}
          >
            结算明细
          </div>
          <div
            className="ops-settlement-batch-items-summary"
            style={{
              display: "flex",
              gap: 6,
              fontSize: 11,
              color: "var(--ink-400)",
            }}
          >
            <span>
              底薪{" "}
              <span
                className="num"
                style={{ color: "var(--ink-700)", fontWeight: 600 }}
              >
                ¥{baseSum.toLocaleString()}
              </span>
            </span>
            <span>·</span>
            <span>
              变动{" "}
              <span
                className="num"
                style={{ color: "var(--ink-700)", fontWeight: 600 }}
              >
                ¥{varSum.toLocaleString()}
              </span>
            </span>
            <span>·</span>
            <span>
              调整{" "}
              <span
                className="num"
                style={{
                  color: adjSum >= 0 ? "var(--ink-700)" : "var(--danger-600)",
                  fontWeight: 600,
                }}
              >
                {adjSum >= 0 ? "+" : ""}
                {adjSum}
              </span>
            </span>
          </div>
        </div>

        <DataTable
          dense
          columns={[
            {
              title: "主播",
              render: (r) => (
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <Avatar name={r.streamer} size={26} />
                  <div>
                    <div
                      style={{
                        fontSize: 12.5,
                        fontWeight: 600,
                        color: "var(--ink-900)",
                      }}
                    >
                      {r.streamer}
                    </div>
                    <div
                      className="mono"
                      style={{ fontSize: 10.5, color: "var(--ink-400)" }}
                    >
                      {displayRecordId(r.id, "结算项")}
                    </div>
                  </div>
                </div>
              ),
            },
            {
              title: "结算规则",
              render: (r) => <Badge tone="blue">{r.rule}</Badge>,
            },
            {
              title: "有效时长",
              align: "right",
              render: (r) => (
                <span className="num">{r.hours.toFixed(1)} h</span>
              ),
            },
            {
              title: "其他口径",
              align: "right",
              render: (r) => (
                <span style={{ fontSize: 11, color: "var(--ink-400)" }}>
                  {r.qty}
                </span>
              ),
            },
            {
              title: "底薪",
              align: "right",
              render: (r) => (
                <span className="num">
                  {r.base ? "¥" + r.base.toLocaleString() : "—"}
                </span>
              ),
            },
            {
              title: "变动",
              align: "right",
              render: (r) => (
                <span className="num">¥{r.variable.toLocaleString()}</span>
              ),
            },
            {
              title: "调整",
              align: "right",
              render: (r) => (
                <span
                  className="num"
                  style={{
                    color:
                      r.adjust === 0
                        ? "var(--ink-400)"
                        : r.adjust > 0
                          ? "var(--ok-600)"
                          : "var(--danger-600)",
                  }}
                >
                  {r.adjust === 0 ? "—" : (r.adjust > 0 ? "+" : "") + r.adjust}
                </span>
              ),
            },
            {
              title: "小计",
              align: "right",
              render: (r) => (
                <span
                  className="num"
                  style={{ fontWeight: 700, color: "var(--ink-900)" }}
                >
                  ¥{r.total.toLocaleString()}
                </span>
              ),
            },
          ]}
          rows={detailRows}
        />

        {ruleBreakdownRows.length > 0 || openRuleExceptions.length > 0 ? (
          <div
            style={{
              padding: "12px 16px",
              borderTop: "1px solid var(--line)",
              display: "flex",
              flexDirection: "column",
              gap: 12,
            }}
          >
            {ruleBreakdownRows.length > 0 ? (
              <div>
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 8,
                    flexWrap: "wrap",
                  }}
                >
                  <div
                    style={{
                      fontSize: 13,
                      fontWeight: 600,
                      color: "var(--ink-700)",
                    }}
                  >
                    规则拆解
                  </div>
                  <Badge tone="neutral">{ruleBreakdownRows.length} 项</Badge>
                </div>

                <div
                  style={{
                    marginTop: 10,
                    display: "flex",
                    flexDirection: "column",
                    gap: 12,
                  }}
                >
                  {ruleBreakdownRows.map((row) => (
                    <div
                      key={row.id}
                      style={{
                        paddingTop: 10,
                        borderTop: "1px dashed var(--line)",
                      }}
                    >
                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          gap: 8,
                          flexWrap: "wrap",
                        }}
                      >
                        <div
                          style={{
                            fontSize: 12,
                            fontWeight: 600,
                            color: "var(--ink-800)",
                          }}
                        >
                          {row.streamer}
                        </div>
                        <div
                          style={{
                            display: "flex",
                            gap: 6,
                            flexWrap: "wrap",
                            justifyContent: "flex-end",
                          }}
                        >
                          {row.ruleBreakdown.appliedVersionLabels.map(
                            (label) => (
                              <Badge key={`${row.id}-${label}`} tone="blue">
                                {label}
                              </Badge>
                            ),
                          )}
                          {row.ruleBreakdown.executionGrain ? (
                            <Badge tone="neutral">
                              {row.ruleBreakdown.executionGrain}
                            </Badge>
                          ) : null}
                          <Badge tone="neutral">
                            来源报数 {row.ruleBreakdown.sourceReportCount} 条
                          </Badge>
                        </div>
                      </div>

                      <div
                        style={{
                          marginTop: 8,
                          display: "grid",
                          gridTemplateColumns:
                            "repeat(auto-fit, minmax(120px, 1fr))",
                          gap: 8,
                        }}
                      >
                        {row.ruleBreakdown.components.map((component) => (
                          <div
                            key={`${row.id}-${component.key}`}
                            style={{
                              padding: "8px 10px",
                              border: "1px solid var(--line)",
                              borderRadius: 8,
                              background: "var(--bg-soft)",
                            }}
                          >
                            <div
                              style={{ fontSize: 11, color: "var(--ink-400)" }}
                            >
                              {component.label}
                            </div>
                            <div
                              className="num"
                              style={{
                                marginTop: 2,
                                fontSize: 13,
                                fontWeight: 700,
                                color: "var(--ink-900)",
                              }}
                            >
                              {formatYuanFromCents(component.amountCents)}
                            </div>
                          </div>
                        ))}
                      </div>

                      {row.ruleBreakdown.explanationZh ? (
                        <div
                          style={{
                            marginTop: 8,
                            fontSize: 12,
                            color: "var(--ink-600)",
                            lineHeight: 1.5,
                          }}
                        >
                          {row.ruleBreakdown.explanationZh}
                        </div>
                      ) : null}

                      {row.ruleBreakdown.missingDataDecisions.length > 0 ? (
                        <div style={{ marginTop: 10 }}>
                          <div
                            style={{
                              fontSize: 12,
                              fontWeight: 600,
                              color: "var(--ink-700)",
                            }}
                          >
                            缺失数据决策
                          </div>
                          <div
                            style={{
                              marginTop: 6,
                              display: "flex",
                              flexDirection: "column",
                              gap: 6,
                            }}
                          >
                            {row.ruleBreakdown.missingDataDecisions.map(
                              (decision) => (
                                <div
                                  key={`${row.id}-${decision.variableName}-${decision.policy}-${decision.decision}`}
                                  style={{
                                    display: "flex",
                                    alignItems: "center",
                                    gap: 8,
                                    flexWrap: "wrap",
                                    fontSize: 12,
                                    color: "var(--ink-500)",
                                  }}
                                >
                                  <span className="mono">
                                    {decision.variableName}
                                  </span>
                                  <Badge tone="amber">{decision.policy}</Badge>
                                  <span>{decision.decision}</span>
                                </div>
                              ),
                            )}
                          </div>
                        </div>
                      ) : null}
                    </div>
                  ))}
                </div>
              </div>
            ) : null}

            <div>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  gap: 8,
                }}
              >
                <div
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: "var(--ink-700)",
                  }}
                >
                  异常队列
                </div>
                <Badge tone={openRuleExceptions.length ? "amber" : "green"}>
                  {openRuleExceptions.length
                    ? `${openRuleExceptions.length} 个待处理`
                    : "无待处理异常"}
                </Badge>
              </div>
              {openRuleExceptions.length > 0 ? (
                <div
                  style={{
                    marginTop: 8,
                    display: "flex",
                    flexDirection: "column",
                    gap: 6,
                  }}
                >
                  {openRuleExceptions.map((exception) => (
                    <div
                      key={exception.id}
                      style={{
                        display: "grid",
                        gridTemplateColumns: "minmax(0, 1fr) auto",
                        gap: 8,
                        alignItems: "center",
                        padding: "7px 0",
                        borderTop: "1px dashed var(--line)",
                      }}
                    >
                      <div style={{ minWidth: 0 }}>
                        <div
                          className="mono"
                          style={{
                            fontSize: 11,
                            color: "var(--ink-700)",
                            wordBreak: "break-all",
                          }}
                        >
                          {exception.id}
                        </div>
                        <div
                          style={{
                            marginTop: 2,
                            fontSize: 12,
                            color: "var(--ink-500)",
                            wordBreak: "break-word",
                          }}
                        >
                          {exception.streamer} · {exception.variableName}
                          {exception.liveReportId
                            ? ` · ${exception.liveReportId}`
                            : ""}
                        </div>
                      </div>
                      <Badge tone="amber">{exception.status}</Badge>
                    </div>
                  ))}
                </div>
              ) : (
                <div
                  style={{
                    marginTop: 6,
                    fontSize: 12,
                    color: "var(--ink-400)",
                  }}
                >
                  当前批次没有待处理的规则异常。
                </div>
              )}
            </div>
          </div>
        ) : null}
        {detailMessage ? (
          <div
            aria-live="polite"
            style={{
              padding: "10px 12px 0",
              fontSize: 12,
              color: "var(--ink-500)",
            }}
          >
            {detailMessage}
          </div>
        ) : null}

        {/* Footer: actions（窄容器下按钮换行而不是把卡片顶出右缘） */}
        <div
          className="ops-settlement-batch-actions"
          style={{
            padding: 12,
            borderTop: "1px solid var(--line)",
            background: "var(--bg-soft)",
            display: "flex",
            alignItems: "center",
            gap: 8,
            flexWrap: "wrap",
            justifyContent: "flex-end",
            rowGap: 8,
          }}
        >
          {isLocked && (
            <div
              style={{
                fontSize: 12,
                color: "var(--ink-500)",
                display: "inline-flex",
                alignItems: "center",
                gap: 6,
              }}
            >
              <Icon.Lock size={12} stroke="var(--ink-500)" />
              本批次已锁定 · 由 {b.creator} 于 {b.updated}
            </div>
          )}
          <div style={{ flex: 1 }} />
          {isLocked ? (
            <>
              <Button
                kind="ghost"
                icon={<Icon.History size={14} />}
                onClick={loadBatchAudit}
                disabled={auditBusy}
              >
                {auditBusy ? "刷新中…" : "查看审计"}
              </Button>
              {isPayable && onNotifyStreamers ? (
                <Button
                  kind="default"
                  icon={<Icon.Bell size={14} />}
                  onClick={onNotifyStreamers}
                  disabled={!!busyAction}
                >
                  {busyAction === "notify" ? "发送中…" : "发送薪资明细"}
                </Button>
              ) : null}
              <Button
                kind="default"
                icon={<Icon.Export size={14} />}
                onClick={() => showPendingDetail("批次 PDF 导出后台暂未接入。")}
              >
                导出 PDF
              </Button>
              <Button
                kind="danger"
                icon={<Icon.Unlock size={14} />}
                onClick={onReopenBatch}
                disabled={!!busyAction}
              >
                {busyAction === "reopen" ? "处理中…" : "重新打开"}
              </Button>
            </>
          ) : (
            <>
              <Button
                kind="ghost"
                onClick={() =>
                  showPendingDetail("批次编辑已取消，未提交后台变更。")
                }
              >
                取消
              </Button>
              <Button
                kind="default"
                icon={<Icon.Plus size={14} />}
                onClick={onAddManualItem}
                disabled={!!busyAction}
              >
                {busyAction === "manual" ? "处理中…" : "添加人工调整"}
              </Button>
              <Button
                kind="default"
                onClick={() =>
                  showPendingDetail(
                    "复杂成本项需导入或人工确认后，再附加到结算批次。",
                  )
                }
              >
                添加复杂成本项
              </Button>
              <Button
                kind="default"
                onClick={() => showPendingDetail("批次草稿保存后台暂未接入。")}
              >
                保存为草稿
              </Button>
              {canFinanceConfirmSettlementBatch(currentUser.role, b.status) ? (
                <Button
                  kind="default"
                  icon={<Icon.Check size={14} />}
                  onClick={onConfirmBatch}
                  disabled={!!busyAction}
                >
                  {busyAction === "confirm" ? "处理中…" : "财务确认"}
                </Button>
              ) : null}
              {isPayable && b.status === "confirmed" && onNotifyStreamers ? (
                <Button
                  kind="default"
                  icon={<Icon.Bell size={14} />}
                  onClick={onNotifyStreamers}
                  disabled={!!busyAction}
                >
                  {busyAction === "notify" ? "发送中…" : "发送薪资明细"}
                </Button>
              ) : null}
              <Button
                kind="primary"
                icon={<Icon.Lock size={14} stroke="#fff" />}
                onClick={onLockBatch}
                disabled={!!busyAction || lockGate?.hasBlocking}
                title={
                  lockGate?.hasBlocking
                    ? lockBlockMessage
                    : lockGate?.evaluated
                      ? undefined
                      : "锁定前请先运行「单项目结算校验」"
                }
              >
                {busyAction === "lock"
                  ? "处理中…"
                  : lockGate?.hasBlocking
                    ? "校验未通过 · 不可锁定"
                    : "确认并锁定"}
              </Button>
            </>
          )}
        </div>
      </Card>

      {/* Audit timeline */}
      <Card
        title="批次审计轨迹"
        extra={
          batchAudit.length ? (
            <Badge tone="neutral">{batchAudit.length} 条</Badge>
          ) : null
        }
        padded={true}
      >
        {batchAudit.length ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {batchAudit.map((entry) => (
              <div
                key={entry.id}
                style={{
                  display: "flex",
                  gap: 10,
                  paddingBottom: 10,
                  borderBottom: "1px solid var(--line)",
                }}
              >
                <Avatar
                  name={entry.actorName || entry.actorRole || "系统"}
                  size={26}
                />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "baseline",
                      gap: 8,
                      flexWrap: "wrap",
                    }}
                  >
                    <span
                      style={{
                        fontSize: 12.5,
                        fontWeight: 600,
                        color: "var(--ink-900)",
                      }}
                    >
                      {entry.actorName || "系统"}
                    </span>
                    <Badge tone={auditModuleTone(entry.module)}>
                      {auditModuleLabel(entry.module)} / {entry.action}
                    </Badge>
                    <span style={{ fontSize: 11, color: "var(--ink-400)" }}>
                      {formatOpsMinute(entry.createdAt)}
                    </span>
                  </div>
                  {entry.reason ? (
                    <div
                      style={{
                        fontSize: 12,
                        color: "var(--ink-500)",
                        marginTop: 2,
                      }}
                    >
                      原因：{entry.reason}
                    </div>
                  ) : null}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <EmptyHint
            title="暂无审计轨迹"
            hint="对该批次执行锁定/解锁/调整后，操作会记录在这里。点击上方「查看审计」可刷新。"
          />
        )}
      </Card>
    </div>
  );
}

// ===== src\screen-tasks.jsx =====
// ——— Screen: 排班与任务 ————————————————————————

function ScreenTasks({ go, focusRequest }) {
  const tasks = useOpsTasks();
  const ownerProjects = useOpsProjects();
  const collaborationProjects = useOpsCollaborationProjects();
  const streamers = useOpsStreamers();
  const applications = useOpsApplications();
  const actions = useOpsLiveActions();
  const {
    projects: projectData,
    streamers: streamerData,
    applications: applicationData,
  } = React.useContext(OpsLiveDataContext);
  const projects = React.useMemo(
    () => [
      ...ownerProjects,
      ...collaborationProjects.filter(
        (project) =>
          !project.collaborationApplicationId &&
          (project.collaborationId || project.collaborationAgreementId),
      ),
    ],
    [collaborationProjects, ownerProjects],
  );
  const [view, setView] = React.useState("board");
  const [project, setProject] = React.useState("all");
  const [streamerFilter, setStreamerFilter] = React.useState("all");
  const [statusFilter, setStatusFilter] = React.useState("all");
  const [selectedTask, setSelectedTask] = React.useState(null);
  const [busyAction, setBusyAction] = React.useState(null);
  const [batchOpen, setBatchOpen] = React.useState(false);
  const [batchDraft, setBatchDraft] = React.useState({
    projectId: "",
    streamerIds: "",
    dateKey: formatDateKey(new Date()),
    startTime: "20:00",
    endTime: "23:30",
  });
  const [taskMessage, setTaskMessage] = React.useState("");

  // 外部跳转请求（go("tasks", { view, projectId, projectName })）：
  // token 每次跳转都会变化（对象随之换新），据此重放视图与项目筛选预置。
  React.useEffect(() => {
    if (!focusRequest) return;
    setView(focusRequest.view || "anomaly");
    const projectKey = focusRequest.projectId || focusRequest.projectName;
    if (projectKey) setProject(projectKey);
  }, [focusRequest]);

  const liveCount = tasks.filter((t) => t.status === "live").length;
  const pendingReportCount = tasks.filter(
    (t) => t.status === "pending_report",
  ).length;
  const pendingReviewCount = tasks.filter(
    (t) => t.status === "pending_review",
  ).length;
  const anomalyCount = tasks.filter(isTaskOperationalAnomaly).length;
  const todayCount = tasks.filter(
    (t) => t.dayIdx === SCHEDULE_WEEK.todayIdx,
  ).length;
  const taskFilters = {
    project,
    streamer: streamerFilter,
    status: statusFilter,
  };
  const filteredTasks = tasks.filter((task) =>
    taskMatchesTaskFilters(task, taskFilters, projects),
  );
  const selectedProject =
    project === "all" ? null : projects.find((item) => item.id === project);

  React.useEffect(() => {
    if (projectData == null && actions.refreshProjects) {
      actions
        .refreshProjects()
        .catch((error) => warnBackgroundRefreshFailure("tasks", error));
    }
  }, [actions, projectData]);

  React.useEffect(() => {
    if (streamerData == null && actions.refreshStreamers) {
      actions
        .refreshStreamers()
        .catch((error) => warnBackgroundRefreshFailure("tasks", error));
    }
  }, [actions, streamerData]);

  React.useEffect(() => {
    setBatchDraft((draft) => {
      const nextProjectId = draft.projectId || projects[0]?.id || "";
      const nextStreamerIds =
        draft.streamerIds ||
        joinedStreamersForProject(nextProjectId, streamers, applications)
          .map((streamer) => streamer.id)
          .join(",");
      if (
        draft.projectId === nextProjectId &&
        draft.streamerIds === nextStreamerIds
      ) {
        return draft;
      }
      return {
        ...draft,
        projectId: nextProjectId,
        streamerIds: nextStreamerIds,
      };
    });
  }, [applications, projects, streamers]);

  React.useEffect(() => {
    if (applicationData == null && actions.refreshApplications) {
      actions
        .refreshApplications()
        .catch((error) => warnBackgroundRefreshFailure("tasks", error));
    }
  }, [actions, applicationData]);

  React.useEffect(() => {
    if (project === "all") return;
    setBatchDraft((draft) =>
      draft.projectId === project ? draft : { ...draft, projectId: project },
    );
  }, [project]);

  const runTaskAction = async (actionName, fn) => {
    if (busyAction) return;
    setBusyAction(actionName);
    try {
      await fn();
    } catch (error) {
      setTaskMessage(formatTaskActionError(error));
    } finally {
      setBusyAction(null);
    }
  };

  const openNewTask = () => {
    const defaultProject =
      project === "all"
        ? projects[0]
        : projects.find((item) => item.id === project);
    if (!defaultProject) {
      globalThis.alert?.("请先创建项目和主播档案。");
      return;
    }
    const eligibleStreamers = joinedStreamersForProject(
      defaultProject.id,
      streamers,
      applications,
    );
    const defaultStreamer =
      streamerFilter === "all"
        ? eligibleStreamers[0]
        : eligibleStreamers.find((item) => item.id === streamerFilter);

    setSelectedTask({
      _new: true,
      dayIdx: SCHEDULE_WEEK.todayIdx,
      projectId: defaultProject.id,
      streamerId: defaultStreamer?.id || "",
    });
  };

  const createTask = async (input) => {
    await runTaskAction("create", async () => {
      const taskProject = projects.find((item) => item.id === input.projectId);
      const collaborationId =
        taskProject?.collaborationId ?? taskProject?.collaborationAgreementId;
      await actions.createLiveTask?.({
        ...input,
        ...(collaborationId ? { collaborationId } : {}),
      });
      setTaskMessage(
        `已创建任务并绑定项目：${
          taskProject?.name || displayRecordId(input.projectId, "项目")
        }`,
      );
      setSelectedTask(null);
    });
  };

  const cancelTask = async (task) => {
    await runTaskAction("cancel", async () => {
      await actions.cancelLiveTask?.(task.id, {
        reason: "经营端页面取消任务",
      });
      setSelectedTask(null);
    });
  };

  const updateBatchDraft = (field) => (event) => {
    setBatchDraft((draft) => ({ ...draft, [field]: event.target.value }));
  };

  const submitBatchTasks = (event) => {
    event.preventDefault();
    return runTaskAction("batch", async () => {
      const project = projectById(batchDraft.projectId, projects);
      if (!project) {
        setTaskMessage("请先选择项目");
        return;
      }

      const plannedStartAt = scheduleTimeToIso(
        batchDraft.dateKey,
        batchDraft.startTime,
      );
      const plannedEndAt = scheduleTimeToIso(
        batchDraft.dateKey,
        batchDraft.endTime,
      );
      const plannedDuration = scheduleMinutes(plannedStartAt, plannedEndAt);
      const eligibleStreamers = joinedStreamersForProject(
        project.id,
        streamers,
        applications,
      );
      const batchTasks = batchDraft.streamerIds
        .split(",")
        .map((id) => id.trim())
        .filter(Boolean)
        .map((streamerId) => {
          const streamer = eligibleStreamers.find(
            (item) => item.id === streamerId,
          );
          if (!streamer) {
            return null;
          }
          return {
            projectId: project.id,
            streamerId: streamer.id,
            title: `${project.name} · ${streamer.alias}`,
            plannedStartAt,
            plannedEndAt,
            plannedDuration,
            note: "经营端批量排班创建",
            ...(project.collaborationId || project.collaborationAgreementId
              ? {
                  collaborationId:
                    project.collaborationId ?? project.collaborationAgreementId,
                }
              : {}),
          };
        })
        .filter(Boolean);

      if (batchTasks.length === 0) {
        setTaskMessage(JOINED_STREAMER_REQUIRED_MESSAGE);
        return;
      }

      setTaskMessage("");
      await actions.createLiveTasks?.({ tasks: batchTasks });
      setTaskMessage(
        `已为 ${project.name} 创建 ${batchTasks.length} 个排班任务`,
      );
      setBatchOpen(false);
    });
  };

  return (
    <>
      <PageHeader
        title="排班与任务"
        actions={
          <>
            <Button
              kind="default"
              icon={<Icon.Upload size={14} />}
              onClick={() => setTaskMessage("Excel 导入后台暂未接入")}
            >
              从 Excel 导入
            </Button>
            <Button
              kind="default"
              icon={<Icon.Calendar size={14} />}
              onClick={() => {
                setBatchOpen((value) => !value);
                setTaskMessage("");
              }}
              disabled={!!busyAction}
            >
              {busyAction === "batch" ? "排班中…" : "批量排班"}
            </Button>
            <Button
              kind="primary"
              icon={<Icon.Plus size={14} stroke="#fff" />}
              onClick={openNewTask}
              disabled={!!busyAction}
            >
              {busyAction === "create" ? "创建中…" : "新建任务"}
            </Button>
          </>
        }
      />

      <div
        style={{
          padding: 20,
          display: "flex",
          flexDirection: "column",
          gap: 16,
        }}
      >
        {/* Grouped task strip — primary 今日任务 + compact secondaries */}
        <Card
          padded={false}
          bodyStyle={{
            display: "flex",
            alignItems: "center",
            gap: 24,
            padding: "16px 18px",
            flexWrap: "wrap",
            rowGap: 12,
          }}
        >
          <div
            style={{
              paddingRight: 24,
              borderRight: "1px solid var(--line)",
              minWidth: 140,
            }}
          >
            <div style={{ fontSize: 12, color: "var(--ink-400)" }}>今日任务</div>
            <div
              style={{
                display: "flex",
                alignItems: "baseline",
                gap: 6,
                marginTop: 4,
              }}
            >
              <span
                className="num"
                style={{
                  fontSize: 26,
                  fontWeight: 600,
                  color: "var(--ink-900)",
                  letterSpacing: "-0.02em",
                }}
              >
                {todayCount}
              </span>
              <span style={{ fontSize: 12, color: "var(--ink-400)" }}>个</span>
            </div>
            <div style={{ fontSize: 12, marginTop: 4, color: "var(--ink-400)" }}>
              {SCHEDULE_WEEK.days[SCHEDULE_WEEK.todayIdx]?.date ?? "本周"}
            </div>
          </div>
          <div
            style={{
              display: "flex",
              gap: 28,
              flex: 1,
              flexWrap: "wrap",
              rowGap: 12,
            }}
          >
            <div style={{ minWidth: 0 }}>
              <div
                style={{
                  fontSize: 12,
                  color: "var(--ink-400)",
                  display: "flex",
                  alignItems: "center",
                  gap: 6,
                }}
              >
                <span
                  style={{
                    width: 6,
                    height: 6,
                    borderRadius: 999,
                    background: "var(--blue-600)",
                    boxShadow: "0 0 0 3px rgba(30,80,200,0.25)",
                  }}
                />
                正在直播
              </div>
              <div
                style={{
                  display: "flex",
                  alignItems: "baseline",
                  gap: 4,
                  marginTop: 4,
                }}
              >
                <span
                  className="num"
                  style={{
                    fontSize: 18,
                    fontWeight: 600,
                    color: "var(--ink-900)",
                  }}
                >
                  {liveCount}
                </span>
                <span style={{ fontSize: 11, color: "var(--ink-400)" }}>个</span>
              </div>
            </div>
            <MiniStat
              label="待报数 / 待审核"
              value={`${pendingReportCount} / ${pendingReviewCount}`}
            />
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 12, color: "var(--ink-400)" }}>异常任务</div>
              <div
                style={{
                  display: "flex",
                  alignItems: "baseline",
                  gap: 4,
                  marginTop: 4,
                }}
              >
                <span
                  className="num"
                  style={{
                    fontSize: 18,
                    fontWeight: 600,
                    color:
                      anomalyCount > 0
                        ? "var(--danger-600)"
                        : "var(--ink-900)",
                  }}
                >
                  {anomalyCount}
                </span>
                <span style={{ fontSize: 11, color: "var(--ink-400)" }}>项</span>
              </div>
              <div
                style={{
                  fontSize: 11,
                  marginTop: 2,
                  color:
                    anomalyCount > 0 ? "var(--danger-600)" : "var(--ink-400)",
                }}
              >
                {anomalyCount > 0 ? "需复核" : "正常"}
              </div>
            </div>
            <MiniStat
              label="本周已排"
              value={tasks.length}
              unit="个"
              hint={`共 ${streamers.length} 位主播`}
            />
          </div>
        </Card>

        <TaskProjectMappingStrip
          project={selectedProject}
          projects={projects}
          tasks={filteredTasks}
          totalTasks={tasks.length}
          onOpenProject={
            selectedProject ? () => go("project", selectedProject.id) : null
          }
        />

        {taskMessage ? (
          <div
            aria-live="polite"
            style={{
              padding: "10px 12px",
              border: "1px solid var(--line)",
              borderRadius: 8,
              background: "var(--bg-soft)",
              color: taskMessage.includes("失败")
                ? "var(--danger-600)"
                : "var(--ink-700)",
              fontSize: 12,
            }}
          >
            {taskMessage}
          </div>
        ) : null}

        {batchOpen ? (
          <form
            onSubmit={submitBatchTasks}
            style={{
              display: "grid",
              gridTemplateColumns:
                "minmax(160px, 0.9fr) minmax(220px, 1.2fr) 150px 120px 120px auto",
              alignItems: "end",
              gap: 10,
              padding: 14,
              border: "1px solid var(--line)",
              borderRadius: 8,
              background: "var(--bg-soft)",
            }}
          >
            <TaskFormLabel label="批量排班项目">
              <select
                value={batchDraft.projectId}
                onChange={updateBatchDraft("projectId")}
                style={taskInputStyle}
              >
                {projects.map((item) => (
                  <option key={item.id} value={item.id}>
                    {item.name}
                  </option>
                ))}
              </select>
            </TaskFormLabel>
            <TaskFormLabel label="批量排班主播">
              <input
                value={batchDraft.streamerIds}
                onChange={updateBatchDraft("streamerIds")}
                placeholder="streamer-one,streamer-two"
                style={taskInputStyle}
              />
            </TaskFormLabel>
            <TaskFormLabel label="排班日期">
              <input
                type="date"
                value={batchDraft.dateKey}
                onChange={updateBatchDraft("dateKey")}
                style={taskInputStyle}
              />
            </TaskFormLabel>
            <TaskFormLabel label="开始时间">
              <input
                type="time"
                value={batchDraft.startTime}
                onChange={updateBatchDraft("startTime")}
                style={taskInputStyle}
              />
            </TaskFormLabel>
            <TaskFormLabel label="结束时间">
              <input
                type="time"
                value={batchDraft.endTime}
                onChange={updateBatchDraft("endTime")}
                style={taskInputStyle}
              />
            </TaskFormLabel>
            <Button kind="primary" type="submit" disabled={!!busyAction}>
              确认批量排班
            </Button>
          </form>
        ) : null}

        <Card padded={false}>
          {/* View toggle + filters */}
          <div
            style={{
              padding: "0 14px",
              borderBottom: "1px solid var(--line)",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 10,
            }}
          >
            <Tabs
              value={view}
              onChange={setView}
              items={[
                { key: "board", label: "项目排班看板" },
                { key: "list", label: "任务列表", count: tasks.length },
                { key: "anomaly", label: "异常任务", count: anomalyCount },
                { key: "mine", label: "我的任务" },
              ]}
            />
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <ProjectFilter
                value={project}
                onChange={setProject}
                projects={projects}
              />
              <TaskInlineFilter
                label="主播筛选"
                value={streamerFilter}
                onChange={setStreamerFilter}
                options={streamers.map((streamer) => ({
                  value: streamer.id,
                  label: streamer.alias,
                }))}
              />
              <TaskInlineFilter
                label="状态筛选"
                value={statusFilter}
                onChange={setStatusFilter}
                options={Object.entries(TASK_STATUS).map(([value, item]) => ({
                  value,
                  label: item.label,
                }))}
              />
            </div>
          </div>

          <div>
            {view === "board" && (
              <ScheduleBoard
                filters={taskFilters}
                onSelectTask={setSelectedTask}
              />
            )}
            {view === "list" && (
              <TaskList
                tasks={filteredTasks}
                projects={projects}
                streamers={streamers}
                onSelectTask={setSelectedTask}
              />
            )}
            {view === "anomaly" && (
              <AnomalyList
                tasks={filteredTasks}
                projects={projects}
                streamers={streamers}
                onSelectTask={setSelectedTask}
              />
            )}
            {view === "mine" && <MyTasksView />}
          </div>
        </Card>
      </div>

      {selectedTask && (
        <TaskDrawer
          task={selectedTask}
          projects={projects}
          streamers={streamers}
          applications={applications}
          onClose={() => setSelectedTask(null)}
          onCreateTask={createTask}
          onCancelTask={cancelTask}
          busyAction={busyAction}
          go={go}
        />
      )}
    </>
  );
}

const taskInputStyle = {
  width: "100%",
  height: 32,
  border: "1px solid var(--line-strong)",
  borderRadius: 6,
  background: "#fff",
  color: "var(--ink-700)",
  fontSize: 13,
  outline: "none",
  padding: "0 10px",
};

function TaskFormLabel({ label, children }) {
  return (
    <label
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 6,
        fontSize: 12,
        color: "var(--ink-500)",
        fontWeight: 600,
        minWidth: 0,
      }}
    >
      {label}
      {children}
    </label>
  );
}

function ProjectFilter({ value, onChange, projects = [] }) {
  return (
    <select
      aria-label="项目筛选"
      value={value}
      onChange={(event) => onChange?.(event.target.value)}
      style={{ ...taskInputStyle, width: 150, height: 28, fontSize: 12 }}
    >
      <option value="all">全部项目</option>
      {projects.map((project) => (
        <option key={project.id} value={project.id}>
          {project.name}
        </option>
      ))}
    </select>
  );
}

function TaskInlineFilter({ label, value, onChange, options }) {
  return (
    <select
      aria-label={label}
      value={value}
      onChange={(event) => onChange?.(event.target.value)}
      style={{ ...taskInputStyle, width: 122, height: 28, fontSize: 12 }}
    >
      <option value="all">{label}</option>
      {options.map((option) => (
        <option key={option.value} value={option.value}>
          {option.label}
        </option>
      ))}
    </select>
  );
}

function TaskProjectMappingStrip({
  project,
  projects = [],
  tasks = [],
  totalTasks = 0,
  onOpenProject,
}) {
  const anomalyCount = tasks.filter(isTaskOperationalAnomaly).length;
  const pendingCount = tasks.filter((task) =>
    ["pending_live", "live", "pending_report", "pending_review"].includes(
      task.status,
    ),
  ).length;

  if (!project) {
    return (
      <div
        style={{
          padding: "10px 12px",
          border: "1px solid var(--line)",
          borderRadius: 8,
          background: "var(--bg-soft)",
          display: "flex",
          alignItems: "center",
          gap: 10,
          fontSize: 12,
          color: "var(--ink-600)",
        }}
      >
        <Icon.Project size={15} stroke="var(--blue-600)" />
        <span>
          全部项目映射 · {projects.length} 个项目 · {totalTasks} 个任务
        </span>
        <span style={{ color: "var(--ink-400)" }}>
          选择项目后，新建任务和批量排班会自动绑定该项目。
        </span>
      </div>
    );
  }

  return (
    <div
      style={{
        padding: "10px 12px",
        border: "1px solid var(--line)",
        borderRadius: 8,
        background: "var(--bg-soft)",
        display: "flex",
        alignItems: "center",
        gap: 12,
        fontSize: 12,
        color: "var(--ink-600)",
      }}
    >
      <Icon.Project size={15} stroke="var(--blue-600)" />
      <span style={{ fontWeight: 600, color: "var(--ink-900)" }}>
        {project.name}
      </span>
      <span className="mono" style={{ color: "var(--ink-400)" }}>
        {project.code || "未设置编号"}
      </span>
      <span>负责人：{project.leadOps || "未分配"}</span>
      <span>
        周期：{project.start || "未配置"} → {project.end || "未配置"}
      </span>
      <span>
        当前筛选 {tasks.length} 个任务 · {pendingCount} 个待执行 ·{" "}
        {anomalyCount} 个异常
      </span>
      <div style={{ flex: 1 }} />
      {onOpenProject ? (
        <Button size="sm" kind="default" onClick={onOpenProject}>
          查看当前项目
        </Button>
      ) : null}
    </div>
  );
}

function taskMatchesTaskFilters(task, filters, projects = []) {
  const project = projects.find((item) => item.id === filters.project);
  const projectKeys = [
    filters.project,
    project?.id,
    project?.code,
    project?.name,
  ].filter(Boolean);
  const taskProjectKeys = [
    task.project,
    task.projectId,
    task.projectName,
  ].filter(Boolean);
  const matchesProject =
    filters.project === "all" ||
    taskProjectKeys.some((key) => projectKeys.includes(key));
  const matchesStreamer =
    filters.streamer === "all" ||
    [task.streamerId, task.streamerName]
      .filter(Boolean)
      .includes(filters.streamer);
  const statusKey = getTaskDisplayStatusKey(task);
  const matchesStatus =
    filters.status === "all" || statusKey === filters.status;
  return matchesProject && matchesStreamer && matchesStatus;
}

function getTaskDisplayStatusKey(task) {
  const baseStatus = task?.anomaly
    ? "abnormal"
    : task?.status || "pending_live";
  if (
    baseStatus === "pending_live" &&
    hasTaskPlannedWindowEnded(task?.plannedEndAt)
  ) {
    return "missed_live";
  }
  return baseStatus;
}

function hasTaskPlannedWindowEnded(plannedEndAt) {
  if (!plannedEndAt) return false;
  const plannedEnd = new Date(plannedEndAt);
  return (
    !Number.isNaN(plannedEnd.getTime()) && Date.now() > plannedEnd.getTime()
  );
}

function getTaskOperationalAnomalyKey(task) {
  if (task?.anomaly) return task.anomaly;
  if (task?.status === "abnormal") return "abnormal";
  if (getTaskDisplayStatusKey(task) === "missed_live") return "not_started";
  return "";
}

function isTaskOperationalAnomaly(task) {
  return Boolean(getTaskOperationalAnomalyKey(task));
}

function taskOperationalAnomalyDescription(anomalyKey) {
  const descriptions = {
    not_started:
      "计划窗口已结束但系统未记录开播，建议联系主播补充未直播原因或重新排班。",
    unstart:
      "计划窗口已结束但系统未记录开播，建议联系主播补充未直播原因或重新排班。",
    not_reported: "直播任务已结束但尚未提交报数，建议提醒主播尽快补报。",
    report_overdue: "已超过项目上传期限，建议运营提示主播尽快补传截图。",
    late_report: "已超过项目上传期限，建议运营提示主播尽快补传截图。",
    missing_checkout_screenshot: "任务缺少下播截图，建议提醒主播补充履约证据。",
    live_over_48h:
      "直播持续超过 48 小时未上传下播截图，建议主动联系主播并提示截图上传。",
    unstopped:
      "直播持续超过 48 小时未上传下播截图，建议主动联系主播并提示截图上传。",
    short: "实际直播时长低于计划时长 75%，触发时长不足异常。",
    rejected: "报数审核被驳回后尚未重新提交，建议跟进主播补充材料。",
    conflict: "该任务与同主播其他排班存在时间冲突，请调整排班窗口。",
    abnormal: "任务已进入异常状态，请运营跟进处理并记录原因。",
  };
  return descriptions[anomalyKey] || descriptions.abnormal;
}

function resolveTaskProject(task, projects = []) {
  const taskProjectKeys = [
    task?.projectId,
    task?.project,
    task?.projectName,
  ].filter(Boolean);
  return (
    projects.find((project) =>
      [project.id, project.code, project.name].some((key) =>
        taskProjectKeys.includes(key),
      ),
    ) || null
  );
}

function resolveTaskStreamer(task, streamers = []) {
  const taskStreamerKeys = [task?.streamerId, task?.streamerName].filter(
    Boolean,
  );
  return (
    streamers.find((streamer) =>
      [streamer.id, streamer.alias, streamer.real].some((key) =>
        taskStreamerKeys.includes(key),
      ),
    ) || null
  );
}

// ——— Schedule Board (week / streamer grid) ————————

function ScheduleBoard({ filters, onSelectTask }) {
  const tasks = useOpsTasks();
  const projects = useOpsProjects();
  const knownStreamers = useOpsStreamers();
  const [unit, setUnit] = React.useState("day"); // 'day' | 'hour'
  const [toolbarMessage, setToolbarMessage] = React.useState("");
  const [weekOffset, setWeekOffset] = React.useState(0);

  const weekMeta = React.useMemo(() => {
    if (weekOffset === 0) {
      return { label: "本周排班", days: SCHEDULE_WEEK.days };
    }
    const base = new Date();
    base.setDate(base.getDate() + weekOffset * 7);
    const week = createScheduleWeek(base);
    return {
      label: `${week.days[0].date} - ${week.days[6].date}`,
      days: week.days.map((day) => ({ ...day, today: false })),
    };
  }, [weekOffset]);

  // Filter tasks
  const visibleTasks = tasks.filter((task) =>
    taskMatchesTaskFilters(task, filters, projects),
  );
  // Sample tasks use a relative day index within the current week, so only the
  // current week carries schedule data; other weeks render an empty board.
  const boardTasks = weekOffset === 0 ? visibleTasks : [];
  const streamerIds = Array.from(
    new Set(
      boardTasks
        .map((task) => task.streamerId || task.streamerName)
        .filter(Boolean),
    ),
  );
  const streamers = streamerIds.map((id) => {
    const fromKnown = knownStreamers.find((streamer) => streamer.id === id);
    if (fromKnown) return fromKnown;
    const task = boardTasks.find(
      (item) => item.streamerId === id || item.streamerName === id,
    );
    return { id, alias: displayTaskStreamerName(task) };
  });
  const dayWidth = "minmax(140px, 1fr)";
  const HOUR_START = 12; // visible window: 12:00 - 24:00 (used in hour view)
  const HOUR_END = 24;

  if (weekOffset === 0 && !visibleTasks.length) {
    return (
      <div style={{ padding: 16 }}>
        <EmptyHint title="暂无排班数据" hint="创建排班或任务后会展示周视图。" />
      </div>
    );
  }

  return (
    <div>
      {/* Week toolbar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 12,
          padding: "12px 16px",
          borderBottom: "1px solid var(--line)",
          background: "var(--bg-soft)",
        }}
      >
        <button
          type="button"
          style={iconBtn}
          aria-label="上一周"
          onClick={() => {
            setToolbarMessage("");
            setWeekOffset((value) => value - 1);
          }}
        >
          <Icon.ChevLeft size={14} />
        </button>
        <div
          style={{
            fontSize: 13,
            fontWeight: 600,
            color: "var(--ink-900)",
            minWidth: 96,
            textAlign: "center",
          }}
        >
          {weekMeta.label}
        </div>
        <button
          type="button"
          style={iconBtn}
          aria-label="下一周"
          onClick={() => {
            setToolbarMessage("");
            setWeekOffset((value) => value + 1);
          }}
        >
          <Icon.ChevRight size={14} />
        </button>
        <Button
          size="sm"
          kind="default"
          onClick={() => {
            setWeekOffset(0);
            setToolbarMessage("");
          }}
        >
          今天
        </Button>

        {/* Unit toggle */}
        <div
          style={{
            display: "inline-flex",
            height: 28,
            padding: 2,
            background: "var(--ink-50)",
            borderRadius: 6,
            marginLeft: 4,
          }}
        >
          {[
            ["day", "1 天"],
            ["hour", "按小时"],
          ].map(([k, v]) => (
            <button
              key={k}
              onClick={() => setUnit(k)}
              style={{
                padding: "0 12px",
                height: 24,
                fontSize: 12,
                background: unit === k ? "#fff" : "transparent",
                border: "none",
                borderRadius: 4,
                cursor: "pointer",
                color: unit === k ? "var(--blue-700)" : "var(--ink-500)",
                fontWeight: unit === k ? 600 : 500,
                boxShadow:
                  unit === k ? "0 1px 2px rgba(15,23,42,0.08)" : "none",
              }}
            >
              {v}
            </button>
          ))}
        </div>

        <div style={{ flex: 1 }} />
        <div
          style={{
            display: "flex",
            gap: 12,
            fontSize: 11,
            color: "var(--ink-400)",
          }}
        >
          <Legend dot="var(--blue-600)" label="直播中" />
          <Legend dot="var(--violet-600)" label="待报数" />
          <Legend dot="var(--warn-600)" label="报数待审" />
          <Legend dot="var(--ok-600)" label="已完成" />
          <Legend dot="var(--danger-600)" label="异常" />
          <Legend dot="var(--ink-200)" label="待开播" />
        </div>
      </div>
      {toolbarMessage ? (
        <div
          aria-live="polite"
          style={{
            padding: "8px 16px 0",
            fontSize: 12,
            color: "var(--ink-500)",
          }}
        >
          {toolbarMessage}
        </div>
      ) : null}

      {/* Day header */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: `180px repeat(7, ${dayWidth})`,
          borderBottom: "1px solid var(--line)",
          background: "var(--bg-soft)",
        }}
      >
        <div
          style={{
            padding: "8px 12px",
            fontSize: 11,
            color: "var(--ink-400)",
            fontWeight: 500,
            borderRight: "1px solid var(--line)",
          }}
        >
          主播 / 日期
        </div>
        {weekMeta.days.map((d, i) => (
          <div
            key={i}
            style={{
              padding: "8px 12px",
              background: d.today ? "var(--blue-50)" : "transparent",
              borderRight: i < 6 ? "1px solid var(--line)" : "none",
              display: "flex",
              flexDirection: "column",
              gap: 2,
            }}
          >
            <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
              <span
                style={{
                  fontSize: 13,
                  fontWeight: 600,
                  color: d.today ? "var(--blue-700)" : "var(--ink-900)",
                }}
              >
                {d.label}
              </span>
              <span
                className="num"
                style={{
                  fontSize: 11,
                  color: d.today ? "var(--blue-700)" : "var(--ink-400)",
                }}
              >
                {d.date}
              </span>
              {d.today && <Badge tone="blue">今天</Badge>}
            </div>
            {unit === "hour" && (
              <div style={{ fontSize: 10.5, color: "var(--ink-300)" }}>
                {HOUR_START}:00 - {HOUR_END}:00
              </div>
            )}
          </div>
        ))}
      </div>

      {streamers.length === 0 ? (
        <div
          style={{
            padding: 32,
            textAlign: "center",
            color: "var(--ink-400)",
            fontSize: 13,
          }}
        >
          {weekMeta.label} 暂无排班记录。
        </div>
      ) : null}

      {/* Rows */}
      {streamers.map((s, ri) => {
        const sTasks = tasks.filter(
          (t) =>
            t.streamerId === s.id &&
            taskMatchesTaskFilters(t, filters, projects),
        );
        return (
          <div
            key={s.id}
            style={{
              display: "grid",
              gridTemplateColumns: `180px repeat(7, ${dayWidth})`,
              borderBottom:
                ri < streamers.length - 1 ? "1px solid var(--line)" : "none",
              minHeight: unit === "day" ? 88 : 78,
            }}
          >
            {/* Streamer cell */}
            <div
              style={{
                padding: "10px 12px",
                borderRight: "1px solid var(--line)",
                display: "flex",
                alignItems: "center",
                gap: 10,
                background: "#fff",
              }}
            >
              <Avatar name={s.alias} size={30} />
              <div style={{ minWidth: 0 }}>
                <div
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: "var(--ink-900)",
                  }}
                >
                  {s.alias}
                </div>
                <div
                  className="mono"
                  style={{ fontSize: 10.5, color: "var(--ink-400)" }}
                >
                  {sTasks.length} 个任务 ·{" "}
                  {sTasks
                    .reduce((sum, t) => sum + (t.endHour - t.startHour), 0)
                    .toFixed(1)}
                  h
                </div>
              </div>
            </div>

            {/* Day cells */}
            {weekMeta.days.map((d, di) => {
              const dayTasks = sTasks.filter((t) => t.dayIdx === di);
              return (
                <div
                  key={di}
                  style={{
                    position: "relative",
                    borderRight: di < 6 ? "1px solid var(--line)" : "none",
                    background: d.today
                      ? "rgba(238, 243, 255, 0.4)"
                      : "transparent",
                    padding: "8px 8px",
                  }}
                >
                  {/* Subtle hour mid-line only in hour mode */}
                  {unit === "hour" && (
                    <div
                      style={{
                        position: "absolute",
                        top: 0,
                        bottom: 0,
                        left: 0,
                        right: 0,
                        backgroundImage:
                          "linear-gradient(to right, transparent calc(50% - 0.5px), rgba(15,23,42,0.04) calc(50% - 0.5px), rgba(15,23,42,0.04) calc(50% + 0.5px), transparent calc(50% + 0.5px))",
                        pointerEvents: "none",
                      }}
                    />
                  )}

                  <div
                    style={{
                      position: "relative",
                      display: "flex",
                      flexDirection: "column",
                      gap: 4,
                    }}
                  >
                    {dayTasks.map((t) =>
                      unit === "day" ? (
                        <DayTaskBlock
                          key={t.id}
                          task={t}
                          projects={projects}
                          onClick={() => onSelectTask(t)}
                        />
                      ) : (
                        <HourTaskBar
                          key={t.id}
                          task={t}
                          projects={projects}
                          hourStart={HOUR_START}
                          hourEnd={HOUR_END}
                          onClick={() => onSelectTask(t)}
                        />
                      ),
                    )}
                    {dayTasks.length === 0 && (
                      <button
                        onClick={() =>
                          onSelectTask({
                            _new: true,
                            dayIdx: di,
                            streamerId: s.id,
                            projectId:
                              filters.project === "all"
                                ? projects[0]?.id
                                : filters.project,
                          })
                        }
                        style={{
                          background: "transparent",
                          border: "1px dashed var(--line-strong)",
                          borderRadius: 4,
                          height: unit === "day" ? 60 : 32,
                          color: "var(--ink-300)",
                          fontSize: 11,
                          cursor: "pointer",
                          display: "inline-flex",
                          alignItems: "center",
                          justifyContent: "center",
                          gap: 4,
                          opacity: 0,
                          transition: "opacity 120ms",
                        }}
                        onMouseEnter={(e) =>
                          (e.currentTarget.style.opacity = 0.8)
                        }
                        onMouseLeave={(e) =>
                          (e.currentTarget.style.opacity = 0)
                        }
                      >
                        <Icon.Plus size={11} stroke="var(--ink-400)" /> 排班
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        );
      })}
    </div>
  );
}

// Day-unit block — full width within its day cell
