// ——— Anomaly List ———————————————————

function AnomalyList({ tasks, projects = [], streamers = [], onSelectTask }) {
  const actions = useOpsLiveActions();
  const [actionMessage, setActionMessage] = React.useState("");
  const [scanBusy, setScanBusy] = React.useState("");
  const [resolvingId, setResolvingId] = React.useState("");
  const resolveOne = async (a) => {
    if (resolvingId) return;
    setResolvingId(a.id);
    setActionMessage("");
    try {
      await actions.resolveTaskAnomaly?.(a.id);
      setActionMessage(`已标记处理：${a.streamer} · ${a.name}`);
    } catch (error) {
      setActionMessage(error?.message || "标记处理失败，请稍后重试。");
    } finally {
      setResolvingId("");
    }
  };
  const anomalies = tasks.filter(isTaskOperationalAnomaly).map((t) => {
    const anomalyKey = getTaskOperationalAnomalyKey(t);
    const project = resolveTaskProject(t, projects);
    const streamer = resolveTaskStreamer(t, streamers);
    return {
      ...t,
      projectDisplay: project?.name || t.projectName || t.project,
      streamer: streamer?.alias || t.streamerName,
      typeKey: anomalyKey,
    };
  });

  // Group by type
  const groups = {};
  anomalies.forEach((a) => {
    (groups[a.typeKey] = groups[a.typeKey] || []).push(a);
  });

  const runAnomalyScan = async (mode) => {
    if (scanBusy) return;
    setScanBusy(mode);
    setActionMessage("");
    try {
      const result = await actions.scanAnomalies?.();
      const detectedCount = result?.detectedCount ?? 0;
      const sentCount = result?.sentCount ?? 0;
      setActionMessage(
        mode === "dispatch"
          ? `异常批量分派完成：发现 ${detectedCount} 项，已分派 ${sentCount} 条通知。`
          : `异常扫描完成：发现 ${detectedCount} 项，已分派 ${sentCount} 条通知。`,
      );
    } catch (error) {
      setActionMessage(error?.message || "异常扫描失败，请稍后重试。");
    } finally {
      setScanBusy("");
    }
  };

  return (
    <div
      style={{ padding: 16, display: "flex", flexDirection: "column", gap: 14 }}
    >
      {/* Bulk action strip */}
      <div
        style={{
          padding: "10px 14px",
          background: "var(--bg-soft)",
          borderRadius: 8,
          border: "1px solid var(--line)",
          display: "flex",
          alignItems: "center",
          gap: 10,
        }}
      >
        <Icon.Warn size={16} stroke="var(--danger-600)" />
        <div style={{ flex: 1, fontSize: 12.5, color: "var(--ink-700)" }}>
          检测到{" "}
          <b className="num" style={{ color: "var(--danger-600)" }}>
            {anomalies.length}
          </b>{" "}
          项异常 · 系统每小时自动扫描，扫描结果同步推送项目运营。
        </div>
        <Button
          size="sm"
          kind="default"
          onClick={() => runAnomalyScan("history")}
          disabled={Boolean(scanBusy)}
        >
          {scanBusy === "history" ? "扫描中" : "扫描历史"}
        </Button>
        <Button
          size="sm"
          kind="primary"
          onClick={() => runAnomalyScan("dispatch")}
          disabled={Boolean(scanBusy)}
        >
          {scanBusy === "dispatch" ? "分派中" : "批量分派处理"}
        </Button>
      </div>
      {actionMessage ? (
        <div
          aria-live="polite"
          style={{ fontSize: 12, color: "var(--ink-500)" }}
        >
          {actionMessage}
        </div>
      ) : null}

      {Object.entries(groups).map(([type, items]) => (
        <div key={type}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              marginBottom: 8,
            }}
          >
            <Badge
              tone={(ANOMALY_TYPES[type] || ANOMALY_TYPES.abnormal).tone}
              dot
            >
              {(ANOMALY_TYPES[type] || ANOMALY_TYPES.abnormal).label}
            </Badge>
            <span style={{ fontSize: 12, color: "var(--ink-400)" }}>
              {items.length} 项
            </span>
          </div>
          <Card padded={false}>
            {items.map((a, i) => (
              <div
                key={a.id}
                style={{
                  padding: "12px 16px",
                  display: "flex",
                  alignItems: "center",
                  gap: 12,
                  borderBottom:
                    i < items.length - 1 ? "1px solid var(--line)" : "none",
                }}
              >
                <Avatar name={a.streamer} size={32} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div
                    style={{ display: "flex", alignItems: "baseline", gap: 8 }}
                  >
                    <span
                      style={{
                        fontSize: 13,
                        fontWeight: 600,
                        color: "var(--ink-900)",
                      }}
                    >
                      {a.streamer}
                    </span>
                    <span
                      className="mono"
                      style={{ fontSize: 11, color: "var(--ink-400)" }}
                    >
                      {displayRecordId(a.id, "异常任务")} · {a.projectDisplay}
                    </span>
                  </div>
                  <div
                    style={{
                      fontSize: 12,
                      color: "var(--ink-500)",
                      marginTop: 2,
                    }}
                  >
                    {a.name} · {taskPlannedDateLabel(a)}
                    {Number.isFinite(a.startHour) && Number.isFinite(a.endHour)
                      ? ` ${formatHour(a.startHour)} - ${formatHour(a.endHour)}`
                      : ""}
                  </div>
                </div>
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "flex-end",
                    gap: 4,
                  }}
                >
                  {/* 检测时间后台未回传，不造伪数据，显示占位符。 */}
                  <span style={{ fontSize: 11, color: "var(--ink-300)" }}>
                    —
                  </span>
                  <div style={{ display: "flex", gap: 6 }}>
                    <Button
                      size="sm"
                      kind="ghost"
                      onClick={() =>
                        setActionMessage(
                          `${a.streamer} 的联系通道后台暂未接入。`,
                        )
                      }
                    >
                      联系主播
                    </Button>
                    <Button
                      size="sm"
                      kind="default"
                      onClick={() =>
                        onSelectTask
                          ? onSelectTask(a)
                          : setActionMessage(
                              `已定位异常任务：${displayRecordId(a.id, "任务")}`,
                            )
                      }
                    >
                      查看任务
                    </Button>
                    <Button
                      size="sm"
                      kind="primary"
                      onClick={() => resolveOne(a)}
                      disabled={resolvingId === a.id}
                    >
                      {resolvingId === a.id ? "处理中…" : "标记处理"}
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </Card>
        </div>
      ))}
    </div>
  );
}

