// ——— Task Drawer (right panel) ——————————

function TaskDrawer({
  task,
  projects,
  streamers,
  applications,
  onClose,
  onCreateTask,
  onCancelTask,
  busyAction,
  go,
}) {
  const [drawerMessage, setDrawerMessage] = React.useState("");
  const [reviewOpen, setReviewOpen] = React.useState(false);
  const reviewTriggerRef = React.useRef(null);
  const actions = useOpsLiveActions();
  const currentUser = useOpsCurrentUser();
  const [operateBusy, setOperateBusy] = React.useState(false);
  // 代操作成功后本地推进状态：drawer 拿到的 task 是打开时的快照，
  // 列表刷新不会回写进来，避免出现「已代开播仍显示代开播」的误导按钮。
  const [operatedStatus, setOperatedStatus] = React.useState(null);
  const [editing, setEditing] = React.useState(false);
  const [editForm, setEditForm] = React.useState({
    title: "",
    startHour: 20,
    endHour: 23,
  });
  const [editBusy, setEditBusy] = React.useState(false);
  const [editError, setEditError] = React.useState("");

  React.useLayoutEffect(() => {
    if (reviewOpen || !reviewTriggerRef.current) return;
    reviewTriggerRef.current.focus();
    reviewTriggerRef.current = null;
  }, [reviewOpen]);

  const openReview = (event) => {
    reviewTriggerRef.current = event.currentTarget;
    setReviewOpen(true);
  };

  const openEdit = () => {
    setEditForm({
      title: task.name || "",
      startHour: task.startHour ?? 20,
      endHour: task.endHour ?? 23,
    });
    setEditError("");
    setDrawerMessage("");
    setEditing(true);
  };
  const submitEdit = async (event) => {
    event.preventDefault();
    if (editBusy) return;
    const startHour = Number(editForm.startHour);
    const endHour = Number(editForm.endHour);
    if (!(endHour > startHour)) {
      setEditError("结束时间需晚于开始时间。");
      return;
    }
    setEditBusy(true);
    setEditError("");
    try {
      const startIso = dayScheduleTimeToIso(task.dayIdx, startHour);
      const endIso = dayScheduleTimeToIso(task.dayIdx, endHour);
      await actions.updateLiveTask?.(task.id, {
        title: editForm.title.trim() || undefined,
        plannedStartAt: startIso,
        plannedEndAt: endIso,
        plannedDuration: scheduleMinutes(startIso, endIso),
      });
      setEditing(false);
      setDrawerMessage("排班已更新。");
    } catch (error) {
      setEditError(error?.message || "更新失败，请稍后重试。");
    } finally {
      setEditBusy(false);
    }
  };
  if (task._new) {
    return (
      <NewTaskDrawer
        task={task}
        projects={projects}
        streamers={streamers}
        applications={applications}
        onClose={onClose}
        onCreateTask={onCreateTask}
      />
    );
  }

  const s = resolveTaskStreamer(task, streamers);
  const p = resolveTaskProject(task, projects);
  const streamerName = s?.alias || displayTaskStreamerName(task);
  const projectName = p?.name || task.projectName || task.project;
  const statusKey = getTaskDisplayStatusKey(task);
  const flowStatusKey = operatedStatus || task.status || "pending_live";
  const canOperateTask = canOperateLiveTaskInUi(currentUser.role);
  const operateLiveTask = async (mode) => {
    const actionLabel = mode === "start" ? "代开播" : "代下播";
    if (operateBusy) return;
    const confirmed = globalThis.confirm?.(
      `确认${actionLabel}「${task.name}」？该操作会立即变更任务状态。`,
    );
    if (!confirmed) return;
    setOperateBusy(true);
    setDrawerMessage("");
    try {
      if (mode === "start") {
        await actions.startLiveTask?.(task.id);
        setOperatedStatus("live");
        setDrawerMessage("已代开播，任务进入「直播中」。");
      } else {
        await actions.stopLiveTask?.(task.id);
        setOperatedStatus("pending_report");
        setDrawerMessage("已代下播，任务进入「待报数」。");
      }
    } catch (error) {
      setDrawerMessage(error?.message || `${actionLabel}失败，请稍后重试。`);
    } finally {
      setOperateBusy(false);
    }
  };
  const taskAnomalyKey = getTaskOperationalAnomalyKey(task);
  const taskAnomalyMeta =
    ANOMALY_TYPES[taskAnomalyKey] || ANOMALY_TYPES.abnormal;
  const st = TASK_STATUS[statusKey] || TASK_STATUS.pending_live;
  const showHeaderAnomalyBadge =
    taskAnomalyKey && taskAnomalyMeta.label !== st.label;

  return (
    <Drawer
      onClose={onClose}
      suspended={reviewOpen}
      title={
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span
            className="mono"
            style={{ fontSize: 13, color: "var(--ink-400)" }}
          >
            {displayRecordId(task.id, "任务")}
          </span>
          <Badge tone={st.tone} dot>
            {st.label}
          </Badge>
          {showHeaderAnomalyBadge && (
            <Badge tone={taskAnomalyMeta.tone}>{taskAnomalyMeta.label}</Badge>
          )}
        </div>
      }
    >
      <div
        style={{
          padding: 20,
          display: "flex",
          flexDirection: "column",
          gap: 16,
        }}
      >
        <div>
          <div
            style={{ fontSize: 16, fontWeight: 600, color: "var(--ink-900)" }}
          >
            {task.name}
          </div>
          <div style={{ fontSize: 12, color: "var(--ink-400)", marginTop: 4 }}>
            {projectName} · {p?.vendor || "经营舱"}
          </div>
        </div>

        <div
          style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}
        >
          <DrawerStat
            label="计划开播"
            value={`${SCHEDULE_WEEK.days[task.dayIdx].date} ${formatHour(task.startHour)}`}
          />
          <DrawerStat
            label="计划结束"
            value={`${SCHEDULE_WEEK.days[task.dayIdx].date} ${formatHour(task.endHour)}`}
          />
          <DrawerStat
            label="计划时长"
            value={`${(task.endHour - task.startHour).toFixed(1)} h`}
          />
          <DrawerStat label="任务类型" value={taskTypeLabel(task.type)} />
        </div>

        <div
          style={{
            padding: 14,
            background: "var(--bg-soft)",
            borderRadius: 8,
            border: "1px solid var(--line)",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              marginBottom: 10,
            }}
          >
            <Avatar name={streamerName} size={36} />
            <div>
              <div style={{ fontWeight: 600, color: "var(--ink-900)" }}>
                {streamerName}
              </div>
              <div
                className="mono"
                style={{ fontSize: 11, color: "var(--ink-400)" }}
              >
                {displayRecordId(s?.id || task.streamerId, "主播")} ·{" "}
                {s?.platforms?.join(" / ") || "直播账号"}
              </div>
            </div>
            <div style={{ flex: 1 }} />
            <Badge tone="blue">{s?.defaultRule || "CPT · 审核后入池"}</Badge>
          </div>
          <KV label="是否需要点击开播 / 停止">
            {(p?.needStartStop ?? true) ? "是 · 主播需在 App 内操作" : "否"}
          </KV>
          <KV label="录屏要求">
            {(p?.needScreening ?? true) ? "本项目强制录屏" : "不强制"}
          </KV>
          <KV label="项目编号">
            <span className="mono">{p?.code || "未设置编号"}</span>
          </KV>
          <KV label="项目负责人">{p?.leadOps || "未分配"}</KV>
          <KV label="项目周期">
            {p?.start || "未配置"} → {p?.end || "未配置"}
          </KV>
        </div>

        {/* Status timeline */}
        <div>
          <SectionTitle hint="任务流转">状态轨迹</SectionTitle>
          <Timeline
            events={[
              {
                time: "已创建",
                who: "系统",
                action: "排班创建",
                done: true,
              },
              {
                time: flowStatusKey === "pending_live" ? "待开播" : "已开播",
                who: streamerName,
                action: "点击开始直播",
                done: flowStatusKey !== "pending_live",
              },
              {
                time: flowStatusKey === "live" ? "进行中…" : "已结束",
                who: streamerName,
                action: "点击停止 + 上传下播截图",
                done: [
                  "pending_report",
                  "pending_review",
                  "completed",
                  "approved",
                ].includes(flowStatusKey),
                current: flowStatusKey === "live",
              },
              {
                time: "—",
                who: streamerName,
                action: "主播确认 OCR 结果",
                done: ["pending_review", "completed", "approved"].includes(
                  flowStatusKey,
                ),
              },
              {
                time: "—",
                who: "运营审核",
                action: "报数审核",
                done: ["completed", "approved"].includes(flowStatusKey),
              },
            ]}
          />
        </div>

        {taskAnomalyKey && (
          <div
            style={{
              padding: 14,
              borderRadius: 8,
              background: "var(--danger-50)",
              border: "1px solid #F3C4C9",
              display: "flex",
              gap: 12,
            }}
          >
            <span
              style={{
                width: 28,
                height: 28,
                borderRadius: 7,
                background: "var(--danger-600)",
                color: "#fff",
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
              }}
            >
              <Icon.Warn size={14} stroke="#fff" />
            </span>
            <div style={{ flex: 1 }}>
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 600,
                  color: "var(--danger-600)",
                }}
              >
                {taskAnomalyMeta.label}
              </div>
              <div
                style={{ fontSize: 12, color: "var(--ink-700)", marginTop: 4 }}
              >
                {taskOperationalAnomalyDescription(taskAnomalyKey)}
              </div>
            </div>
          </div>
        )}
        {drawerMessage ? (
          <div
            aria-live="polite"
            style={{
              padding: "10px 12px",
              border: "1px solid var(--line)",
              borderRadius: 8,
              background: "var(--bg-soft)",
              color: "var(--ink-700)",
              fontSize: 12,
            }}
          >
            {drawerMessage}
          </div>
        ) : null}

        {editing ? (
          <form
            onSubmit={submitEdit}
            style={{
              border: "1px solid var(--line)",
              borderRadius: 8,
              padding: 14,
              display: "flex",
              flexDirection: "column",
              gap: 10,
              background: "var(--bg-soft)",
            }}
          >
            <div
              style={{
                fontSize: 13,
                fontWeight: 600,
                color: "var(--ink-900)",
              }}
            >
              编辑排班
            </div>
            <label
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 6,
                fontSize: 12,
                color: "var(--ink-500)",
                fontWeight: 600,
              }}
            >
              任务标题
              <input
                value={editForm.title}
                onChange={(event) =>
                  setEditForm((form) => ({ ...form, title: event.target.value }))
                }
                style={{
                  height: 32,
                  border: "1px solid var(--line-strong)",
                  borderRadius: 6,
                  padding: "0 10px",
                  fontSize: 13,
                  outline: "none",
                }}
              />
            </label>
            <div style={{ display: "flex", gap: 10 }}>
              <label
                style={{
                  flex: 1,
                  display: "flex",
                  flexDirection: "column",
                  gap: 6,
                  fontSize: 12,
                  color: "var(--ink-500)",
                  fontWeight: 600,
                }}
              >
                开始 (时)
                <input
                  type="number"
                  min={0}
                  max={23}
                  value={editForm.startHour}
                  onChange={(event) =>
                    setEditForm((form) => ({
                      ...form,
                      startHour: event.target.value,
                    }))
                  }
                  style={{
                    height: 32,
                    border: "1px solid var(--line-strong)",
                    borderRadius: 6,
                    padding: "0 10px",
                    fontSize: 13,
                    outline: "none",
                  }}
                />
              </label>
              <label
                style={{
                  flex: 1,
                  display: "flex",
                  flexDirection: "column",
                  gap: 6,
                  fontSize: 12,
                  color: "var(--ink-500)",
                  fontWeight: 600,
                }}
              >
                结束 (时)
                <input
                  type="number"
                  min={1}
                  max={24}
                  value={editForm.endHour}
                  onChange={(event) =>
                    setEditForm((form) => ({
                      ...form,
                      endHour: event.target.value,
                    }))
                  }
                  style={{
                    height: 32,
                    border: "1px solid var(--line-strong)",
                    borderRadius: 6,
                    padding: "0 10px",
                    fontSize: 13,
                    outline: "none",
                  }}
                />
              </label>
            </div>
            {editError ? (
              <div style={{ fontSize: 12, color: "var(--danger-600)" }}>
                {editError}
              </div>
            ) : null}
            <div
              style={{ display: "flex", justifyContent: "flex-end", gap: 8 }}
            >
              <Button
                kind="default"
                type="button"
                disabled={editBusy}
                onClick={() => setEditing(false)}
              >
                取消
              </Button>
              <Button kind="primary" type="submit" disabled={editBusy}>
                {editBusy ? "保存中…" : "保存排班"}
              </Button>
            </div>
          </form>
        ) : null}
      </div>

      <div
        style={{
          padding: 12,
          borderTop: "1px solid var(--line)",
          background: "var(--bg-soft)",
          display: "flex",
          flexWrap: "wrap",
          gap: 8,
        }}
      >
        {canOperateTask && flowStatusKey === "pending_live" ? (
          <Button
            kind="primary"
            icon={<Icon.Play size={14} stroke="#fff" />}
            onClick={() => operateLiveTask("start")}
            disabled={operateBusy || !!busyAction}
          >
            {operateBusy ? "处理中…" : "代开播"}
          </Button>
        ) : null}
        {canOperateTask && flowStatusKey === "live" ? (
          <Button
            kind="primary"
            icon={<Icon.Play size={14} stroke="#fff" />}
            onClick={() => operateLiveTask("stop")}
            disabled={operateBusy || !!busyAction}
          >
            {operateBusy ? "处理中…" : "代下播"}
          </Button>
        ) : null}
        <Button
          kind="danger"
          icon={<Icon.X size={14} />}
          onClick={() => onCancelTask?.(task)}
          disabled={busyAction === "cancel"}
        >
          {busyAction === "cancel" ? "取消中…" : "取消任务"}
        </Button>
        <Button
          kind="primary"
          icon={<Icon.Sparkles size={14} />}
          onClick={openReview}
        >
          直播复盘
        </Button>
        <div style={{ flex: 1 }} />
        <Button kind="default" onClick={openEdit}>
          编辑排班
        </Button>
        <Button
          kind="default"
          onClick={() => p?.id && go?.("project", p.id)}
          disabled={!p?.id}
        >
          查看项目
        </Button>
        <Button kind="default" onClick={() => go?.("reports")}>
          查看报数
        </Button>
      </div>
      {reviewOpen && (
        <LiveReviewDrawer
          task={task}
          project={p}
          streamer={s}
          streamerName={streamerName}
          projectName={projectName}
          onClose={() => setReviewOpen(false)}
        />
      )}
    </Drawer>
  );
}

// ——— Live Review (直播复盘) ——————————————————————————————————
// 知识库本地兜底：线上走 /api/live-review，离线/未登录时落 localStorage，
// 让原型也能演示「保存到组织知识库 + AI 接入知识库反哺」的完整闭环。

const LIVE_REVIEW_LS_KEY = "jingying.liveReviewKB.v1";
const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function readLocalReviewDocs() {
  if (typeof window === "undefined" || !window.localStorage) return [];
  try {
    const raw = window.localStorage.getItem(LIVE_REVIEW_LS_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function writeLocalReviewDoc(doc) {
  if (typeof window === "undefined" || !window.localStorage) return;
  try {
    const docs = readLocalReviewDocs();
    docs.unshift(doc);
    window.localStorage.setItem(
      LIVE_REVIEW_LS_KEY,
      JSON.stringify(docs.slice(0, 200)),
    );
  } catch {
    /* ignore quota / serialization errors */
  }
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function inlineMarkdown(value) {
  return escapeHtml(value).replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
}

function splitMarkdownRow(line) {
  return line
    .trim()
    .replace(/^\|/, "")
    .replace(/\|$/, "")
    .split("|")
    .map((cell) => cell.trim());
}

// Minimal markdown renderer (headings / tables / lists / blockquote / bold).
function renderMarkdownToHtml(markdown) {
  const lines = String(markdown || "").split(/\r?\n/);
  const out = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const isTableRow = /^\s*\|.*\|\s*$/.test(line);
    const nextIsSep =
      i + 1 < lines.length && /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1]);
    if (isTableRow && nextIsSep) {
      const header = splitMarkdownRow(line);
      i += 2;
      const body = [];
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) {
        body.push(splitMarkdownRow(lines[i]));
        i += 1;
      }
      const head = header
        .map((cell) => `<th>${inlineMarkdown(cell)}</th>`)
        .join("");
      const rows = body
        .map(
          (row) =>
            `<tr>${row.map((cell) => `<td>${inlineMarkdown(cell)}</td>`).join("")}</tr>`,
        )
        .join("");
      out.push(
        `<table><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table>`,
      );
      continue;
    }
    const heading = line.match(/^(#{2,4})\s+(.*)$/);
    if (heading) {
      const level = heading[1].length;
      out.push(`<h${level}>${inlineMarkdown(heading[2])}</h${level}>`);
      i += 1;
      continue;
    }
    if (/^\s*>\s?/.test(line)) {
      out.push(
        `<blockquote>${inlineMarkdown(line.replace(/^\s*>\s?/, ""))}</blockquote>`,
      );
      i += 1;
      continue;
    }
    if (/^\s*[-*]\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(
          `<li>${inlineMarkdown(lines[i].replace(/^\s*[-*]\s+/, ""))}</li>`,
        );
        i += 1;
      }
      out.push(`<ul>${items.join("")}</ul>`);
      continue;
    }
    if (/^\s*\d+\.\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(
          `<li>${inlineMarkdown(lines[i].replace(/^\s*\d+\.\s+/, ""))}</li>`,
        );
        i += 1;
      }
      out.push(`<ol>${items.join("")}</ol>`);
      continue;
    }
    if (line.trim() === "") {
      i += 1;
      continue;
    }
    out.push(`<p>${inlineMarkdown(line)}</p>`);
    i += 1;
  }
  return out.join("\n");
}

// Markdown ⇄ block model, so the editor can render a clean Notion-like surface
// (headings / tables / lists) while still persisting Markdown to the knowledge base.
function parseMarkdownToBlocks(markdown) {
  const lines = String(markdown || "").split(/\r?\n/);
  const blocks = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim() === "") {
      i += 1;
      continue;
    }
    const isTableRow = /^\s*\|.*\|\s*$/.test(line);
    const nextIsSep =
      i + 1 < lines.length && /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1]);
    if (isTableRow && nextIsSep) {
      const headers = splitMarkdownRow(line);
      i += 2;
      const rows = [];
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) {
        rows.push(splitMarkdownRow(lines[i]));
        i += 1;
      }
      blocks.push({ type: "table", headers, rows });
      continue;
    }
    const heading = line.match(/^(#{1,6})\s+(.*)$/);
    if (heading) {
      blocks.push({ type: "heading", level: heading[1].length, text: heading[2] });
      i += 1;
      continue;
    }
    if (/^\s*>\s?/.test(line)) {
      const buf = [];
      while (i < lines.length && /^\s*>\s?/.test(lines[i])) {
        buf.push(lines[i].replace(/^\s*>\s?/, ""));
        i += 1;
      }
      blocks.push({ type: "quote", text: buf.join("\n") });
      continue;
    }
    if (/^\s*[-*]\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*]\s+/, "").trim());
        i += 1;
      }
      blocks.push({ type: "list", ordered: false, items });
      continue;
    }
    if (/^\s*\d+\.\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, "").trim());
        i += 1;
      }
      blocks.push({ type: "list", ordered: true, items });
      continue;
    }
    const image = line.trim().match(/^!\[(.*?)\]\((.*)\)$/);
    if (image) {
      blocks.push({ type: "image", alt: image[1], src: image[2] });
      i += 1;
      continue;
    }
    blocks.push({ type: "paragraph", text: line.trim() });
    i += 1;
  }
  return blocks;
}

function serializeBlocksToMarkdown(blocks) {
  const out = [];
  for (const b of blocks || []) {
    if (b.type === "heading") {
      out.push(`${"#".repeat(b.level || 2)} ${b.text || ""}`.trimEnd());
    } else if (b.type === "table") {
      const headers = b.headers && b.headers.length ? b.headers : [""];
      out.push(`| ${headers.join(" | ")} |`);
      out.push(`|${headers.map(() => "---").join("|")}|`);
      for (const r of b.rows || []) {
        const cells = headers.map((_, k) => (r[k] ?? "").toString());
        out.push(`| ${cells.join(" | ")} |`);
      }
    } else if (b.type === "list") {
      (b.items || []).forEach((it, idx) =>
        out.push(`${b.ordered ? `${idx + 1}.` : "-"} ${it}`),
      );
    } else if (b.type === "quote") {
      String(b.text || "")
        .split("\n")
        .forEach((l) => out.push(`> ${l}`));
    } else if (b.type === "image") {
      out.push(`![${b.alt || ""}](${b.src || ""})`);
    } else {
      out.push(b.text || "");
    }
    out.push("");
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd() + "\n";
}

const REVIEW_ADD_BTN_STYLE = {
  alignSelf: "flex-start",
  border: "1px dashed var(--line)",
  background: "transparent",
  color: "var(--ink-400)",
  borderRadius: 6,
  padding: "5px 10px",
  fontSize: 12,
  cursor: "pointer",
};
const REVIEW_CELL_STYLE = {
  width: "100%",
  border: "none",
  outline: "none",
  background: "transparent",
  fontSize: 13,
  color: "var(--ink-900)",
  padding: "6px 8px",
  fontFamily: "inherit",
  boxSizing: "border-box",
};

const REVIEW_TOOL_BTN_STYLE = {
  border: "1px solid var(--line)",
  background: "#fff",
  color: "var(--ink-700)",
  borderRadius: 6,
  padding: "4px 9px",
  fontSize: 12,
  cursor: "pointer",
  lineHeight: 1.4,
};
const REVIEW_HANDLE_STYLE = {
  border: "none",
  background: "transparent",
  color: "var(--ink-300, #c7ccd6)",
  cursor: "pointer",
  fontSize: 13,
  lineHeight: "22px",
  padding: "2px 2px",
  flexShrink: 0,
  userSelect: "none",
};

function makeEmptyBlock(kind) {
  switch (kind) {
    case "h1":
      return { type: "heading", level: 1, text: "" };
    case "h2":
      return { type: "heading", level: 2, text: "" };
    case "h3":
      return { type: "heading", level: 3, text: "" };
    case "bullet":
      return { type: "list", ordered: false, items: [""] };
    case "ordered":
      return { type: "list", ordered: true, items: [""] };
    case "quote":
      return { type: "quote", text: "" };
    case "table":
      return {
        type: "table",
        headers: ["列 1", "列 2", "列 3"],
        rows: [
          ["", "", ""],
          ["", "", ""],
        ],
      };
    case "image":
      return { type: "image", alt: "", src: "" };
    default:
      return { type: "paragraph", text: "" };
  }
}

function blockToPlainText(b) {
  if (!b) return "";
  if (b.type === "list") return (b.items || []).join("，");
  if (b.type === "table") return (b.headers || []).join(" / ");
  if (b.type === "image") return b.alt || "";
  return b.text || "";
}

// Notion-like block editor: rendered blocks edited in place, quick-insert toolbar,
// markdown shortcuts (# / - / 1. / >), right-click context menu, table + image support.
function BlockEditor({ blocks, onChange }) {
  const [menu, setMenu] = React.useState(null);
  const [activeIndex, setActiveIndex] = React.useState(
    Math.max(0, blocks.length - 1),
  );
  const fileInputRef = React.useRef(null);
  const pendingInsertRef = React.useRef(null);
  const rootRef = React.useRef(null);
  const pendingFocusRef = React.useRef(null);

  // Restore focus to a block after an insert/convert that swaps element type.
  React.useEffect(() => {
    const idx = pendingFocusRef.current;
    if (idx == null || !rootRef.current) return;
    pendingFocusRef.current = null;
    const el = rootRef.current.querySelector(`[data-focus-bi="${idx}"]`);
    if (el) {
      el.focus();
      const len = el.value?.length ?? 0;
      el.setSelectionRange?.(len, len);
    }
  });

  const setBlock = (bi, next) =>
    onChange(blocks.map((b, i) => (i === bi ? next : b)));
  const insertAt = (index, block) => {
    const next = [...blocks];
    next.splice(index, 0, block);
    onChange(next);
  };
  const removeAt = (i) => onChange(blocks.filter((_, j) => j !== i));
  const moveBlock = (i, dir) => {
    const j = i + dir;
    if (j < 0 || j >= blocks.length) return;
    const next = [...blocks];
    [next[i], next[j]] = [next[j], next[i]];
    onChange(next);
  };
  const duplicateAt = (i) =>
    insertAt(i + 1, JSON.parse(JSON.stringify(blocks[i])));
  const turnInto = (i, kind) => {
    const text = blockToPlainText(blocks[i]);
    const nb = makeEmptyBlock(kind);
    if (nb.type === "heading" || nb.type === "quote" || nb.type === "paragraph") {
      nb.text = text;
    } else if (nb.type === "list") {
      nb.items = text
        ? text.split(/[，,]/).map((x) => x.trim()).filter(Boolean)
        : [""];
      if (!nb.items.length) nb.items = [""];
    }
    onChange(blocks.map((b, j) => (j === i ? nb : b)));
    pendingFocusRef.current = i;
  };

  const onPickImage = (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    if (file.size > 3 * 1024 * 1024) {
      globalThis.alert?.("图片过大（>3MB），请压缩后再插入。");
      return;
    }
    const reader = new globalThis.FileReader();
    reader.onload = () => {
      const img = { type: "image", alt: file.name || "图片", src: reader.result };
      const pend = pendingInsertRef.current;
      pendingInsertRef.current = null;
      if (pend && pend.replace != null) {
        onChange(blocks.map((b, j) => (j === pend.replace ? img : b)));
      } else {
        insertAt(pend?.at ?? blocks.length, img);
      }
    };
    reader.readAsDataURL(file);
  };

  const insertColumn = (bi, at) => {
    const b = blocks[bi];
    const headers = [...b.headers];
    headers.splice(at, 0, `列 ${headers.length + 1}`);
    const rows = b.rows.map((r) => {
      const nr = [...r];
      nr.splice(at, 0, "");
      return nr;
    });
    setBlock(bi, { ...b, headers, rows });
  };
  const deleteColumn = (bi, ci) => {
    const b = blocks[bi];
    if (b.headers.length <= 1) return;
    setBlock(bi, {
      ...b,
      headers: b.headers.filter((_, k) => k !== ci),
      rows: b.rows.map((r) => r.filter((_, k) => k !== ci)),
    });
  };
  const insertRow = (bi, at) => {
    const b = blocks[bi];
    const cols = b.headers.length || 1;
    const rows = [...b.rows];
    rows.splice(at, 0, Array.from({ length: cols }).map(() => ""));
    setBlock(bi, { ...b, rows });
  };
  const deleteRow = (bi, ri) => {
    const b = blocks[bi];
    const cols = b.headers.length || 1;
    if (b.rows.length <= 1) {
      setBlock(bi, { ...b, rows: [Array.from({ length: cols }).map(() => "")] });
      return;
    }
    setBlock(bi, { ...b, rows: b.rows.filter((_, j) => j !== ri) });
  };

  const closeMenu = () => setMenu(null);
  const openActionsMenu = (e, bi) => {
    e.preventDefault();
    e.stopPropagation();
    setMenu({ kind: "actions", x: e.clientX, y: e.clientY, blockIndex: bi });
  };
  const openInsertMenu = (e, bi, mode) => {
    e.preventDefault();
    e.stopPropagation();
    setMenu({ kind: "insert", mode, x: e.clientX, y: e.clientY, blockIndex: bi });
  };
  const openColumnMenu = (e, bi, ci) => {
    e.preventDefault();
    e.stopPropagation();
    setMenu({ kind: "column", x: e.clientX, y: e.clientY, blockIndex: bi, colIndex: ci });
  };
  const openCellMenu = (e, bi, ri, ci) => {
    e.preventDefault();
    e.stopPropagation();
    setMenu({
      kind: "cell",
      x: e.clientX,
      y: e.clientY,
      blockIndex: bi,
      rowIndex: ri,
      colIndex: ci,
    });
  };

  const applyInsert = (kind) => {
    const bi = menu?.blockIndex ?? blocks.length - 1;
    const mode = menu?.mode || "after";
    if (kind === "image") {
      pendingInsertRef.current =
        mode === "convert" ? { replace: bi } : { at: bi + 1 };
      fileInputRef.current?.click();
      return;
    }
    if (mode === "convert") {
      turnInto(bi, kind);
    } else {
      const at = bi + 1;
      insertAt(at, makeEmptyBlock(kind));
      setActiveIndex(at);
      pendingFocusRef.current = at;
    }
  };

  const BLOCK_TYPES = [
    { kind: "paragraph", label: "正文", hint: "Aa" },
    { kind: "h1", label: "标题 1", hint: "H1" },
    { kind: "h2", label: "标题 2", hint: "H2" },
    { kind: "h3", label: "标题 3", hint: "H3" },
    { kind: "bullet", label: "无序列表", hint: "•" },
    { kind: "ordered", label: "有序列表", hint: "1." },
    { kind: "quote", label: "引用", hint: "❝" },
    { kind: "table", label: "表格", hint: "⊞" },
    { kind: "image", label: "图片", hint: "🖼" },
  ];

  const MenuLabel = ({ children }) => (
    <div style={{ fontSize: 11, color: "var(--ink-400)", padding: "6px 8px 2px" }}>
      {children}
    </div>
  );
  const MenuItem = ({ onClick, children, danger, hint }) => (
    <button
      type="button"
      onMouseDown={(e) => {
        e.preventDefault();
        onClick();
        setMenu(null);
      }}
      onMouseEnter={(e) => (e.currentTarget.style.background = "var(--bg-soft)")}
      onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
      style={{
        display: "flex",
        alignItems: "center",
        gap: 8,
        width: "100%",
        textAlign: "left",
        border: "none",
        background: "transparent",
        padding: "7px 8px",
        borderRadius: 6,
        cursor: "pointer",
        color: danger ? "var(--danger-600)" : "var(--ink-700)",
        fontSize: 13,
      }}
    >
      {hint != null && (
        <span
          style={{
            width: 22,
            textAlign: "center",
            color: "var(--ink-400)",
            fontSize: 12,
            flexShrink: 0,
          }}
        >
          {hint}
        </span>
      )}
      <span>{children}</span>
    </button>
  );
  const menuSep = { height: 1, background: "var(--line)", margin: "4px 0" };
  const gutterBtn = {
    border: "none",
    background: "transparent",
    color: "var(--ink-300, #c2c8d2)",
    cursor: "pointer",
    fontSize: 13,
    lineHeight: "20px",
    width: 18,
    height: 22,
    borderRadius: 4,
    padding: 0,
  };
  const tAddBtn = {
    border: "1px solid var(--line)",
    borderRadius: 4,
    background: "var(--bg-soft)",
    color: "var(--ink-400)",
    cursor: "pointer",
    fontSize: 12,
    lineHeight: 1,
    padding: 0,
  };

  const renderInner = (b, bi) => {
    if (b.type === "heading") {
      const sizes = { 1: 22, 2: 19, 3: 15.5, 4: 13.5 };
      return (
        <input
          data-focus-bi={bi}
          value={b.text}
          onChange={(e) => setBlock(bi, { ...b, text: e.target.value })}
          placeholder={`标题 ${b.level || 2}`}
          style={{
            ...REVIEW_CELL_STYLE,
            fontSize: sizes[b.level] || 14,
            fontWeight: (b.level || 2) <= 3 ? 700 : 600,
            padding: "2px 0",
            marginTop: (b.level || 2) <= 2 ? 6 : 2,
          }}
        />
      );
    }
    if (b.type === "quote") {
      return (
        <div
          style={{
            borderLeft: "3px solid var(--blue-600)",
            background: "var(--bg-soft)",
            borderRadius: 6,
            padding: "4px 10px",
          }}
        >
          <textarea
            data-focus-bi={bi}
            value={b.text}
            onChange={(e) => setBlock(bi, { ...b, text: e.target.value })}
            rows={Math.max(1, String(b.text || "").split("\n").length)}
            style={{
              ...REVIEW_CELL_STYLE,
              resize: "vertical",
              lineHeight: 1.6,
              color: "var(--ink-700)",
              padding: "4px 2px",
            }}
          />
        </div>
      );
    }
    if (b.type === "image") {
      return b.src ? (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          <img
            src={b.src}
            alt={b.alt || ""}
            style={{
              maxWidth: "100%",
              borderRadius: 8,
              border: "1px solid var(--line)",
            }}
          />
          <input
            value={b.alt || ""}
            placeholder="图片说明（alt）"
            onChange={(e) => setBlock(bi, { ...b, alt: e.target.value })}
            style={{ ...REVIEW_CELL_STYLE, fontSize: 12, color: "var(--ink-400)" }}
          />
        </div>
      ) : (
        <div
          style={{
            border: "1px dashed var(--line)",
            borderRadius: 8,
            padding: 16,
            color: "var(--ink-400)",
            fontSize: 12,
          }}
        >
          图片未加载
        </div>
      );
    }
    if (b.type === "list") {
      return (
        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
          {b.items.map((it, ii) => (
            <div key={ii} style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span
                style={{
                  color: "var(--ink-400)",
                  fontSize: 13,
                  minWidth: b.ordered ? 18 : 10,
                  textAlign: "right",
                  flexShrink: 0,
                }}
              >
                {b.ordered ? `${ii + 1}.` : "•"}
              </span>
              <input
                data-focus-bi={ii === 0 ? bi : undefined}
                value={it}
                onChange={(e) =>
                  setBlock(bi, {
                    ...b,
                    items: b.items.map((x, j) => (j === ii ? e.target.value : x)),
                  })
                }
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    const items = [...b.items];
                    items.splice(ii + 1, 0, "");
                    setBlock(bi, { ...b, items });
                  } else if (
                    e.key === "Backspace" &&
                    it === "" &&
                    b.items.length > 1
                  ) {
                    e.preventDefault();
                    setBlock(bi, {
                      ...b,
                      items: b.items.filter((_, j) => j !== ii),
                    });
                  }
                }}
                placeholder="列表项"
                style={REVIEW_CELL_STYLE}
              />
            </div>
          ))}
        </div>
      );
    }
    if (b.type === "table") {
      const cols = b.headers.length || 1;
      return (
        <div
          className="lr-table-wrap"
          style={{ position: "relative", marginRight: 16, marginBottom: 16 }}
        >
          <table
            style={{
              borderCollapse: "collapse",
              width: "100%",
              tableLayout: "fixed",
            }}
          >
            <thead>
              <tr>
                {b.headers.map((h, ci) => (
                  <th
                    key={ci}
                    title="右键：增 / 删列"
                    onContextMenu={(e) => openColumnMenu(e, bi, ci)}
                    style={{
                      border: "1px solid var(--line)",
                      background: "var(--bg-soft)",
                      padding: 0,
                    }}
                  >
                    <input
                      data-focus-bi={ci === 0 ? bi : undefined}
                      value={h}
                      onChange={(e) =>
                        setBlock(bi, {
                          ...b,
                          headers: b.headers.map((x, k) =>
                            k === ci ? e.target.value : x,
                          ),
                        })
                      }
                      style={{ ...REVIEW_CELL_STYLE, fontWeight: 600 }}
                    />
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {b.rows.map((r, ri) => (
                <tr key={ri}>
                  {Array.from({ length: cols }).map((_, ci) => (
                    <td
                      key={ci}
                      title="右键：增 / 删行 · 列"
                      onContextMenu={(e) => openCellMenu(e, bi, ri, ci)}
                      style={{
                        border: "1px solid var(--line)",
                        padding: 0,
                        verticalAlign: "top",
                      }}
                    >
                      <input
                        value={r[ci] ?? ""}
                        onChange={(e) => {
                          const rows = b.rows.map((row, j) =>
                            j !== ri
                              ? row
                              : Array.from({ length: cols }).map((__, k) =>
                                  k === ci ? e.target.value : row[k] ?? "",
                                ),
                          );
                          setBlock(bi, { ...b, rows });
                        }}
                        style={REVIEW_CELL_STYLE}
                      />
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
          <button
            type="button"
            className="lr-tadd"
            title="添加一列"
            onClick={() => insertColumn(bi, cols)}
            style={{
              ...tAddBtn,
              position: "absolute",
              top: 0,
              bottom: 0,
              right: -14,
              width: 12,
            }}
          >
            +
          </button>
          <button
            type="button"
            className="lr-tadd"
            title="添加一行"
            onClick={() => insertRow(bi, b.rows.length)}
            style={{
              ...tAddBtn,
              position: "absolute",
              left: 0,
              right: 0,
              bottom: -14,
              height: 12,
            }}
          >
            +
          </button>
        </div>
      );
    }
    // paragraph — slash menu + markdown shortcuts
    return (
      <textarea
        data-focus-bi={bi}
        value={b.text}
        onChange={(e) => {
          const v = e.target.value;
          if (v === "/") {
            const r = e.target.getBoundingClientRect();
            setBlock(bi, { ...b, text: "" });
            setMenu({
              kind: "insert",
              mode: "convert",
              blockIndex: bi,
              x: r.left,
              y: r.bottom + 4,
            });
            return;
          }
          const mH = v.match(/^(#{1,3})\s(.*)$/);
          if (mH) {
            pendingFocusRef.current = bi;
            setBlock(bi, { type: "heading", level: mH[1].length, text: mH[2] });
            return;
          }
          if (/^[-*]\s/.test(v)) {
            pendingFocusRef.current = bi;
            setBlock(bi, {
              type: "list",
              ordered: false,
              items: [v.replace(/^[-*]\s/, "")],
            });
            return;
          }
          if (/^\d+\.\s/.test(v)) {
            pendingFocusRef.current = bi;
            setBlock(bi, {
              type: "list",
              ordered: true,
              items: [v.replace(/^\d+\.\s/, "")],
            });
            return;
          }
          if (/^>\s/.test(v)) {
            pendingFocusRef.current = bi;
            setBlock(bi, { type: "quote", text: v.replace(/^>\s/, "") });
            return;
          }
          setBlock(bi, { ...b, text: v });
        }}
        rows={Math.max(1, String(b.text || "").split("\n").length)}
        placeholder="输入正文，按 / 选择块类型"
        style={{
          ...REVIEW_CELL_STYLE,
          resize: "vertical",
          lineHeight: 1.6,
          color: "var(--ink-700)",
          padding: "4px 2px",
        }}
      />
    );
  };

  return (
    <div ref={rootRef} style={{ display: "flex", flexDirection: "column" }}>
      <style>{`
        .lr-block .lr-gutter { opacity: 0; transition: opacity .12s ease; }
        .lr-block:hover .lr-gutter { opacity: 1; }
        .lr-table-wrap .lr-tadd { opacity: 0; transition: opacity .12s ease; }
        .lr-table-wrap:hover .lr-tadd { opacity: 1; }
      `}</style>

      <div style={{ fontSize: 11, color: "var(--ink-400)", marginBottom: 10 }}>
        输入 <b>/</b> 选择块类型 · 悬停左侧 <b>+</b> 添加块 · 右键块 / 表格单元格更多操作
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        {blocks.map((b, bi) => (
          <div
            key={bi}
            className="lr-block"
            onFocusCapture={() => setActiveIndex(bi)}
            onContextMenu={(e) => openActionsMenu(e, bi)}
            style={{ display: "flex", gap: 2, alignItems: "flex-start" }}
          >
            <div
              className="lr-gutter"
              style={{ display: "flex", flexShrink: 0, paddingTop: 3 }}
            >
              <button
                type="button"
                title="在下方添加块"
                onClick={(e) => openInsertMenu(e, bi, "after")}
                style={gutterBtn}
              >
                +
              </button>
              <button
                type="button"
                title="块操作（也可右键）"
                onClick={(e) => openActionsMenu(e, bi)}
                style={gutterBtn}
              >
                ⋮⋮
              </button>
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>{renderInner(b, bi)}</div>
          </div>
        ))}
      </div>

      <button
        type="button"
        onMouseDown={(e) => {
          e.preventDefault();
          setMenu({
            kind: "insert",
            mode: "after",
            blockIndex: blocks.length - 1,
            x: e.clientX,
            y: e.clientY,
          });
        }}
        style={{ ...REVIEW_ADD_BTN_STYLE, marginTop: 10 }}
      >
        + 添加内容
      </button>

      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        onChange={onPickImage}
        style={{ display: "none" }}
      />

      {menu && (
        <>
          <div
            onMouseDown={closeMenu}
            onContextMenu={(e) => {
              e.preventDefault();
              closeMenu();
            }}
            style={{ position: "fixed", inset: 0, zIndex: 90 }}
          />
          <div
            style={{
              position: "fixed",
              left: Math.min(
                menu.x,
                (typeof window !== "undefined" ? window.innerWidth : 1200) - 230,
              ),
              top: Math.min(
                menu.y,
                (typeof window !== "undefined" ? window.innerHeight : 800) - 380,
              ),
              zIndex: 91,
              background: "#fff",
              border: "1px solid var(--line)",
              borderRadius: 8,
              boxShadow: "0 12px 32px rgba(15,23,42,0.18)",
              padding: 6,
              minWidth: 200,
              maxHeight: 360,
              overflowY: "auto",
            }}
          >
            {menu.kind === "insert" && (
              <>
                <MenuLabel>{menu.mode === "convert" ? "转为" : "插入块"}</MenuLabel>
                {BLOCK_TYPES.map((t) => (
                  <MenuItem key={t.kind} hint={t.hint} onClick={() => applyInsert(t.kind)}>
                    {t.label}
                  </MenuItem>
                ))}
              </>
            )}
            {menu.kind === "actions" && (
              <>
                <MenuLabel>转为</MenuLabel>
                <MenuItem hint="Aa" onClick={() => turnInto(menu.blockIndex, "paragraph")}>
                  正文
                </MenuItem>
                <MenuItem hint="H1" onClick={() => turnInto(menu.blockIndex, "h1")}>
                  标题 1
                </MenuItem>
                <MenuItem hint="H2" onClick={() => turnInto(menu.blockIndex, "h2")}>
                  标题 2
                </MenuItem>
                <MenuItem hint="H3" onClick={() => turnInto(menu.blockIndex, "h3")}>
                  标题 3
                </MenuItem>
                <MenuItem hint="•" onClick={() => turnInto(menu.blockIndex, "bullet")}>
                  无序列表
                </MenuItem>
                <MenuItem hint="1." onClick={() => turnInto(menu.blockIndex, "ordered")}>
                  有序列表
                </MenuItem>
                <MenuItem hint="❝" onClick={() => turnInto(menu.blockIndex, "quote")}>
                  引用
                </MenuItem>
                <div style={menuSep} />
                <MenuItem onClick={() => moveBlock(menu.blockIndex, -1)}>上移</MenuItem>
                <MenuItem onClick={() => moveBlock(menu.blockIndex, 1)}>下移</MenuItem>
                <MenuItem onClick={() => duplicateAt(menu.blockIndex)}>复制</MenuItem>
                <div style={menuSep} />
                <MenuItem danger onClick={() => removeAt(menu.blockIndex)}>
                  删除
                </MenuItem>
              </>
            )}
            {menu.kind === "column" && (
              <>
                <MenuLabel>列操作</MenuLabel>
                <MenuItem onClick={() => insertColumn(menu.blockIndex, menu.colIndex + 1)}>
                  在右侧插入列
                </MenuItem>
                <MenuItem onClick={() => insertColumn(menu.blockIndex, menu.colIndex)}>
                  在左侧插入列
                </MenuItem>
                <MenuItem danger onClick={() => deleteColumn(menu.blockIndex, menu.colIndex)}>
                  删除本列
                </MenuItem>
              </>
            )}
            {menu.kind === "cell" && (
              <>
                <MenuLabel>行操作</MenuLabel>
                <MenuItem onClick={() => insertRow(menu.blockIndex, menu.rowIndex)}>
                  在上方插入行
                </MenuItem>
                <MenuItem onClick={() => insertRow(menu.blockIndex, menu.rowIndex + 1)}>
                  在下方插入行
                </MenuItem>
                <MenuItem danger onClick={() => deleteRow(menu.blockIndex, menu.rowIndex)}>
                  删除本行
                </MenuItem>
                <div style={menuSep} />
                <MenuLabel>列操作</MenuLabel>
                <MenuItem onClick={() => insertColumn(menu.blockIndex, menu.colIndex + 1)}>
                  在右侧插入列
                </MenuItem>
                <MenuItem onClick={() => insertColumn(menu.blockIndex, menu.colIndex)}>
                  在左侧插入列
                </MenuItem>
                <MenuItem danger onClick={() => deleteColumn(menu.blockIndex, menu.colIndex)}>
                  删除本列
                </MenuItem>
              </>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// ——— 知识库（Notion 式层级文档库）———————————————————————————
// 直属库 → 复盘 → 项目 → 主播 → 复盘文件（日期+主播+产品复盘）；任务复盘自动归档，
// 同时支持自定义文件夹/页面、重命名、移动、删除，层级任意嵌套。

const KB_LS_KEY = "jingying.knowledgeBase.v1";
const KB_ROOT_ID = "kb-root";
const KB_REVIEW_FOLDER_ID = "kb-folder-review";
const KB_TRANSCRIPT_FOLDER_ID = "kb-folder-transcript";
// 默认内置文档：产品使用教程。system=true → 不可删除，加载时缺了自动补，人人可见。
const KB_TUTORIAL_DOC_ID = "kb-doc-usage-tutorial";

function kbTutorialNode() {
  return {
    id: KB_TUTORIAL_DOC_ID,
    type: "doc",
    name: "📖 使用教程",
    parentId: KB_ROOT_ID,
    contentMd: USAGE_TUTORIAL_MD,
    createdAt: 0,
    updatedAt: 0,
    order: -1, // 置顶
    system: true,
  };
}

function kbReviewFolderNode() {
  return {
    id: KB_REVIEW_FOLDER_ID,
    type: "folder",
    name: "复盘",
    parentId: KB_ROOT_ID,
    createdAt: 0,
    order: 0,
    system: true,
  };
}

function kbTranscriptFolderNode() {
  return {
    id: KB_TRANSCRIPT_FOLDER_ID,
    type: "folder",
    name: "逐字稿",
    parentId: KB_ROOT_ID,
    createdAt: 0,
    order: 1,
    system: true,
  };
}

// 保证系统节点（复盘文件夹、使用教程文档）始终存在；老用户的存量库加载时自动补齐。
// 教程内容随版本更新——若已存在则刷新其 contentMd，确保看到最新版。
function kbEnsureSystemNodes(store) {
  if (!store || !store.nodes || !store.nodes[KB_ROOT_ID]) return store;
  const nodes = { ...store.nodes };
  if (!nodes[KB_REVIEW_FOLDER_ID]) {
    nodes[KB_REVIEW_FOLDER_ID] = kbReviewFolderNode();
  }
  if (!nodes[KB_TRANSCRIPT_FOLDER_ID]) {
    nodes[KB_TRANSCRIPT_FOLDER_ID] = kbTranscriptFolderNode();
  }
  const tutorial = kbTutorialNode();
  nodes[KB_TUTORIAL_DOC_ID] = nodes[KB_TUTORIAL_DOC_ID]
    ? { ...nodes[KB_TUTORIAL_DOC_ID], contentMd: tutorial.contentMd, system: true }
    : tutorial;
  return { ...store, nodes };
}

function kbGenId() {
  return `kb_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
}

function kbDefaultStore() {
  return {
    version: 1,
    nodes: {
      [KB_ROOT_ID]: {
        id: KB_ROOT_ID,
        type: "folder",
        name: "直属库",
        parentId: null,
        createdAt: 0,
        order: 0,
        system: true,
      },
      [KB_REVIEW_FOLDER_ID]: kbReviewFolderNode(),
      [KB_TRANSCRIPT_FOLDER_ID]: kbTranscriptFolderNode(),
      [KB_TUTORIAL_DOC_ID]: kbTutorialNode(),
    },
  };
}

function loadKnowledgeStore() {
  if (typeof window === "undefined" || !window.localStorage) {
    return kbDefaultStore();
  }
  try {
    const raw = window.localStorage.getItem(KB_LS_KEY);
    if (!raw) return kbDefaultStore();
    const parsed = JSON.parse(raw);
    if (!parsed || !parsed.nodes || !parsed.nodes[KB_ROOT_ID]) {
      return kbDefaultStore();
    }
    return kbEnsureSystemNodes(parsed);
  } catch {
    return kbDefaultStore();
  }
}

function saveKnowledgeStore(store) {
  if (typeof window === "undefined" || !window.localStorage) return;
  try {
    window.localStorage.setItem(KB_LS_KEY, JSON.stringify(store));
  } catch {
    /* ignore quota errors */
  }
}

// 远端（腾讯云 COS）读写：线上为共享真源，离线/未登录回退本地缓存。
async function loadKnowledgeStoreRemote() {
  try {
    const res = await globalThis.fetch("/api/knowledge-base");
    if (!res.ok) return null;
    const payload = await res.json();
    return payload?.store ?? null;
  } catch {
    return null;
  }
}

async function saveKnowledgeStoreRemote(store) {
  try {
    const res = await globalThis.fetch("/api/knowledge-base", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ store }),
    });
    return res.ok;
  } catch {
    return false;
  }
}

function kbChildren(store, parentId) {
  return Object.values(store.nodes)
    .filter((n) => n.parentId === parentId)
    .sort(
      (a, b) =>
        (a.order ?? 0) - (b.order ?? 0) ||
        (a.createdAt ?? 0) - (b.createdAt ?? 0) ||
        String(a.name).localeCompare(String(b.name)),
    );
}

function kbNextOrder(store, parentId) {
  const kids = kbChildren(store, parentId);
  return kids.length ? (kids[kids.length - 1].order ?? 0) + 1 : 0;
}

function kbAddNode(store, { type, name, parentId, contentMd, meta }) {
  const id = kbGenId();
  const node = {
    id,
    type,
    name,
    parentId,
    createdAt: Date.now(),
    order: kbNextOrder(store, parentId),
  };
  if (type === "doc") node.contentMd = contentMd ?? "";
  if (meta) node.meta = meta;
  return { store: { ...store, nodes: { ...store.nodes, [id]: node } }, id };
}

function kbDescendants(store, id) {
  const out = [];
  const stack = [id];
  while (stack.length) {
    const cur = stack.pop();
    for (const n of Object.values(store.nodes)) {
      if (n.parentId === cur) {
        out.push(n.id);
        stack.push(n.id);
      }
    }
  }
  return out;
}

function kbDeleteNode(store, id) {
  if (store.nodes[id]?.system) return store;
  const ids = new Set([id, ...kbDescendants(store, id)]);
  const nodes = {};
  for (const [k, v] of Object.entries(store.nodes)) {
    if (!ids.has(k)) nodes[k] = v;
  }
  return { ...store, nodes };
}

function kbRenameNode(store, id, name) {
  const n = store.nodes[id];
  if (!n) return store;
  return { ...store, nodes: { ...store.nodes, [id]: { ...n, name } } };
}

function kbSetContent(store, id, contentMd) {
  const n = store.nodes[id];
  if (!n) return store;
  return {
    ...store,
    nodes: {
      ...store.nodes,
      [id]: { ...n, contentMd, updatedAt: Date.now() },
    },
  };
}

function kbMoveNode(store, id, newParentId) {
  const n = store.nodes[id];
  if (!n || n.system) return store;
  if (id === newParentId) return store;
  if (kbDescendants(store, id).includes(newParentId)) return store;
  return {
    ...store,
    nodes: {
      ...store.nodes,
      [id]: { ...n, parentId: newParentId, order: kbNextOrder(store, newParentId) },
    },
  };
}

function kbFindChildByName(store, parentId, name, type) {
  return kbChildren(store, parentId).find(
    (n) => n.name === name && (!type || n.type === type),
  );
}

function kbPath(store, id) {
  const path = [];
  let cur = store.nodes[id];
  while (cur) {
    path.unshift(cur);
    cur = cur.parentId ? store.nodes[cur.parentId] : null;
  }
  return path;
}

// 任务复盘自动归档：直属库 / 复盘 / {项目} / {主播} / {日期 主播 产品复盘}
// 先读 COS 真源（拿不到则用本地缓存），归档后写回 COS + 本地缓存。
async function archiveReviewToKnowledgeBase({
  date,
  streamer,
  product,
  contentMd,
  projectId,
  streamerId,
}) {
  let store = kbEnsureSystemNodes(
    (await loadKnowledgeStoreRemote()) || loadKnowledgeStore(),
  );
  const projName = product || projectId || "未标注项目";
  const strName = streamer || streamerId || "未知主播";

  let proj = kbFindChildByName(store, KB_REVIEW_FOLDER_ID, projName, "folder");
  if (!proj) {
    const r = kbAddNode(store, {
      type: "folder",
      name: projName,
      parentId: KB_REVIEW_FOLDER_ID,
    });
    store = r.store;
    proj = store.nodes[r.id];
  }

  let str = kbFindChildByName(store, proj.id, strName, "folder");
  if (!str) {
    const r = kbAddNode(store, {
      type: "folder",
      name: strName,
      parentId: proj.id,
    });
    store = r.store;
    str = store.nodes[r.id];
  }

  const docName = `${date || ""} ${strName} ${product || ""}复盘`
    .replace(/\s+/g, " ")
    .trim();
  const meta = { date, streamer: strName, product, projectId, streamerId };
  const existing = kbFindChildByName(store, str.id, docName, "doc");
  if (existing) {
    store = {
      ...store,
      nodes: {
        ...store.nodes,
        [existing.id]: {
          ...existing,
          contentMd,
          meta,
          updatedAt: Date.now(),
        },
      },
    };
  } else {
    const r = kbAddNode(store, {
      type: "doc",
      name: docName,
      parentId: str.id,
      contentMd,
      meta,
    });
    store = r.store;
  }
  saveKnowledgeStore(store);
  await saveKnowledgeStoreRemote(store);
}

// 录屏逐字稿归档：客户端用转写数据拼 markdown，排版对齐服务端知识库导出的观感
// （## 风险摘要 / ## 高频词 / ## 正文；违规词【违规:词】、风险词【风险:词】内联标注）。
// 供 archiveTranscriptToKnowledgeBase 落进 COS 知识树（用户在「知识库」页可见）。
const TRANSCRIPT_KB_WORD_TOP_N = 5;

function transcriptKbSegmentsToMarkedText(segments) {
  const list =
    Array.isArray(segments) && segments.length > 0 ? segments : null;
  if (!list) return "";
  return list
    .map((segment) => {
      const text = segment?.text ?? "";
      if (segment?.tone === "violation") return `【违规:${text}】`;
      if (segment?.tone === "warning") return `【风险:${text}】`;
      return text;
    })
    .join("");
}

function buildTranscriptMarkdown({
  title,
  asrProvider,
  transcript,
  includeTimestamps,
}) {
  const summary = transcript?.summary ?? null;
  const violationCount = summary?.violationCount ?? 0;
  const warningCount = summary?.warningCount ?? 0;
  const keywordLabel = summary?.keywords?.length
    ? summary.keywords
        .map(
          (item) =>
            `${item.tone === "violation" ? "违规" : "风险"}「${item.keyword}」×${item.count ?? 0}`,
        )
        .join("、")
    : "无";

  const lines = [
    `# ${title}`,
    "",
    `ASR provider: ${asrProvider ?? "unknown"}`,
    "",
    "## 风险摘要",
    "",
    `- 违规命中 ${violationCount} 处 · 风险命中 ${warningCount} 处 · 命中词：${keywordLabel}`,
    "",
  ];

  const insights =
    transcript?.wordInsights && typeof transcript.wordInsights === "object"
      ? transcript.wordInsights
      : null;
  if (insights) {
    const effective = (
      Array.isArray(insights.effective) ? insights.effective : []
    )
      .slice(0, TRANSCRIPT_KB_WORD_TOP_N)
      .map(
        (item) =>
          `${item.categoryLabel || item.category || "有效"}「${item.word}」×${item.count ?? 0}`,
      )
      .join("、");
    const ineffective = (
      Array.isArray(insights.ineffective) ? insights.ineffective : []
    )
      .slice(0, TRANSCRIPT_KB_WORD_TOP_N)
      .map((item) => `「${item.word}」×${item.count ?? 0}`)
      .join("、");
    const share =
      typeof insights.metrics?.effectiveShare === "number" &&
      Number.isFinite(insights.metrics.effectiveShare)
        ? `${Math.round(insights.metrics.effectiveShare * 100)}%`
        : "—";
    const filler = insights.metrics?.fillerPerUtterance ?? "—";
    lines.push(
      "## 高频词",
      "",
      `- 有效词 Top${TRANSCRIPT_KB_WORD_TOP_N}：${effective || "无"}`,
      `- 无效水词 Top${TRANSCRIPT_KB_WORD_TOP_N}：${ineffective || "无"}`,
      `- 口播指标：水词密度 ${filler} 词/句 · 有效话术占比 ${share}`,
      "",
    );
  }

  lines.push("## 正文", "");
  for (const utterance of transcript?.utterances ?? []) {
    const prefix = includeTimestamps
      ? `[${formatTranscriptClock(utterance.startSeconds)}] `
      : "";
    const text =
      transcriptKbSegmentsToMarkedText(utterance.segments) ||
      (utterance.text ?? "");
    lines.push(`- ${prefix}${text}`);
  }

  return lines.join("\n").trim() + "\n";
}

// 逐字稿归档到「知识库 → 逐字稿 / {资产名} / {日期 资产名 逐字稿}」（腾讯云 COS）。
// 严格对齐 archiveReviewToKnowledgeBase：先读 COS 真源（拿不到则用本地缓存），
// 按名幂等找/建目录与文档，写回 COS + 本地缓存。返回 { docName, remoteOk }：
// remoteOk=false（COS 未配置/写失败）时调用方回退「已保存到知识库（本地）」提示。
async function archiveTranscriptToKnowledgeBase({
  assetName,
  asrProvider,
  transcript,
  includeTimestamps,
}) {
  let store = kbEnsureSystemNodes(
    (await loadKnowledgeStoreRemote()) || loadKnowledgeStore(),
  );
  const folderName = assetName || "未命名录屏";

  let assetFolder = kbFindChildByName(
    store,
    KB_TRANSCRIPT_FOLDER_ID,
    folderName,
    "folder",
  );
  if (!assetFolder) {
    const r = kbAddNode(store, {
      type: "folder",
      name: folderName,
      parentId: KB_TRANSCRIPT_FOLDER_ID,
    });
    store = r.store;
    assetFolder = store.nodes[r.id];
  }

  const today = new Date().toISOString().slice(0, 10);
  const docName = `${today} ${folderName} 逐字稿`.replace(/\s+/g, " ").trim();
  const contentMd = buildTranscriptMarkdown({
    title: docName,
    asrProvider,
    transcript,
    includeTimestamps,
  });
  const meta = {
    source: "recording_transcript",
    asrProvider: asrProvider ?? null,
    assetName: folderName,
    exportedAt: new Date().toISOString(),
  };

  const existing = kbFindChildByName(store, assetFolder.id, docName, "doc");
  if (existing) {
    store = {
      ...store,
      nodes: {
        ...store.nodes,
        [existing.id]: {
          ...existing,
          contentMd,
          meta,
          updatedAt: Date.now(),
        },
      },
    };
  } else {
    const r = kbAddNode(store, {
      type: "doc",
      name: docName,
      parentId: assetFolder.id,
      contentMd,
      meta,
    });
    store = r.store;
  }

  saveKnowledgeStore(store);
  const remoteOk = await saveKnowledgeStoreRemote(store);
  return { docName, remoteOk };
}

// ——— 知识库文档：分享 / 导出（MD / PDF / Word）———————————————
function kbSafeFileName(name) {
  return (
    (name || "复盘文档")
      .replace(/[\\/:*?"<>|]/g, "_")
      .trim()
      .slice(0, 120) || "复盘文档"
  );
}

function kbEscapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function kbDocHtmlPage(title, contentMd, { autoPrint } = {}) {
  const body = renderMarkdownDoc(contentMd || "");
  const safeTitle = kbEscapeHtml(title || "复盘文档");
  const printScript = autoPrint
    ? "<script>window.onload=function(){setTimeout(function(){window.focus();window.print();},150);};</script>"
    : "";
  return `<!doctype html><html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${safeTitle}</title><style>${MARKDOWN_DOC_CSS}</style>${printScript}</head><body><h1>${safeTitle}</h1>${body}</body></html>`;
}

function kbDownloadBlob(filename, mime, content) {
  if (typeof window === "undefined") return;
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function kbExportMarkdown(doc) {
  kbDownloadBlob(
    `${kbSafeFileName(doc.name)}.md`,
    "text/markdown;charset=utf-8",
    doc.contentMd || "",
  );
}

function kbExportWord(doc) {
  kbDownloadBlob(
    `${kbSafeFileName(doc.name)}.doc`,
    "application/msword",
    kbDocHtmlPage(doc.name, doc.contentMd),
  );
}

function kbExportPdf(doc) {
  if (typeof window === "undefined") return;
  const w = window.open("", "_blank");
  if (!w) {
    globalThis.alert?.(
      "请允许弹出窗口以导出 PDF（在打印对话框中选择「另存为 PDF」）。",
    );
    return;
  }
  w.document.write(kbDocHtmlPage(doc.name, doc.contentMd, { autoPrint: true }));
  w.document.close();
}

async function kbShareDoc(doc) {
  const res = await globalThis.fetch("/api/knowledge-base/share", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title: doc.name, contentMd: doc.contentMd || "" }),
  });
  if (!res.ok) {
    const payload = await res.json().catch(() => ({}));
    throw new Error(payload.error || "分享失败");
  }
  const payload = await res.json();
  return payload.url;
}

function KnowledgeDocEditor({ doc, onChange }) {
  const [blocks, setBlocks] = React.useState(() => {
    const parsed = parseMarkdownToBlocks(doc.contentMd || "");
    return parsed.length ? parsed : [{ type: "paragraph", text: "" }];
  });
  const handle = (next) => {
    setBlocks(next);
    onChange(serializeBlocksToMarkdown(next));
  };
  return <BlockEditor blocks={blocks} onChange={handle} />;
}

function ScreenKnowledge() {
  const [store, setStore] = React.useState(loadKnowledgeStore);
  const [selectedId, setSelectedId] = React.useState(KB_REVIEW_FOLDER_ID);
  const [expanded, setExpanded] = React.useState(
    () => new Set([KB_ROOT_ID, KB_REVIEW_FOLDER_ID]),
  );
  const [renamingId, setRenamingId] = React.useState(null);
  const [menu, setMenu] = React.useState(null);
  const [moveId, setMoveId] = React.useState(null);
  const [shareUrl, setShareUrl] = React.useState("");
  const [docMsg, setDocMsg] = React.useState("");
  const [shareBusy, setShareBusy] = React.useState(false);
  const [syncState, setSyncState] = React.useState("loading"); // loading|synced|local
  const hydratedRef = React.useRef(false);
  const remoteTimerRef = React.useRef(null);

  // 加载：优先腾讯云 COS 真源，拿不到则用本地缓存。
  React.useEffect(() => {
    let alive = true;
    (async () => {
      const remote = await loadKnowledgeStoreRemote();
      if (!alive) return;
      if (remote && remote.nodes && remote.nodes[KB_ROOT_ID]) {
        setStore(kbEnsureSystemNodes(remote));
        setSyncState("synced");
      } else {
        setSyncState(remote === null ? "local" : "synced");
      }
      hydratedRef.current = true;
    })();
    return () => {
      alive = false;
    };
  }, []);

  // 保存：本地缓存即时写，COS 防抖写（仅在完成首次加载后）。
  React.useEffect(() => {
    saveKnowledgeStore(store);
    if (!hydratedRef.current) return;
    if (remoteTimerRef.current) clearTimeout(remoteTimerRef.current);
    remoteTimerRef.current = setTimeout(() => {
      saveKnowledgeStoreRemote(store).then((ok) =>
        setSyncState(ok ? "synced" : "local"),
      );
    }, 600);
  }, [store]);

  const selected = store.nodes[selectedId] || store.nodes[KB_ROOT_ID];

  // 切换文档时清空上一篇的分享链接 / 提示。
  React.useEffect(() => {
    setShareUrl("");
    setDocMsg("");
  }, [selectedId]);

  const toggle = (id) =>
    setExpanded((e) => {
      const n = new Set(e);
      if (n.has(id)) n.delete(id);
      else n.add(id);
      return n;
    });

  const addChild = (parentId, type) => {
    const name = type === "folder" ? "新建文件夹" : "新建页面";
    let newId = null;
    setStore((s) => {
      const r = kbAddNode(s, { type, name, parentId });
      newId = r.id;
      return r.store;
    });
    setExpanded((e) => new Set(e).add(parentId));
    setTimeout(() => {
      if (newId) {
        setSelectedId(newId);
        setRenamingId(newId);
      }
    }, 0);
  };

  const selectNode = (node) => {
    setSelectedId(node.id);
    if (node.type === "folder") setExpanded((e) => new Set(e).add(node.id));
  };

  const folderOptions = Object.values(store.nodes).filter(
    (n) => n.type === "folder",
  );

  const renderRow = (node, depth) => {
    const isFolder = node.type === "folder";
    const open = expanded.has(node.id);
    const kids = isFolder ? kbChildren(store, node.id) : [];
    return (
      <div key={node.id}>
        <div
          className="kb-row"
          onClick={() => selectNode(node)}
          onContextMenu={(e) => {
            e.preventDefault();
            setMenu({ id: node.id, x: e.clientX, y: e.clientY });
          }}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 4,
            padding: "4px 6px",
            paddingLeft: 6 + depth * 14,
            borderRadius: 6,
            cursor: "pointer",
            fontSize: 13,
            color: "var(--ink-800, #1f2733)",
            background: selectedId === node.id ? "var(--blue-50)" : "transparent",
          }}
        >
          <span
            onClick={(e) => {
              e.stopPropagation();
              if (isFolder) toggle(node.id);
            }}
            style={{
              width: 14,
              flexShrink: 0,
              color: "var(--ink-400)",
              fontSize: 10,
              textAlign: "center",
              visibility: isFolder && kids.length ? "visible" : "hidden",
            }}
          >
            {open ? "▾" : "▸"}
          </span>
          <span style={{ flexShrink: 0 }}>{isFolder ? "📁" : "📄"}</span>
          {renamingId === node.id ? (
            <input
              autoFocus
              defaultValue={node.name}
              onClick={(e) => e.stopPropagation()}
              onBlur={(e) => {
                setStore((s) => kbRenameNode(s, node.id, e.target.value.trim() || node.name));
                setRenamingId(null);
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") e.currentTarget.blur();
                if (e.key === "Escape") setRenamingId(null);
              }}
              style={{
                flex: 1,
                minWidth: 0,
                border: "1px solid var(--blue-600)",
                borderRadius: 4,
                padding: "1px 4px",
                fontSize: 13,
                outline: "none",
              }}
            />
          ) : (
            <span
              style={{
                flex: 1,
                minWidth: 0,
                overflow: "hidden",
                textOverflow: "ellipsis",
                whiteSpace: "nowrap",
              }}
            >
              {node.name}
            </span>
          )}
          <span className="kb-actions" style={{ display: "flex", gap: 2, flexShrink: 0 }}>
            {isFolder && (
              <button
                type="button"
                title="新建页面"
                onClick={(e) => {
                  e.stopPropagation();
                  addChild(node.id, "doc");
                }}
                style={kbIconBtn}
              >
                +
              </button>
            )}
            <button
              type="button"
              title="更多"
              onClick={(e) => {
                e.stopPropagation();
                setMenu({ id: node.id, x: e.clientX, y: e.clientY });
              }}
              style={kbIconBtn}
            >
              ⋯
            </button>
          </span>
        </div>
        {isFolder && open && kids.map((k) => renderRow(k, depth + 1))}
      </div>
    );
  };

  const menuNode = menu ? store.nodes[menu.id] : null;

  return (
    <>
      <PageHeader
        title="知识库"
        subtitle="任务复盘自动归档（直属库 / 复盘 / 项目 / 主播），支持自定义层级，像 Notion 一样组织文档"
      />
      <style>{`
        .kb-row .kb-actions { opacity: 0; transition: opacity .12s ease; }
        .kb-row:hover .kb-actions { opacity: 1; }
        .kb-row:hover { background: var(--bg-soft); }
      `}</style>
      <div
        style={{
          display: "flex",
          height: "calc(100vh - 168px)",
          background: "#fff",
        }}
      >
        {/* Tree */}
        <div
          style={{
            width: 290,
            flexShrink: 0,
            borderRight: "1px solid var(--line)",
            overflowY: "auto",
            padding: 10,
            display: "flex",
            flexDirection: "column",
            gap: 4,
          }}
        >
          <div style={{ display: "flex", gap: 6, marginBottom: 4 }}>
            <Button size="sm" kind="default" onClick={() => addChild(KB_ROOT_ID, "doc")}>
              + 页面
            </Button>
            <Button
              size="sm"
              kind="default"
              onClick={() => addChild(KB_ROOT_ID, "folder")}
            >
              + 文件夹
            </Button>
          </div>
          <div
            style={{
              fontSize: 11,
              color: syncState === "synced" ? "var(--ok-600)" : "var(--ink-400)",
              marginBottom: 6,
              paddingLeft: 2,
            }}
          >
            {syncState === "loading"
              ? "正在从腾讯云读取…"
              : syncState === "synced"
                ? "● 已同步至腾讯云存储桶"
                : "○ 本地缓存（未连接云端存储）"}
          </div>
          {renderRow(store.nodes[KB_ROOT_ID], 0)}
        </div>

        {/* Content */}
        <div style={{ flex: 1, minWidth: 0, overflowY: "auto", padding: "18px 24px" }}>
          {selected ? (
            <>
              <div
                style={{
                  fontSize: 11,
                  color: "var(--ink-400)",
                  marginBottom: 8,
                  display: "flex",
                  gap: 4,
                  flexWrap: "wrap",
                }}
              >
                {kbPath(store, selected.id).map((p, i, arr) => (
                  <span key={p.id}>
                    {p.name}
                    {i < arr.length - 1 ? " / " : ""}
                  </span>
                ))}
              </div>
              {selected.type === "doc" && (
                <div
                  style={{
                    display: "flex",
                    flexWrap: "wrap",
                    gap: 8,
                    marginBottom: 12,
                    alignItems: "center",
                  }}
                >
                  <Button
                    size="sm"
                    kind="default"
                    icon={<Icon.Upload size={13} />}
                    disabled={shareBusy}
                    onClick={async () => {
                      setDocMsg("");
                      setShareUrl("");
                      setShareBusy(true);
                      try {
                        const url = await kbShareDoc(selected);
                        setShareUrl(url);
                        try {
                          await navigator.clipboard?.writeText(url);
                          setDocMsg("分享链接已生成并复制到剪贴板。");
                        } catch {
                          setDocMsg("分享链接已生成。");
                        }
                      } catch (e) {
                        setDocMsg(
                          e?.message === "Tencent COS is not configured"
                            ? "未连接云端存储，暂不可生成分享链接。"
                            : `分享失败：${e?.message || "请稍后重试"}`,
                        );
                      } finally {
                        setShareBusy(false);
                      }
                    }}
                  >
                    {shareBusy ? "生成中…" : "分享链接"}
                  </Button>
                  <Button
                    size="sm"
                    kind="default"
                    onClick={() => kbExportMarkdown(selected)}
                  >
                    导出 MD
                  </Button>
                  <Button
                    size="sm"
                    kind="default"
                    onClick={() => kbExportPdf(selected)}
                  >
                    导出 PDF
                  </Button>
                  <Button
                    size="sm"
                    kind="default"
                    onClick={() => kbExportWord(selected)}
                  >
                    导出 Word
                  </Button>
                </div>
              )}
              {selected.type === "doc" && (shareUrl || docMsg) ? (
                <div
                  style={{
                    marginBottom: 12,
                    padding: "10px 12px",
                    border: "1px solid var(--line)",
                    borderRadius: 8,
                    background: "var(--bg-soft)",
                    fontSize: 12,
                    color: "var(--ink-700)",
                  }}
                >
                  {docMsg ? <div style={{ marginBottom: shareUrl ? 6 : 0 }}>{docMsg}</div> : null}
                  {shareUrl ? (
                    <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                      <input
                        readOnly
                        value={shareUrl}
                        onFocus={(e) => e.target.select()}
                        style={{
                          flex: 1,
                          minWidth: 0,
                          border: "1px solid var(--line)",
                          borderRadius: 6,
                          padding: "5px 8px",
                          fontSize: 12,
                          color: "var(--ink-700)",
                          background: "#fff",
                        }}
                      />
                      <Button
                        size="sm"
                        kind="default"
                        onClick={() => {
                          navigator.clipboard?.writeText(shareUrl);
                          setDocMsg("已复制到剪贴板。");
                        }}
                      >
                        复制
                      </Button>
                      <a
                        href={shareUrl}
                        target="_blank"
                        rel="noreferrer"
                        style={{ fontSize: 12, color: "var(--blue-700)" }}
                      >
                        打开
                      </a>
                    </div>
                  ) : null}
                </div>
              ) : null}
              <input
                value={selected.name}
                onChange={(e) =>
                  setStore((s) => kbRenameNode(s, selected.id, e.target.value))
                }
                style={{
                  width: "100%",
                  border: "none",
                  outline: "none",
                  fontSize: 24,
                  fontWeight: 700,
                  color: "var(--ink-900)",
                  marginBottom: 14,
                  background: "transparent",
                }}
              />
              {selected.type === "doc" ? (
                <KnowledgeDocEditor
                  key={selected.id}
                  doc={selected}
                  onChange={(md) => setStore((s) => kbSetContent(s, selected.id, md))}
                />
              ) : (
                <KnowledgeFolderView
                  store={store}
                  folder={selected}
                  onOpen={(n) => selectNode(n)}
                  onAdd={(type) => addChild(selected.id, type)}
                />
              )}
            </>
          ) : (
            <EmptyHint title="选择左侧文档" hint="或新建页面 / 文件夹组织你的知识库。" />
          )}
        </div>
      </div>

      {/* Node context menu */}
      {menu && menuNode && (
        <>
          <div
            onMouseDown={() => setMenu(null)}
            onContextMenu={(e) => {
              e.preventDefault();
              setMenu(null);
            }}
            style={{ position: "fixed", inset: 0, zIndex: 90 }}
          />
          <div
            style={{
              position: "fixed",
              left: Math.min(menu.x, (typeof window !== "undefined" ? window.innerWidth : 1200) - 200),
              top: Math.min(menu.y, (typeof window !== "undefined" ? window.innerHeight : 800) - 240),
              zIndex: 91,
              background: "#fff",
              border: "1px solid var(--line)",
              borderRadius: 8,
              boxShadow: "0 12px 32px rgba(15,23,42,0.18)",
              padding: 6,
              minWidth: 168,
            }}
          >
            {menuNode.type === "folder" && (
              <>
                <KbMenuItem
                  onClick={() => addChild(menuNode.id, "doc")}
                  close={() => setMenu(null)}
                >
                  新建页面
                </KbMenuItem>
                <KbMenuItem
                  onClick={() => addChild(menuNode.id, "folder")}
                  close={() => setMenu(null)}
                >
                  新建文件夹
                </KbMenuItem>
              </>
            )}
            <KbMenuItem
              onClick={() => setRenamingId(menuNode.id)}
              close={() => setMenu(null)}
            >
              重命名
            </KbMenuItem>
            {!menuNode.system && (
              <KbMenuItem onClick={() => setMoveId(menuNode.id)} close={() => setMenu(null)}>
                移动到…
              </KbMenuItem>
            )}
            {!menuNode.system && (
              <KbMenuItem
                danger
                onClick={() => {
                  setStore((s) => kbDeleteNode(s, menuNode.id));
                  if (selectedId === menuNode.id) setSelectedId(KB_REVIEW_FOLDER_ID);
                }}
                close={() => setMenu(null)}
              >
                删除
              </KbMenuItem>
            )}
          </div>
        </>
      )}

      {/* Move picker */}
      {moveId && (
        <div
          onMouseDown={() => setMoveId(null)}
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(15,23,42,0.4)",
            zIndex: 95,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            onMouseDown={(e) => e.stopPropagation()}
            style={{
              width: 360,
              maxHeight: "70vh",
              overflowY: "auto",
              background: "#fff",
              borderRadius: 10,
              padding: 14,
              boxShadow: "0 20px 50px rgba(15,23,42,0.25)",
            }}
          >
            <div style={{ fontWeight: 600, marginBottom: 10 }}>移动到…</div>
            {folderOptions
              .filter(
                (f) =>
                  f.id !== moveId &&
                  !kbDescendants(store, moveId).includes(f.id) &&
                  store.nodes[moveId]?.parentId !== f.id,
              )
              .map((f) => (
                <button
                  key={f.id}
                  type="button"
                  onClick={() => {
                    setStore((s) => kbMoveNode(s, moveId, f.id));
                    setMoveId(null);
                  }}
                  style={{
                    display: "block",
                    width: "100%",
                    textAlign: "left",
                    border: "none",
                    background: "transparent",
                    padding: "8px 10px",
                    borderRadius: 6,
                    cursor: "pointer",
                    fontSize: 13,
                    color: "var(--ink-700)",
                  }}
                  onMouseEnter={(e) => (e.currentTarget.style.background = "var(--bg-soft)")}
                  onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
                >
                  {kbPath(store, f.id).map((p) => p.name).join(" / ")}
                </button>
              ))}
          </div>
        </div>
      )}
    </>
  );
}

const kbIconBtn = {
  border: "none",
  background: "transparent",
  color: "var(--ink-400)",
  cursor: "pointer",
  fontSize: 13,
  width: 20,
  height: 20,
  borderRadius: 4,
  padding: 0,
  lineHeight: 1,
};

function KbMenuItem({ children, onClick, close, danger }) {
  return (
    <button
      type="button"
      onMouseDown={(e) => {
        e.preventDefault();
        onClick();
        close?.();
      }}
      onMouseEnter={(e) => (e.currentTarget.style.background = "var(--bg-soft)")}
      onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
      style={{
        display: "block",
        width: "100%",
        textAlign: "left",
        border: "none",
        background: "transparent",
        padding: "7px 8px",
        borderRadius: 6,
        cursor: "pointer",
        fontSize: 13,
        color: danger ? "var(--danger-600)" : "var(--ink-700)",
      }}
    >
      {children}
    </button>
  );
}

function KnowledgeFolderView({ store, folder, onOpen, onAdd }) {
  const kids = kbChildren(store, folder.id);
  return (
    <div>
      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        <Button size="sm" kind="default" onClick={() => onAdd("doc")}>
          + 新建页面
        </Button>
        <Button size="sm" kind="default" onClick={() => onAdd("folder")}>
          + 新建文件夹
        </Button>
      </div>
      {kids.length === 0 ? (
        <EmptyHint title="空文件夹" hint="新建页面或文件夹，或在任务详情完成复盘后自动归档到这里。" />
      ) : (
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))",
            gap: 10,
          }}
        >
          {kids.map((k) => (
            <button
              key={k.id}
              type="button"
              onClick={() => onOpen(k)}
              style={{
                textAlign: "left",
                border: "1px solid var(--line)",
                borderRadius: 8,
                padding: 12,
                background: "#fff",
                cursor: "pointer",
              }}
            >
              <div style={{ fontSize: 18, marginBottom: 6 }}>
                {k.type === "folder" ? "📁" : "📄"}
              </div>
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 600,
                  color: "var(--ink-900)",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                }}
              >
                {k.name}
              </div>
              <div style={{ fontSize: 11, color: "var(--ink-400)", marginTop: 4 }}>
                {k.type === "folder"
                  ? `${kbChildren(store, k.id).length} 项`
                  : "复盘文档"}
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function LiveReviewDrawer({
  task,
  project,
  streamer,
  streamerName,
  projectName,
  onClose,
}) {
  const dialogRef = React.useRef(null);
  const closeButtonRef = React.useRef(null);
  const reviewContext = React.useMemo(() => {
    const day = SCHEDULE_WEEK?.days?.[task.dayIdx];
    return {
      reviewDate: day?.date || "",
      sessionLabel: task.name || "",
      product: projectName || "",
      server: project?.serverLabel || "",
      streamer: streamerName || "",
      platform: streamer?.platforms?.[0] || "",
      liveWindow:
        task.startHour != null && task.endHour != null
          ? `${formatHour(task.startHour)} – ${formatHour(task.endHour)}`
          : "",
      goal: "",
    };
  }, [task, project, streamer, streamerName, projectName]);

  const [blocks, setBlocks] = React.useState(() =>
    parseMarkdownToBlocks(buildLiveReviewTemplate(reviewContext)),
  );
  // mode: "edit" = block (Notion-like) editor, "source" = raw Markdown
  const [mode, setMode] = React.useState("edit");
  const [rawDraft, setRawDraft] = React.useState("");
  const [assist, setAssist] = React.useState(null);

  const currentMarkdown = () =>
    mode === "source" ? rawDraft : serializeBlocksToMarkdown(blocks);

  const switchMode = (next) => {
    if (next === mode) return;
    if (next === "source") {
      setRawDraft(serializeBlocksToMarkdown(blocks));
    } else {
      setBlocks(parseMarkdownToBlocks(rawDraft));
    }
    setMode(next);
  };
  const [assistBusy, setAssistBusy] = React.useState(false);
  const [saveBusy, setSaveBusy] = React.useState(false);
  const [message, setMessage] = React.useState("");
  const [error, setError] = React.useState("");

  useModalLayerIsolation(dialogRef);

  React.useLayoutEffect(() => {
    closeButtonRef.current?.focus();
  }, []);

  const handleReviewKeyDown = (event) => {
    if (event.key === "Tab" || event.key === "Escape") {
      event.stopPropagation();
    }
    if (event.key === "Escape") {
      event.preventDefault();
      onClose?.();
      return;
    }
    if (event.key !== "Tab") return;

    const dialogElement = dialogRef.current;
    if (!dialogElement) return;
    const focusable = Array.from(
      dialogElement.querySelectorAll(OPS_FOCUSABLE_SELECTOR),
    ).filter((element) => isVisiblyTabbableWithin(element, dialogElement));
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (!first || !last) {
      event.preventDefault();
      return;
    }

    const activeElement = globalThis.document?.activeElement;
    if (event.shiftKey) {
      if (activeElement === first || !dialogElement.contains(activeElement)) {
        event.preventDefault();
        last.focus();
      }
      return;
    }
    if (activeElement === last || !dialogElement.contains(activeElement)) {
      event.preventDefault();
      first.focus();
    }
  };

  const assistInput = {
    product: reviewContext.product,
    platform: reviewContext.platform,
    streamer: reviewContext.streamer,
    goal: reviewContext.goal,
  };

  const runAssist = async () => {
    if (assistBusy) return;
    setAssistBusy(true);
    setError("");
    try {
      const response = await globalThis.fetch("/api/live-review/assist", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(assistInput),
      });
      if (!response.ok) throw new Error("server");
      const payload = await response.json();
      setAssist({ ...payload, source: "server" });
    } catch {
      // Offline / unauthenticated fallback: learn from the local knowledge base.
      const docs = readLocalReviewDocs().map((doc) => ({
        contentMd: doc.contentMd,
      }));
      const knowledge = aggregateReviewKnowledge(docs);
      const built = buildReviewAssist(knowledge, assistInput);
      setAssist({ knowledge, assist: built, source: "local" });
    } finally {
      setAssistBusy(false);
    }
  };

  const insertAssist = () => {
    const blockMd = assist?.assist?.assistMarkdown;
    if (!blockMd) return;
    if (mode === "source") {
      setRawDraft((prev) => `${blockMd}\n${prev}`);
    } else {
      setBlocks((prev) => [...parseMarkdownToBlocks(blockMd), ...prev]);
    }
    setMessage("已将 AI 复盘助手建议插入到复盘顶部。");
  };

  const save = async () => {
    if (saveBusy) return;
    const content = currentMarkdown();
    if (!content.trim()) {
      setError("复盘内容不能为空。");
      return;
    }
    setSaveBusy(true);
    setError("");
    setMessage("");
    const title =
      `${projectName || "项目"} · ${reviewContext.reviewDate || "复盘"} · ${streamerName || ""}`.trim();
    const body = {
      title,
      contentMd: content,
      product: reviewContext.product || undefined,
      platform: reviewContext.platform || undefined,
    };
    if (UUID_RE.test(task.projectId || "")) body.projectId = task.projectId;
    if (UUID_RE.test(task.streamerId || "")) body.streamerId = task.streamerId;
    if (UUID_RE.test(task.id || "")) body.liveTaskId = task.id;

    // 自动归档到「知识库 → 直属库 / 复盘 / 项目 / 主播 / 复盘文件」（腾讯云 COS）。
    try {
      await archiveReviewToKnowledgeBase({
        date: reviewContext.reviewDate,
        streamer: streamerName,
        product: reviewContext.product || projectName,
        contentMd: content,
        projectId: task.projectId,
        streamerId: task.streamerId,
      });
    } catch {
      /* 归档失败不阻断保存主流程 */
    }

    try {
      const response = await globalThis.fetch("/api/live-review/documents", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      if (!response.ok) throw new Error("server");
      setMessage(
        "已保存并归档到知识库（复盘 / 项目 / 主播），AI 将在后续复盘中学习复用。",
      );
    } catch {
      // Persist locally so the prototype knowledge base + AI assist keep working.
      writeLocalReviewDoc({
        id: `local-${task.id}-${content.length}`,
        title,
        contentMd: content,
        product: reviewContext.product || null,
        platform: reviewContext.platform || null,
      });
      setMessage(
        "已归档到知识库（离线/未登录），AI 复盘助手将基于本地知识库学习。",
      );
    } finally {
      setSaveBusy(false);
    }
  };

  const knowledge = assist?.knowledge;
  const built = assist?.assist;

  const dialog = (
    <div
      ref={dialogRef}
      className="ops-live-review-overlay"
      role="dialog"
      aria-modal="true"
      aria-label="直播复盘"
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(15,23,42,0.45)",
        zIndex: 60,
        display: "flex",
        justifyContent: "center",
        alignItems: "stretch",
        padding: "32px 24px",
        boxSizing: "border-box",
        overflow: "hidden",
      }}
      onClick={onClose}
      onKeyDown={handleReviewKeyDown}
    >
      <style>{`
        .md-preview { font-size: 13px; color: var(--ink-700); line-height: 1.7; }
        .md-preview h2 { font-size: 18px; margin: 8px 0 12px; color: var(--ink-900); }
        .md-preview h3 { font-size: 15px; margin: 16px 0 8px; color: var(--ink-900); }
        .md-preview h4 { font-size: 13px; margin: 12px 0 6px; color: var(--ink-900); }
        .md-preview ul, .md-preview ol { margin: 6px 0 6px 18px; }
        .md-preview li { margin: 2px 0; }
        .md-preview blockquote { margin: 10px 0; padding: 8px 12px; background: var(--bg-soft); border-left: 3px solid var(--blue-600); border-radius: 4px; color: var(--ink-700); }
        .md-preview table { border-collapse: collapse; width: 100%; margin: 8px 0; font-size: 12.5px; }
        .md-preview th, .md-preview td { border: 1px solid var(--line); padding: 6px 10px; text-align: left; vertical-align: top; }
        .md-preview th { background: var(--bg-soft); font-weight: 600; color: var(--ink-900); }
        .md-preview strong { color: var(--ink-900); }
        @media (max-width: 720px) {
          .ops-live-review-overlay { padding: 8px !important; }
          .ops-live-review-panel {
            width: 100% !important;
            max-width: 100%;
            height: 100%;
            max-height: 100%;
            border-radius: 8px !important;
          }
          .ops-live-review-header {
            height: auto !important;
            min-height: 56px;
            padding: 8px 10px !important;
            flex-wrap: wrap;
          }
          .ops-live-review-meta {
            flex: 1 1 150px;
            min-width: 0;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
          }
          .ops-live-review-header-spacer { display: none; }
          .ops-live-review-modes { margin-left: auto; max-width: calc(100% - 42px); }
          .ops-live-review-body {
            width: 100%;
            min-width: 0;
            min-height: 0;
            flex-direction: column;
            overflow-y: auto;
          }
          .ops-live-review-editor {
            width: 100%;
            min-height: 280px;
            height: min(46dvh, 380px);
            flex: 0 0 auto !important;
            box-sizing: border-box;
            border-right: none !important;
            border-bottom: 1px solid var(--line);
          }
          .ops-live-review-editor > * { max-width: 100%; }
          .ops-live-review-sidebar {
            width: 100% !important;
            max-height: min(32dvh, 260px);
            flex: 0 0 auto !important;
            box-sizing: border-box;
          }
          .ops-live-review-footer { flex-wrap: wrap; }
          .ops-live-review-footer-message { flex-basis: 100%; }
        }
      `}</style>
      <div
        className="ops-live-review-panel"
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "min(1040px, 100%)",
          maxWidth: "100%",
          maxHeight: "100%",
          background: "#fff",
          borderRadius: 12,
          boxShadow: "0 24px 60px rgba(15,23,42,0.25)",
          display: "flex",
          flexDirection: "column",
          overflow: "hidden",
        }}
      >
        {/* Header */}
        <div
          className="ops-live-review-header"
          style={{
            height: 56,
            padding: "0 16px",
            borderBottom: "1px solid var(--line)",
            display: "flex",
            alignItems: "center",
            gap: 12,
          }}
        >
          <Icon.Sparkles size={16} stroke="var(--violet-600)" />
          <div style={{ fontWeight: 600, color: "var(--ink-900)" }}>
            直播复盘
          </div>
          <span
            className="ops-live-review-meta"
            style={{ fontSize: 12, color: "var(--ink-400)" }}
          >
            {projectName} · {streamerName}
          </span>
          <div className="ops-live-review-header-spacer" style={{ flex: 1 }} />
          <div
            className="ops-live-review-modes"
            style={{
              display: "inline-flex",
              border: "1px solid var(--line)",
              borderRadius: 8,
              overflow: "hidden",
            }}
          >
            {[
              { key: "edit", label: "编辑" },
              { key: "source", label: "Markdown" },
            ].map((tab) => (
              <button
                key={tab.key}
                onClick={() => switchMode(tab.key)}
                style={{
                  border: "none",
                  cursor: "pointer",
                  padding: "6px 14px",
                  fontSize: 12.5,
                  background:
                    mode === tab.key ? "var(--blue-600)" : "transparent",
                  color: mode === tab.key ? "#fff" : "var(--ink-700)",
                }}
              >
                {tab.label}
              </button>
            ))}
          </div>
          <button
            ref={closeButtonRef}
            type="button"
            aria-label="关闭直播复盘"
            title="关闭直播复盘"
            onClick={onClose}
            style={{
              width: 30,
              height: 30,
              borderRadius: 6,
              border: "none",
              background: "transparent",
              cursor: "pointer",
              color: "var(--ink-400)",
            }}
          >
            <Icon.X size={16} />
          </button>
        </div>

        {/* Body: editor/preview + AI sidebar */}
        <div
          className="ops-live-review-body"
          style={{ flex: 1, display: "flex", minHeight: 0 }}
        >
          <div
            className="ops-live-review-editor"
            style={{
              flex: 1,
              minWidth: 0,
              padding: 16,
              overflowY: "auto",
              borderRight: "1px solid var(--line)",
            }}
          >
            {mode === "source" ? (
              <textarea
                value={rawDraft}
                onChange={(e) => setRawDraft(e.target.value)}
                spellCheck={false}
                style={{
                  width: "100%",
                  minHeight: 460,
                  height: "100%",
                  resize: "vertical",
                  border: "1px solid var(--line)",
                  borderRadius: 8,
                  padding: 12,
                  fontSize: 12.5,
                  lineHeight: 1.7,
                  fontFamily:
                    "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace",
                  color: "var(--ink-900)",
                  outline: "none",
                }}
              />
            ) : (
              <BlockEditor blocks={blocks} onChange={setBlocks} />
            )}
          </div>

          {/* AI assistant sidebar */}
          <div
            className="ops-live-review-sidebar"
            style={{
              width: 320,
              flexShrink: 0,
              padding: 16,
              overflowY: "auto",
              background: "var(--bg-soft)",
              display: "flex",
              flexDirection: "column",
              gap: 12,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
              }}
            >
              <Icon.Sparkles size={14} stroke="var(--violet-600)" />
              <span style={{ fontWeight: 600, color: "var(--ink-900)" }}>
                AI 复盘助手
              </span>
            </div>
            <div style={{ fontSize: 12, color: "var(--ink-400)" }}>
              接入组织复盘知识库，汇聚复发问题与可复制打法，辅助本场复盘。
            </div>
            <Button
              size="sm"
              kind="primary"
              icon={<Icon.Sparkles size={13} />}
              onClick={runAssist}
              disabled={assistBusy}
            >
              {assistBusy ? "学习中…" : "调用知识库辅助"}
            </Button>

            {built ? (
              <div
                style={{ display: "flex", flexDirection: "column", gap: 12 }}
              >
                <div style={{ fontSize: 11, color: "var(--ink-400)" }}>
                  已学习 {built.sampleSize} 份历史复盘
                  {assist.source === "local"
                    ? "（本地知识库）"
                    : "（组织知识库）"}
                </div>
                {built.sampleSize > 0 ? (
                  <>
                    <ReviewAssistList
                      title="⚠️ 复发问题预警"
                      items={built.watchOuts}
                      tone="var(--danger-600)"
                    />
                    <ReviewAssistList
                      title="✅ 可复制打法"
                      items={built.reusableWins}
                      tone="var(--ok-600)"
                    />
                    <ReviewAssistList
                      title="🎯 本场建议"
                      items={built.suggestions}
                      tone="var(--blue-700)"
                    />
                    <Button size="sm" kind="default" onClick={insertAssist}>
                      插入到复盘正文
                    </Button>
                  </>
                ) : (
                  <div
                    style={{
                      fontSize: 12,
                      color: "var(--ink-400)",
                      padding: 10,
                      border: "1px dashed var(--line)",
                      borderRadius: 8,
                    }}
                  >
                    知识库暂无历史复盘，本场保存后即可开始沉淀经验。
                  </div>
                )}
              </div>
            ) : null}
          </div>
        </div>

        {/* Footer */}
        <div
          className="ops-live-review-footer"
          style={{
            padding: 12,
            borderTop: "1px solid var(--line)",
            display: "flex",
            alignItems: "center",
            gap: 12,
          }}
        >
          <div
            className="ops-live-review-footer-message"
            style={{ flex: 1, fontSize: 12 }}
          >
            {error ? (
              <span style={{ color: "var(--danger-600)" }}>{error}</span>
            ) : message ? (
              <span style={{ color: "var(--ok-600)" }}>{message}</span>
            ) : (
              <span style={{ color: "var(--ink-400)" }}>
                编辑模式为 Markdown，保存后写入组织知识库。
              </span>
            )}
          </div>
          <Button kind="ghost" onClick={onClose}>
            关闭
          </Button>
          <Button
            kind="primary"
            icon={<Icon.Upload size={14} />}
            onClick={save}
            disabled={saveBusy}
          >
            {saveBusy ? "保存中…" : "保存到组织知识库"}
          </Button>
        </div>
      </div>
    </div>
  );

  if (typeof document === "undefined") return dialog;
  return createPortal(dialog, document.body);
}

function ReviewAssistList({ title, items, tone }) {
  if (!items || items.length === 0) return null;
  return (
    <div>
      <div
        style={{
          fontSize: 12,
          fontWeight: 600,
          color: tone || "var(--ink-900)",
          marginBottom: 6,
        }}
      >
        {title}
      </div>
      <ul style={{ margin: 0, paddingLeft: 16 }}>
        {items.map((item, i) => (
          <li
            key={i}
            style={{
              fontSize: 12,
              color: "var(--ink-700)",
              lineHeight: 1.6,
              marginBottom: 4,
            }}
          >
            {item}
          </li>
        ))}
      </ul>
    </div>
  );
}

function NewTaskDrawer({
  task,
  projects = [],
  streamers = [],
  applications = [],
  onClose,
  onCreateTask,
}) {
  const [selectedProjectId, setSelectedProjectId] = React.useState(
    task.projectId || projects[0]?.id || "",
  );
  const [selectedStreamerId, setSelectedStreamerId] = React.useState(
    task.streamerId || streamers[0]?.id || "",
  );
  const [startTime, setStartTime] = React.useState(
    decimalHourToTime(task.startHour ?? 20),
  );
  const [endTime, setEndTime] = React.useState(
    decimalHourToTime(task.endHour ?? 23.5),
  );
  const [taskType, setTaskType] = React.useState(
    normalizeTaskType(task.type || "project"),
  );
  const [note, setNote] = React.useState("");
  const p = projects.find((x) => x.id === selectedProjectId) || projects[0];
  const eligibleStreamers = p
    ? joinedStreamersForProject(p.id, streamers, applications)
    : [];
  const pendingConfirmApplications = p
    ? applications.filter(
        (application) =>
          isConfirmableRosterApplication(application.status) &&
          applicationBelongsToProject(application, p),
      )
    : [];
  const joinedRequirementMessage =
    pendingConfirmApplications.length > 0
      ? `该项目有 ${pendingConfirmApplications.length} 位待确认主播，请先到项目详情的主播阵容点击确认加入后再排班。`
      : JOINED_STREAMER_REQUIRED_MESSAGE;
  const s = eligibleStreamers.find((x) => x.id === selectedStreamerId) || null;
  const projectName = p?.name || task.projectName || task.project || "";
  const [busy, setBusy] = React.useState(false);
  const [draftMessage, setDraftMessage] = React.useState("");
  React.useEffect(() => {
    const project =
      projects.find((x) => x.id === selectedProjectId) || projects[0];
    const nextEligibleStreamers = project
      ? joinedStreamersForProject(project.id, streamers, applications)
      : [];
    if (
      !nextEligibleStreamers.some(
        (streamer) => streamer.id === selectedStreamerId,
      )
    ) {
      setSelectedStreamerId(nextEligibleStreamers[0]?.id || "");
    }
  }, [
    applications,
    projects,
    selectedProjectId,
    selectedStreamerId,
    streamers,
  ]);
  const handleCreate = async () => {
    if (!onCreateTask || !p) {
      setDraftMessage("请先选择项目。");
      return;
    }
    if (!s) {
      setDraftMessage("");
      return;
    }
    const startHour = timeValueToDecimalHour(startTime, 20);
    const endHour = timeValueToDecimalHour(endTime, 23.5);
    if (endHour <= startHour) {
      setDraftMessage("计划结束时间必须晚于开播时间。");
      return;
    }
    setBusy(true);
    setDraftMessage("");
    try {
      await onCreateTask(
        opsLiveTaskInput({
          projectId: p.id,
          streamerId: s.id,
          dayIdx: task.dayIdx,
          startHour,
          endHour,
          type: taskType,
          note: note.trim() || "经营端页面创建任务",
          projects,
          streamers: eligibleStreamers,
        }),
      );
    } finally {
      setBusy(false);
    }
  };

  return (
    <Drawer onClose={onClose} title="新建任务">
      <div
        style={{
          padding: 20,
          display: "flex",
          flexDirection: "column",
          gap: 14,
        }}
      >
        <TaskFormLabel label="所属项目">
          <select
            value={p?.id || ""}
            onChange={(event) => setSelectedProjectId(event.target.value)}
            style={taskInputStyle}
          >
            {projects.map((project) => (
              <option key={project.id} value={project.id}>
                {project.name}
              </option>
            ))}
          </select>
        </TaskFormLabel>
        <TaskFormLabel label="主播">
          <select
            value={s?.id || ""}
            onChange={(event) => setSelectedStreamerId(event.target.value)}
            style={taskInputStyle}
            disabled={eligibleStreamers.length === 0}
          >
            {eligibleStreamers.length > 0 ? (
              eligibleStreamers.map((streamer) => (
                <option key={streamer.id} value={streamer.id}>
                  {streamer.alias}
                </option>
              ))
            ) : (
              <option value="">暂无已加入主播</option>
            )}
          </select>
        </TaskFormLabel>
        {eligibleStreamers.length === 0 ? (
          <div
            aria-live="polite"
            style={{ fontSize: 12, color: "var(--danger-600)" }}
          >
            {joinedRequirementMessage}
          </div>
        ) : null}
        <FormField label="任务类型">
          <SegmentedControl
            options={TASK_TYPE_OPTIONS}
            value={taskType}
            onChange={setTaskType}
          />
        </FormField>
        <div
          style={{
            padding: "8px 10px",
            border: "1px solid var(--line)",
            borderRadius: 8,
            background: "var(--bg-soft)",
            fontSize: 12,
            color: "var(--ink-600)",
            display: "flex",
            flexDirection: "column",
            gap: 4,
          }}
        >
          <span>
            项目映射：{projectName || "未选择项目"} · {p?.code || "未设置编号"}
          </span>
          <span>
            负责人：{p?.leadOps || "未分配"} · 周期：{p?.start || "未配置"} →{" "}
            {p?.end || "未配置"}
          </span>
        </div>
        <div
          style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}
        >
          <TaskFormLabel label="计划开播">
            <input
              type="time"
              value={startTime}
              onChange={(event) => setStartTime(event.target.value)}
              style={taskInputStyle}
            />
          </TaskFormLabel>
          <TaskFormLabel label="计划结束">
            <input
              type="time"
              value={endTime}
              onChange={(event) => setEndTime(event.target.value)}
              style={taskInputStyle}
            />
          </TaskFormLabel>
        </div>
        <TaskFormLabel label="任务说明（可选）">
          <textarea
            value={note}
            onChange={(event) => setNote(event.target.value)}
            placeholder="特殊要求、口径备注等"
            style={{
              width: "100%",
              minHeight: 72,
              padding: "8px 10px",
              border: "1px solid var(--line-strong)",
              borderRadius: 6,
              fontSize: 13,
              color: "var(--ink-700)",
              fontFamily: "inherit",
              resize: "vertical",
            }}
          />
        </TaskFormLabel>
        {draftMessage ? (
          <div
            aria-live="polite"
            style={{ fontSize: 12, color: "var(--ink-500)" }}
          >
            {draftMessage}
          </div>
        ) : null}
      </div>
      <div
        style={{
          padding: 12,
          borderTop: "1px solid var(--line)",
          background: "var(--bg-soft)",
          display: "flex",
          gap: 8,
          justifyContent: "flex-end",
        }}
      >
        <Button kind="default" onClick={onClose}>
          取消
        </Button>
        <Button
          kind="default"
          onClick={() => setDraftMessage("任务草稿保存后台暂未接入。")}
        >
          保存草稿
        </Button>
        <Button kind="primary" onClick={handleCreate} disabled={busy}>
          {busy ? "创建中…" : "创建任务"}
        </Button>
      </div>
    </Drawer>
  );
}

function FormField({ label, children }) {
  return (
    <div>
      <div
        style={{
          fontSize: 12,
          color: "var(--ink-500)",
          marginBottom: 6,
          fontWeight: 500,
        }}
      >
        {label}
      </div>
      {children}
    </div>
  );
}

function SegmentedControl({ options, value, onChange }) {
  const normalizedOptions = options.map((option) =>
    typeof option === "string" ? { value: option, label: option } : option,
  );
  return (
    <div style={{ display: "flex", gap: 6 }}>
      {normalizedOptions.map((option) => (
        <button
          key={option.value}
          type="button"
          aria-pressed={option.value === value}
          onClick={() => onChange?.(option.value)}
          style={{
            flex: 1,
            height: 30,
            fontSize: 12,
            background: option.value === value ? "var(--blue-50)" : "#fff",
            border: `1px solid ${
              option.value === value ? "var(--blue-500)" : "var(--line-strong)"
            }`,
            color:
              option.value === value ? "var(--blue-700)" : "var(--ink-500)",
            borderRadius: 6,
            cursor: "pointer",
            fontWeight: option.value === value ? 600 : 500,
          }}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

function DrawerStat({ label, value }) {
  return (
    <div
      style={{
        padding: 12,
        background: "var(--bg-soft)",
        border: "1px solid var(--line)",
        borderRadius: 8,
      }}
    >
      <div style={{ fontSize: 11, color: "var(--ink-400)" }}>{label}</div>
      <div
        className="num"
        style={{
          fontSize: 14,
          fontWeight: 600,
          color: "var(--ink-900)",
          marginTop: 4,
        }}
      >
        {value}
      </div>
    </div>
  );
}

function Timeline({ events }) {
  return (
    <div style={{ display: "flex", flexDirection: "column" }}>
      {events.map((e, i) => (
        <div
          key={i}
          style={{
            display: "flex",
            gap: 12,
            paddingBottom: i < events.length - 1 ? 14 : 0,
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
            }}
          >
            <span
              style={{
                width: 14,
                height: 14,
                borderRadius: 999,
                background: e.current
                  ? "var(--blue-600)"
                  : e.done
                    ? "var(--ok-600)"
                    : "var(--ink-100)",
                border: `2px solid ${e.current ? "var(--blue-600)" : e.done ? "var(--ok-600)" : "#fff"}`,
                boxShadow: e.current
                  ? "0 0 0 3px rgba(30,80,200,0.18)"
                  : "none",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {e.done && !e.current && <Icon.Check size={9} stroke="#fff" />}
            </span>
            {i < events.length - 1 && (
              <span
                style={{
                  flex: 1,
                  width: 1.5,
                  background: e.done ? "var(--ok-600)" : "var(--ink-100)",
                  marginTop: 2,
                }}
              />
            )}
          </div>
          <div style={{ flex: 1, paddingTop: 1 }}>
            <div
              style={{
                fontSize: 12.5,
                fontWeight: 500,
                color:
                  e.done || e.current ? "var(--ink-900)" : "var(--ink-400)",
              }}
            >
              {e.action}
            </div>
            <div
              style={{ fontSize: 11, color: "var(--ink-400)", marginTop: 2 }}
            >
              {e.who}{" "}
              <span style={{ marginLeft: 6 }} className="num">
                {e.time}
              </span>
              {e.current && (
                <Badge tone="blue" style={{ marginLeft: 6 }}>
                  当前
                </Badge>
              )}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

function Drawer({ children, onClose, onKeyDown, suspended = false, title }) {
  const layerRef = React.useRef(null);
  const drawerRef = React.useRef(null);
  const closeButtonRef = React.useRef(null);
  const openerRef = React.useRef(null);
  const titleId = React.useId();

  const setLayerRef = React.useCallback((element) => {
    if (element && !layerRef.current) {
      const activeElement = globalThis.document?.activeElement;
      if (
        activeElement &&
        activeElement !== globalThis.document?.body &&
        !element.contains(activeElement)
      ) {
        openerRef.current = activeElement;
      }
    }
    layerRef.current = element;
  }, []);

  const focusDrawer = React.useCallback(() => {
    const drawerElement = drawerRef.current;
    if (!drawerElement?.contains(globalThis.document?.activeElement)) {
      closeButtonRef.current?.focus();
    }
  }, []);

  const restoreDrawerFocus = React.useCallback(() => {
    const opener = openerRef.current;
    openerRef.current = null;
    if (isRestorableFocusTarget(opener)) opener.focus();
  }, []);

  useModalLayerIsolation(layerRef, focusDrawer, restoreDrawerFocus);

  const handleDrawerKeyDown = (event) => {
    const sourceDialog = event.target?.closest?.('[role="dialog"]');
    if (sourceDialog && sourceDialog !== event.currentTarget) return;

    if (event.key === "Tab" || event.key === "Escape") {
      event.stopPropagation();
    }
    onKeyDown?.(event);
    if (event.defaultPrevented) return;

    if (event.key === "Escape") {
      event.preventDefault();
      onClose?.();
      return;
    }
    if (event.key !== "Tab") return;

    const drawerElement = drawerRef.current;
    if (!drawerElement) return;
    const focusable = Array.from(
      drawerElement.querySelectorAll(OPS_FOCUSABLE_SELECTOR),
    ).filter((element) => isVisiblyTabbableWithin(element, drawerElement));
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (!first || !last) {
      event.preventDefault();
      return;
    }

    const activeElement = globalThis.document?.activeElement;
    if (event.shiftKey) {
      if (activeElement === first || !drawerElement.contains(activeElement)) {
        event.preventDefault();
        last.focus();
      }
      return;
    }
    if (activeElement === last || !drawerElement.contains(activeElement)) {
      event.preventDefault();
      first.focus();
    }
  };

  const layer = (
    <div
      ref={setLayerRef}
      className="ops-drawer-layer"
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 50,
      }}
    >
      <button
        type="button"
        aria-label="关闭抽屉遮罩"
        tabIndex={-1}
        onClick={onClose}
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          padding: 0,
          border: "none",
          borderRadius: 0,
          background: "rgba(15,23,42,0.24)",
          cursor: "pointer",
        }}
      />
      <div
        ref={drawerRef}
        role="dialog"
        aria-modal={suspended ? undefined : "true"}
        aria-labelledby={titleId}
        onKeyDown={handleDrawerKeyDown}
        style={{
          position: "absolute",
          top: 0,
          right: 0,
          bottom: 0,
          width: 460,
          maxWidth: "100vw",
          boxSizing: "border-box",
          background: "#fff",
          borderLeft: "1px solid var(--line)",
          boxShadow: "-8px 0 24px rgba(15,23,42,0.08)",
          display: "flex",
          flexDirection: "column",
          zIndex: 1,
        }}
      >
        <div
          style={{
            height: 56,
            padding: "0 16px",
            borderBottom: "1px solid var(--line)",
            display: "flex",
            alignItems: "center",
            gap: 10,
          }}
        >
          <div id={titleId} style={{ flex: 1, minWidth: 0 }}>
            {title}
          </div>
          <button
            ref={closeButtonRef}
            type="button"
            aria-label="关闭"
            title="关闭"
            onClick={onClose}
            style={{
              width: 30,
              height: 30,
              borderRadius: 6,
              border: "none",
              background: "transparent",
              cursor: "pointer",
              color: "var(--ink-400)",
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Icon.X size={16} />
          </button>
        </div>
        <div style={{ flex: 1, overflowY: "auto" }}>{children}</div>
      </div>
    </div>
  );

  if (typeof document === "undefined") return layer;
  return createPortal(layer, document.body);
}

