function StatusEditDrawer({ member, onClose, onSubmit }) {
  const nextStatus = member.status === "suspended" ? "active" : "suspended";
  const isSuspending = nextStatus === "suspended";
  const [reason, setReason] = React.useState("");
  const [busy, setBusy] = React.useState(false);
  const [message, setMessage] = React.useState("");

  const submit = async () => {
    setBusy(true);
    setMessage("");
    try {
      await onSubmit?.(member.id, { status: nextStatus, reason });
    } catch (error) {
      setMessage(error?.message || "成员状态保存失败。");
    } finally {
      setBusy(false);
    }
  };

  return (
    <Drawer
      title={`${isSuspending ? "停用成员" : "恢复成员"} · ${member.name}`}
      onClose={onClose}
    >
      <div
        style={{
          padding: 16,
          display: "flex",
          flexDirection: "column",
          gap: 14,
        }}
      >
        <div style={{ fontSize: 12, color: "var(--ink-500)" }}>
          {memberIdentityText(member)}
        </div>
        <div
          style={{
            padding: 12,
            borderRadius: 8,
            border: "1px solid var(--line)",
            background: isSuspending ? "#FDECEC" : "var(--ok-50)",
            color: isSuspending ? "var(--danger-600)" : "var(--ok-600)",
            fontSize: 12,
            fontWeight: 600,
          }}
        >
          {isSuspending
            ? "停用后该成员无法继续访问当前组织数据。"
            : "恢复后该成员将按当前角色重新获得组织访问权限。"}
        </div>
        <OrgMemberField label="状态变更原因">
          <textarea
            aria-label="状态变更原因"
            value={reason}
            onChange={(event) => setReason(event.target.value)}
            placeholder="记录停用或恢复原因，写入权限审计日志"
            style={{
              ...orgMemberInputStyle,
              minHeight: 84,
              resize: "vertical",
            }}
          />
        </OrgMemberField>
        {message ? (
          <div
            aria-live="polite"
            style={{ fontSize: 12, color: "var(--danger-600)" }}
          >
            {message}
          </div>
        ) : null}
      </div>
      <div
        style={{
          padding: 12,
          borderTop: "1px solid var(--line)",
          background: "var(--bg-soft)",
          display: "flex",
          justifyContent: "flex-end",
          gap: 8,
        }}
      >
        <Button kind="default" onClick={onClose}>
          取消
        </Button>
        <Button
          kind={isSuspending ? "danger" : "primary"}
          onClick={submit}
          disabled={busy}
        >
          {busy ? "保存中…" : isSuspending ? "确认停用" : "确认恢复"}
        </Button>
      </div>
    </Drawer>
  );
}

function OrgMemberField({ label, children }) {
  return (
    <label style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      <span style={{ fontSize: 12, color: "var(--ink-500)", fontWeight: 500 }}>
        {label}
      </span>
      {children}
    </label>
  );
}

const orgMemberInputStyle = {
  width: "100%",
  height: 34,
  padding: "0 10px",
  border: "1px solid var(--line-strong)",
  borderRadius: 6,
  fontSize: 13,
  color: "var(--ink-700)",
  background: "#fff",
  fontFamily: "inherit",
};

function formatMemberDate(value) {
  if (!value) {
    return "—";
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }

  return formatDateKey(date);
}

function RoleFilter({ value, onChange }) {
  const opts = [
    { key: "all", label: "全部角色" },
    { key: "owner", label: "负责人" },
    { key: "ops_manager", label: "运营负责人" },
    { key: "operator_business", label: "次级运营" },
    { key: "finance", label: "财务" },
  ];
  return (
    <label
      style={{
        height: 32,
        padding: "0 10px",
        border: "1px solid var(--line-strong)",
        borderRadius: 6,
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        background: "#fff",
        fontSize: 12,
        color: "var(--ink-700)",
      }}
    >
      <Icon.Streamer size={13} stroke="var(--ink-500)" />
      <span style={{ color: "var(--ink-400)" }}>角色：</span>
      <select
        value={value}
        aria-label="角色筛选"
        onChange={(event) => onChange(event.target.value)}
        style={{
          border: "none",
          outline: "none",
          background: "transparent",
          fontSize: 12,
          fontWeight: 600,
          color: "var(--ink-700)",
        }}
      >
        {opts.map((option) => (
          <option key={option.key} value={option.key}>
            {option.label}
          </option>
        ))}
      </select>
    </label>
  );
}

function RoleBadge({ role }) {
  const map = {
    owner: { tone: "red", label: "负责人" },
    ops_manager: { tone: "blue", label: "运营负责人" },
    operator_business: { tone: "teal", label: "次级运营" },
    finance: { tone: "violet", label: "财务" },
    streamer: { tone: "neutral", label: "主播" },
  };
  const m = map[role] || map.streamer;
  return (
    <Badge tone={m.tone} dot>
      {m.label}
    </Badge>
  );
}

// ——— Permission Matrix ——————————————————————

function PermMatrix() {
  const roleCols = [
    { key: "o", label: "负责人", sub: "owner", tone: "red" },
    { key: "m", label: "运营负责人", sub: "ops_manager", tone: "blue" },
    { key: "b", label: "次级运营", sub: "operator_business", tone: "teal" },
    { key: "f", label: "财务", sub: "finance", tone: "violet" },
    { key: "s", label: "主播", sub: "streamer", tone: "neutral" },
  ];

  return (
    <div>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: 12,
        }}
      >
        <div>
          <div
            style={{ fontSize: 14, fontWeight: 600, color: "var(--ink-900)" }}
          >
            跨模块 × 角色权限矩阵
          </div>
          <div style={{ fontSize: 12, color: "var(--ink-400)", marginTop: 4 }}>
            该矩阵作为数据库 RLS、服务端字段过滤、前端按钮控制的唯一来源
          </div>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          {Object.entries(PERM_LEVELS)
            .filter(([k]) => k !== "none")
            .map(([k, v]) => (
              <span
                key={k}
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 4,
                  padding: "3px 8px",
                  fontSize: 11,
                  borderRadius: 4,
                  background: v.cell,
                  color: v.fg,
                  fontWeight: 500,
                }}
              >
                <span
                  style={{
                    width: 6,
                    height: 6,
                    borderRadius: 999,
                    background: v.shortColor,
                  }}
                />
                {v.label}
              </span>
            ))}
        </div>
      </div>

      <Card padded={false}>
        <div style={{ overflowX: "auto" }}>
          <table
            style={{
              width: "100%",
              borderCollapse: "separate",
              borderSpacing: 0,
              fontSize: 13,
            }}
          >
            <thead>
              <tr>
                <th
                  style={{
                    ...mthStyle,
                    width: 200,
                    textAlign: "left",
                    position: "sticky",
                    left: 0,
                    zIndex: 2,
                    background: "var(--bg-soft)",
                  }}
                >
                  能力 / 角色
                </th>
                {roleCols.map((c) => (
                  <th key={c.key} style={{ ...mthStyle, textAlign: "center" }}>
                    <div
                      style={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                        gap: 4,
                      }}
                    >
                      <RoleBadge role={c.sub} />
                      <span
                        className="mono"
                        style={{ fontSize: 10, color: "var(--ink-400)" }}
                      >
                        {c.sub}
                      </span>
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {PERM_MATRIX.map((g, gi) => (
                <React.Fragment key={g.group}>
                  <tr>
                    <td
                      colSpan={6}
                      style={{
                        padding: "10px 14px",
                        background: "var(--bg-soft)",
                        fontSize: 11,
                        fontWeight: 600,
                        color: "var(--ink-400)",
                        textTransform: "uppercase",
                        letterSpacing: "0.08em",
                        borderTop: gi > 0 ? "1px solid var(--line)" : "none",
                        borderBottom: "1px solid var(--line)",
                        position: "sticky",
                        left: 0,
                      }}
                    >
                      {g.group}
                    </td>
                  </tr>
                  {g.rows.map((r, ri) => (
                    <tr key={r.feat}>
                      <td
                        style={{
                          ...mtdStyle,
                          position: "sticky",
                          left: 0,
                          background: "#fff",
                          fontWeight: 500,
                          color: "var(--ink-900)",
                        }}
                      >
                        {r.feat}
                      </td>
                      {roleCols.map((c) => (
                        <PermCell key={c.key} level={r[c.key]} />
                      ))}
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}

const mthStyle = {
  padding: "12px 14px",
  fontSize: 12,
  fontWeight: 500,
  color: "var(--ink-400)",
  background: "var(--bg-soft)",
  borderBottom: "1px solid var(--line)",
  position: "sticky",
  top: 0,
};
const mtdStyle = {
  padding: "10px 14px",
  borderBottom: "1px solid var(--line)",
};

function PermCell({ level }) {
  const l = PERM_LEVELS[level] || PERM_LEVELS.none;
  return (
    <td
      style={{
        ...mtdStyle,
        textAlign: "center",
      }}
    >
      {level === "none" ? (
        <Icon.X size={14} stroke="var(--ink-200)" />
      ) : (
        <span
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 4,
            padding: "3px 8px",
            borderRadius: 4,
            background: l.cell,
            color: l.fg,
            fontSize: 11.5,
            fontWeight: 600,
          }}
        >
          {l.label}
        </span>
      )}
    </td>
  );
}

