function PolicyCard({ title, icon, items, accent }) {
  const IconComp = Icon[icon];
  return (
    <Card padded={false}>
      <div
        style={{
          padding: "14px 16px",
          borderBottom: "1px solid var(--line)",
          display: "flex",
          alignItems: "center",
          gap: 10,
        }}
      >
        <span
          style={{
            width: 30,
            height: 30,
            borderRadius: 8,
            background:
              accent === "violet" ? "var(--violet-50)" : "var(--blue-50)",
            color:
              accent === "violet" ? "var(--violet-600)" : "var(--blue-700)",
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <IconComp size={15} />
        </span>
        <div
          style={{
            flex: 1,
            fontSize: 14,
            fontWeight: 600,
            color: "var(--ink-900)",
          }}
        >
          {title}
        </div>
        <Button size="sm" kind="ghost" icon={<Icon.Settings size={12} />}>
          配置
        </Button>
      </div>
      <div>
        {items.map((it, i) => (
          <div
            key={i}
            style={{
              padding: "10px 16px",
              display: "flex",
              alignItems: "center",
              borderBottom:
                i < items.length - 1 ? "1px solid var(--line)" : "none",
            }}
          >
            <span style={{ fontSize: 12.5, color: "var(--ink-500)", flex: 1 }}>
              {it.label}
            </span>
            <span
              style={{
                fontSize: 12,
                fontWeight: 600,
                color:
                  it.tone === "green"
                    ? "var(--ok-600)"
                    : it.tone === "amber"
                      ? "var(--warn-600)"
                      : it.tone === "red"
                        ? "var(--danger-600)"
                        : it.tone === "blue"
                          ? "var(--blue-700)"
                          : "var(--ink-700)",
              }}
            >
              {it.val}
            </span>
          </div>
        ))}
      </div>
    </Card>
  );
}

